window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0154", [{"word":"conscious","ipa_uk":"/ˈkɒnʃəs/","ipa_us":"/ˈkɑːnʃəs/","definition_zh":"清醒的；有知觉的；察觉到的；有意识的；刻意的；对某方面敏感的","definition_en":"awake and able to feel and respond, or aware of something, or done on purpose","core_image":"一间原本熄了灯的房间重新亮起，屋里的人开始看得见桌上的东西，也开始看得见自己","scene":"手术台上，麻醉渐渐退去，病人先是动了动手指，随后能按医生的要求报出自己的名字。The patient stayed conscious through the whole procedure and answered every question.","sceneCN":"这里 conscious 指「处于清醒、能感知并回应外界的状态」（第 1 个义项：清醒并能回应的状态）；句意为病人整台手术期间都保持清醒，并回答了每一个问题。图中可辨识物件：手术灯、监护仪、抬起的指尖。","pos":[{"tag":"adj.","zh":"清醒的；有知觉的；察觉到的；有意识的；刻意的"},{"tag":"adj. (combining form)","zh":"与名词连用，表示对某方面特别在意，如注重健康、注重形象"}],"collocations":[{"phrase":"conscious of","zh":"意识到；察觉到"},{"phrase":"conscious that","zh":"意识到（某事实）"},{"phrase":"become conscious","zh":"恢复知觉；开始察觉"},{"phrase":"conscious effort","zh":"有意识的努力"},{"phrase":"self-conscious","zh":"不自在的；自我意识过强的"},{"phrase":"health-conscious","zh":"注重健康的"}],"forms":[{"label":"比较级（多与 more 连用）","form":"more conscious"},{"label":"最高级（多与 most 连用）","form":"most conscious"},{"label":"副词","form":"consciously"},{"label":"名词（状态）","form":"consciousness"},{"label":"复合形容词","form":"self-conscious"}],"derivatives":[{"word":"consciously","pos":"adv.","zh":"有意识地；刻意地"},{"word":"consciousness","pos":"n.","zh":"意识；知觉；清醒状态"},{"word":"unconscious","pos":"adj.","zh":"失去知觉的；无意识的"},{"word":"subconscious","pos":"adj./n.","zh":"下意识的 / 潜意识"},{"word":"self-conscious","pos":"adj.","zh":"不自在的；过分在意他人眼光的"}],"senses":[{"no":"01","title":"Awake and able to respond","titleCN":"清醒并能回应外界","definition":"awake, able to see, hear and respond to what is happening","definitionCN":"处于清醒状态，能看见、听见并对周围发生的事作出回应","example":"The patient stayed conscious through the whole procedure.","exampleCN":"整个手术过程中病人一直保持清醒。","why":"the oldest English use of conscious is simply 'knowing with oneself', and being awake is the state in which that knowing can happen at all.","whyCN":"conscious 最早的英语用法就是「与己同知」，而清醒正是这种「知」得以发生的状态。"},{"no":"02","title":"Aware of something present","titleCN":"察觉到眼前存在的事物","definition":"noticing something that is present, often through the senses","definitionCN":"注意到眼前存在的事物，通常经由感官获得","example":"She was conscious of a faint smell of smoke in the corridor.","exampleCN":"她察觉到走廊里有一丝淡淡的烟味。","why":"awareness is the core of the word; the phrase with 'of' simply names what the awareness is aimed at.","whyCN":"觉察是这个词的核心，后接介词只是点明觉察所指向的对象。"},{"no":"03","title":"Done on purpose","titleCN":"刻意做出的","definition":"done deliberately, with full attention and intention","definitionCN":"带着完全的注意与意图做出，而非出于本能或习惯","example":"He made a conscious effort to slow his speech.","exampleCN":"他有意识地放慢了自己的语速。","why":"if you are fully awake to what you are doing, the act is by definition intended rather than accidental.","whyCN":"既然你对所做的事完全心知肚明，这个动作按定义就是有意的，而非偶然的。"},{"no":"04","title":"The knowing layer of the mind","titleCN":"心理层面上的意识","definition":"the part of mental life that is open to awareness, as opposed to what lies below it","definitionCN":"心理生活中可以被觉察到的那一部分，与沉在其下的部分相对","example":"Psychologists once drew a hard line between the conscious and the unconscious.","exampleCN":"心理学家曾把意识层面与无意识层面划出明确界线。","why":"the word was taken into psychology as a noun-like label for whatever the mind can hold in the light.","whyCN":"这个词被心理学借去，当作一个近似名词的标签，指心智能置于亮处的那些内容。"},{"no":"05","title":"Aware that a fact is true","titleCN":"意识到某个事实成立","definition":"knowing that something is the case, usually something uneasy or important","definitionCN":"知道某件事确实如此，通常指令人不安或重要的事","example":"They were conscious that the deadline had already passed.","exampleCN":"他们意识到截止日期已经过去了。","why":"here awareness has moved from the senses to the intellect: what is known is a fact rather than a sight or a sound.","whyCN":"这里的觉察从感官转到理智：被知道的是一个事实，而不是看见或听见的东西。"},{"no":"06","title":"Embarrassed by being watched","titleCN":"因被人注意而不自在","definition":"too aware of oneself as seen by others, so that behaviour becomes awkward","definitionCN":"过分意识到自己正被别人看见，因而举止变得拘谨","example":"He grew self-conscious when the camera turned toward him.","exampleCN":"镜头转向他时，他变得很不自在。","why":"awareness turned inward and doubled: you are conscious of yourself being conscious of yourself.","whyCN":"觉察转向内部并且加倍：你意识到自己正在意识到自己。"},{"no":"07","title":"Attentive to a particular issue","titleCN":"对某一议题格外在意","definition":"paying regular attention to a named concern, as in health or safety","definitionCN":"对某个被点名的关切长期保持注意，如健康、安全之类","example":"The new canteen attracts health-conscious students.","exampleCN":"新食堂吸引注重健康的学生。","why":"the compound pattern names the object of awareness first, so the adjective carries the sense of an ongoing habit rather than a single act.","whyCN":"这种复合构词先点明觉察的对象，因此这个词带的是长期习惯，而不是一次性的动作。"},{"no":"08","title":"Coming back from sleep or drugs","titleCN":"从睡眠或麻醉中恢复知觉","definition":"regaining awareness after sleep, illness or anaesthesia, or failing to do so","definitionCN":"在睡眠、疾病或麻醉之后重新获得知觉，或未能获得","example":"He was still only half conscious when the ambulance arrived.","exampleCN":"救护车到的时候，他仍只是半清醒。","why":"the same state is now measured as a process with two directions, losing it and getting it back, which explains the hospital phrase.","whyCN":"同一个状态在这里被当作有方向的过程来测量：失去与恢复，这就解释了医院里的那种说法。"}],"etymology":{"intro":{"en":"Conscious comes from Latin conscius 'knowing with, privy to', built on com- 'together' and scire 'to know'. It entered English in the seventeenth century, first meaning 'sharing knowledge with another', and only later 'knowing one's own mind'. Dates are approximate.","cn":"conscious 来自拉丁 conscius「与……同知、知情」，由表「共同」的前缀加 scire「知道」构成。17 世纪进入英语，最初指「与别人共知某事」，后来才指「知道自己的心思」。年代均为约数。"},"items":[{"era":"LATIN SCIRE","en":"Scire meant 'to know, to understand'. Its deeper origin is not established; the old suggestion that it is related to scindere 'to cut' is a hypothesis, not a demonstrated derivation.","cn":"scire 意为「知道、懂得」。其更深来源未得到证明；旧说认为它与意为「切分」的动词有关，那只是假说，并非已证实的派生。"},{"era":"LATIN CONSCIRE","en":"Com- 'together' plus scire produced conscire 'to know together with someone, to be privy to'. A conscius was a witness or an accomplice, someone who knew what another did.","cn":"表「共同」的前缀加 scire 构成 conscire「与某人共知、知情」。相应名词指证人或有份者，即知道别人所作所为的人。"},{"era":"LATIN CONSCIENTIA","en":"Conscientia, 'knowledge shared with oneself', became the ordinary word for both inner awareness and the moral sense that judges one's own acts.","cn":"conscientia 意为「与自己共有的知识」，既是内心觉察，也指评判自身行为的道德感。"},{"era":"ENGLISH CONSCIOUS","en":"In the seventeenth century conscious was borrowed from the Latin adjective, first in the social sense of being privy to something, then in the inward sense of being aware of one's own existence.","cn":"17 世纪 conscious 从拉丁形容词借入英语，先有「知情、与闻」的社会义，后转为「觉察自身存在」的内向义。"},{"era":"PSYCHOLOGY SPLIT","en":"Nineteenth-century psychology paired conscious with its negative and its prefixed forms, and the adjective became a technical label for the lighted part of mental life.","cn":"19 世纪心理学把它与否定形式及带前缀的形式配成一组，这个形容词遂成为心理生活中「亮处」的专业标签。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of scire remains a reconstruction, and the exact first English citation is not fixed.","cn":"来源不确定：scire 在拉丁语之前的来源仍属重构形式，英语中最早的确切书证年代也未定。"}]},"similar":{"note":{"en":"Group one holds near-identical spellings whose histories must be kept apart; group two holds words that share the idea of noticing but differ in focus.","cn":"第一组是拼写极近、必须分清来历的词；第二组是同样表示「注意到」但侧重不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conscience","ipa":"/ˈkɒnʃəns/","tag":"same root, moral sense","definition":"The same Latin noun that gave conscious, but English kept it for the inner judge of right and wrong, so it is a moral faculty rather than a state of awareness.","definitionCN":"与 conscious 同出那个拉丁名词，但英语把它留给内心的是非裁判，因此指道德能力，而不是觉察状态。"},{"word":"conscientious","ipa":"/kənˈʃiːənʃəs/","tag":"same root, dutiful","definition":"Built on the same stock, but it describes a person who follows the inner judge carefully, hence 'scrupulous, dutiful'.","definitionCN":"同出这一词族，但形容一个人认真听从内心的裁判，因此是「一丝不苟、尽责」。"},{"word":"consensus","ipa":"/kənˈsensəs/","tag":"different root","definition":"From sentire 'to feel', not scire 'to know': a shared feeling, so despite the shared opening it belongs to another family.","definitionCN":"来自意为「感觉」的动词，而非「知道」：指共同的感觉，因此开头相同却属另一词族。"},{"word":"unconscious","ipa":"/ʌnˈkɒnʃəs/","tag":"negated form","definition":"The plain negative of this word: not awake, or not aware, or below the lighted layer.","definitionCN":"本词的否定形式：不清醒、未察觉，或处在亮处之下。"}]},{"heading":"NEAR MEANING","entries":[{"word":"aware","ipa":"/əˈweə/","tag":"noticing only","definition":"Covers the noticing senses but says nothing about being awake or about intention, so it cannot replace conscious in a hospital report.","definitionCN":"只覆盖「注意到」这一类义项，不涉及清醒与意图，因此不能替代表述病情的 conscious。"},{"word":"alert","ipa":"/əˈlɜːt/","tag":"ready to act","definition":"Adds readiness and speed of response; a person can be conscious yet dull, but not alert and dull.","definitionCN":"多了机敏与反应迅速之意；人可以清醒而迟钝，却不能既机敏又迟钝。"},{"word":"mindful","ipa":"/ˈmaɪndfəl/","tag":"keeping in mind","definition":"Stresses remembering a duty or risk while acting, which is closer to the deliberate sense than to the medical one.","definitionCN":"强调做事时记着责任或风险，更接近「刻意」义，而非医学义。"},{"word":"awake","ipa":"/əˈweɪk/","tag":"sleep only","definition":"Only names the end of sleep; it does not extend to awareness of facts, intentions or social unease.","definitionCN":"只表示睡眠结束，不延伸到对事实的觉察、意图或社交上的不自在。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root scire 'to know' is the same one behind science, so conscious is literally 'knowing with'.","cn":"词根意为「知道」，也是 science 的词根，因此 conscious 字面上是「与……同知」。"},{"en":"The family runs conscious, consciousness, consciously, unconscious, subconscious, self-conscious.","cn":"同族词包括 conscious、consciousness、consciously、unconscious、subconscious、self-conscious。"},{"en":"Fixed phrases mark the senses: conscious of, conscious that, conscious effort, health-conscious.","cn":"固定搭配标出各义项：察觉到、意识到某事、有意识的努力、注重健康。"},{"en":"Hospitals speak of losing and regaining consciousness, which pins the medical sense down.","cn":"医院里说失去与恢复意识，这正好锁定了医学义。"},{"en":"The word sits opposite unconscious in psychology, and opposite asleep in everyday speech.","cn":"在心理学里它与「无意识」相对，在日常口语里它与「睡着」相对。"}],"abstract":[{"en":"Picture a lamp switched on in a room where furniture was always there but unseen.","cn":"想象房间里一盏灯被打开，家具一直都在，只是此前看不见。"},{"en":"Picture a witness inside your own head who can testify about what you did.","cn":"想象你脑中有一位证人，能对你做过的事作证。"},{"en":"Picture a mirror carried into a crowd, so that seeing others turns into seeing yourself.","cn":"想象一面镜子被带进人群，看见别人于是变成看见自己。"}]},"examples":[{"en":"The driver was conscious but unable to move his legs.","cn":"司机神志清醒，但双腿无法动弹。"},{"en":"She was conscious of the silence that followed her question.","cn":"她察觉到自己的问题之后那片沉默。"},{"en":"Advertising makes children conscious of brands long before they can read prices.","cn":"广告让孩子在会读价签之前就已经对品牌敏感。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"con（共同）+ sci（知）——和自己一起知道 → 清醒的、有意识的","word":"conscious"},"root":"拉丁 conscius「与……同知、知情」= 表「共同」的前缀 + scire「知道」；其更早来源不确定，与意为「切分」的动词之间的联系仅为假说。英语 conscious。","sensesIntro":{"en":"Eight senses follow one movement: a light comes on inside a person, then that light is aimed at things, at facts, at one's own acts, and finally at oneself as seen by others.","cn":"八个义项沿一个动作展开：人内部亮起一盏灯，这盏灯依次照向事物、照向事实、照向自己的行为，最后照向被他人看见的自己。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp switched on inside a room, so that what was always there becomes visible and the person can act on it.","cn":"核心意象：房间里的一盏灯被打开，本来就在的东西变得可见，人于是能据此行动。"},"chain":["LIGHT ON","SEEING WHAT IS THERE","KNOWING A FACT","ACTING ON PURPOSE","THE LIGHTED LAYER","BEING SEEN"],"branches":[{"senses":"01 · 08","en":"LIGHT ON OR OFF: the medical pair measures the same state in two directions, waking up and going under.","cn":"灯亮与灯灭：医学上成对的说法把同一状态量成两个方向，醒来与失去。"},{"senses":"02 · 05","en":"WHAT THE LIGHT REACHES: first a smell or a sound, then a fact that cannot be sensed at all.","cn":"灯光照到什么：先是气味或声音，后来是完全无法感知的事实。"},{"senses":"03","en":"LIGHT ON THE ACT: because the doer sees what he is doing, the deed counts as intended.","cn":"灯照在动作上：因为做事的人看见自己在做什么，这个行为便算作有意。"},{"senses":"04","en":"THE LIGHTED LAYER AS A WHOLE: psychology turns the state into a named region of the mind.","cn":"亮处作为整体：心理学把这个状态变成一个被命名的心理区域。"},{"senses":"06 · 07","en":"LIGHT TURNED ON THE SELF: either too much, so one freezes, or steadily, so one watches a chosen concern.","cn":"灯转向自身：要么过量而僵住，要么稳定地照着某个选定的关切。"}]},"affixes":{"intro":{"en":"Conscious is a Latin adjective in which a prefix meaning 'together' sits on a verb meaning 'to know', so the whole family can be read morpheme by morpheme.","cn":"conscious 是一个拉丁形容词，表「共同」的前缀叠在意为「知道」的动词上，因此整个词族都可以按语素逐个读出。"},"latinIntro":{"en":"Latin scire gives science, scientific and conscience; the prefix adds the sense of knowing together with someone else or with oneself.","cn":"拉丁 scire 衍生 science、scientific 与 conscience；前缀则增添「与别人或与自己共知」的意思。"},"items":[{"word":"scire","structure":"scire (Latin verb, fourth conjugation)","meaning":"to know, to understand","meaningCN":"知道；懂得","example":"The root supplies the idea of knowledge in every member of the family.","exampleCN":"这个词根为整个词族提供「知」的意思。"},{"word":"conscire","structure":"com- 'together' + scire","meaning":"to know together with, to be privy to","meaningCN":"与……共知；知情","example":"The prefix turns knowing into knowing alongside someone.","exampleCN":"前缀把「知道」变成「与某人一起知道」。"},{"word":"conscius","structure":"conscire + -us (adjective ending)","meaning":"knowing with another; conscious of","meaningCN":"与别人共知的；自觉到的","example":"The adjective is the direct source of the English word.","exampleCN":"这个形容词正是英语这个词的直接来源。"},{"word":"conscientia","structure":"conscius + -ia (state noun)","meaning":"shared knowledge; inner awareness; moral sense","meaningCN":"共有的知识；内心觉察；道德感","example":"It split into two English words with different duties.","exampleCN":"它在英语中分成两个职责不同的词。"},{"word":"conscious","structure":"conscius, borrowed whole","meaning":"aware, awake, deliberate","meaningCN":"察觉的；清醒的；刻意的","example":"The driver was conscious but unable to move.","exampleCN":"司机神志清醒，却无法动弹。"},{"word":"consciousness","structure":"conscious + -ness (state)","meaning":"the state of being aware","meaningCN":"意识；知觉","example":"The drug dulls consciousness without stopping breathing.","exampleCN":"这种药让人意识迟钝，却不停止呼吸。"},{"word":"consciously","structure":"conscious + -ly (adverb)","meaning":"in a deliberate way","meaningCN":"有意识地；刻意地","example":"He consciously avoided the subject.","exampleCN":"他刻意回避这个话题。"},{"word":"unconscious","structure":"un- 'not' + conscious","meaning":"not awake or not aware","meaningCN":"失去知觉的；无意识的","example":"She was unconscious for several minutes.","exampleCN":"她失去知觉好几分钟。"},{"word":"subconscious","structure":"sub- 'under' + conscious","meaning":"below the lighted layer of awareness","meaningCN":"意识之下的；下意识的","example":"A subconscious habit can be hard to name.","exampleCN":"下意识的习惯往往难以说清。"}],"latinEntries":[{"word":"scire","structure":"scire, scio, scivi, scitum (verb, fourth conjugation)","meaning":"to know, understand, know how","meaningCN":"知道；懂得；会做"},{"word":"conscire","structure":"com- + scire (verb, fourth conjugation)","meaning":"to be conscious of, to share knowledge of","meaningCN":"自觉；与……共知"},{"word":"conscius","structure":"conscire + -us (first and second declension adjective)","meaning":"privy to, conscious of, guilty with knowledge","meaningCN":"知情的；自觉的；心里有数的"},{"word":"conscientia","structure":"conscius + -ia (first declension noun)","meaning":"shared knowledge, consciousness, conscience","meaningCN":"共知；意识；良心"}],"derivatives":[{"word":"consciously","pos":"adv.","zh":"有意识地；刻意地"},{"word":"consciousness","pos":"n.","zh":"意识；知觉；清醒状态"},{"word":"unconscious","pos":"adj.","zh":"失去知觉的；无意识的"},{"word":"subconscious","pos":"adj./n.","zh":"下意识的 / 潜意识"},{"word":"conscience","pos":"n.","zh":"良心；是非心"},{"word":"conscientious","pos":"adj.","zh":"一丝不苟的；尽责的"}]}},{"word":"consciousness","ipa_uk":"/kənˈʃʌsnəs/","ipa_us":"/kənˈʃʌsnəs/","definition_zh":"意识；知觉；清醒状态；自我觉察；群体意识；对某议题的关注","definition_en":"the state of being awake and aware, or the whole body of a person's or group's awareness","core_image":"水面下的暗流看不见，水面上却有一层能照见自己的薄光，这层薄光时开时合","scene":"病房的窗帘拉开，护士叫了三声名字，床上的人终于睁眼，目光从茫然变得能追着人走。The nurse watched for signs that consciousness was returning after the operation.","sceneCN":"这里 consciousness 指「意识这一状态由无到有的恢复」（第 1 个义项：清醒并能感知的状态）；句意为护士观察手术后意识是否正在恢复。图中可辨识物件：窗帘、病床、睁开的眼睛。","pos":[{"tag":"n.","zh":"意识；知觉；清醒状态；自我觉察；觉悟"}],"collocations":[{"phrase":"lose consciousness","zh":"失去知觉；昏过去"},{"phrase":"regain consciousness","zh":"恢复意识"},{"phrase":"a state of consciousness","zh":"意识状态"},{"phrase":"self-consciousness","zh":"自我意识；不自在"},{"phrase":"class consciousness","zh":"阶级意识"},{"phrase":"environmental consciousness","zh":"环保意识"}],"forms":[{"label":"复数（少见，指多种意识形式）","form":"consciousnesses"},{"label":"形容词形式","form":"conscious"},{"label":"副词形式","form":"consciously"},{"label":"复合名词","form":"self-consciousness"},{"label":"反义名词","form":"unconsciousness"}],"derivatives":[{"word":"conscious","pos":"adj.","zh":"清醒的；有意识的"},{"word":"consciously","pos":"adv.","zh":"有意识地"},{"word":"unconsciousness","pos":"n.","zh":"昏迷；无意识状态"},{"word":"self-consciousness","pos":"n.","zh":"自我意识；拘谨"},{"word":"subconsciousness","pos":"n.","zh":"潜意识状态"}],"senses":[{"no":"01","title":"The state of being awake","titleCN":"清醒这一状态本身","definition":"the condition of being awake and able to feel and act","definitionCN":"处于醒着、能感受也能行动的状态","example":"The nurse watched for signs that consciousness was returning.","exampleCN":"护士观察意识是否正在恢复的迹象。","why":"the noun names the state rather than the person, so it can be lost, regained and monitored like a level.","whyCN":"这个名词命名的是状态而不是人，因此可以像水位一样被失去、恢复与监测。"},{"no":"02","title":"The capacity to feel","titleCN":"感受与知觉的能力","definition":"the ability to have sensations and experiences at all","definitionCN":"能够拥有感觉与经验这一根本能力","example":"Anaesthetists adjust the dose until sensation and consciousness fade.","exampleCN":"麻醉师调整剂量，直到感觉与意识消退。","why":"this is the thinnest sense: not being aware of anything in particular, but being able to be affected.","whyCN":"这是最薄的义项：不是察觉到某个具体之物，而是「能被影响」这件事本身。"},{"no":"03","title":"Awareness of oneself","titleCN":"对自身的觉察","definition":"the ability to notice one's own thoughts, body and appearance","definitionCN":"注意到自己的念头、身体与外貌的能力","example":"Mirrors test whether an animal has self-consciousness.","exampleCN":"镜子测试检验动物是否具有自我意识。","why":"the light that turns back on the lamp itself; this is what separates a person from a mere sensing device.","whyCN":"灯光反过来照到灯本身；这正是人区别于单纯感应装置的地方。"},{"no":"04","title":"The flow of inner experience","titleCN":"当下内心经验之流","definition":"the whole moving content of what one is currently thinking, feeling and remembering","definitionCN":"此刻所想、所感、所记的全部流动内容","example":"The novel tries to copy the consciousness of a man walking through a city.","exampleCN":"这部小说试图复制一个人穿过城市时的意识流。","why":"psychology turned the state into something with contents, so the word can name a stream rather than a switch.","whyCN":"心理学把这个状态变成有内容的东西，于是这个词可以命名一条流，而不只是一个开关。"},{"no":"05","title":"A shared awareness in a group","titleCN":"群体共有的意识","definition":"a body of awareness shared by a class, nation or generation, often about its own position","definitionCN":"某个阶级、民族或世代共有的觉察，常指向自身处境","example":"The strike sharpened class consciousness among the mill workers.","exampleCN":"罢工让纱厂工人的阶级意识变得清晰。","why":"the same noun is lifted from one head to many, where it means a group knowing itself as a group.","whyCN":"同一个名词从一颗脑袋抬到许多脑袋上，指一个群体把自己认作群体。"},{"no":"06","title":"Attention to a public issue","titleCN":"对公共议题的关注","definition":"a general readiness to notice and care about a named problem, such as waste or safety","definitionCN":"对某个被点名的公共问题普遍保持注意与关心","example":"Recycling bins did more for environmental consciousness than any slogan.","exampleCN":"回收箱对环保意识的推动大过任何口号。","why":"awareness narrowed to one topic becomes a social habit, and the word measures how widespread that habit is.","whyCN":"觉察收窄到单一议题就变成社会习惯，这个词衡量的正是这种习惯有多广。"},{"no":"07","title":"The object of psychological study","titleCN":"作为研究对象的「意识」","definition":"the general phenomenon that philosophers and scientists argue about, rather than any instance of it","definitionCN":"哲学家与科学家争论的那个总现象，而非它的某一具体实例","example":"No laboratory instrument yet measures consciousness directly.","exampleCN":"目前还没有仪器能直接测量意识。","why":"once a thing has a name, it can be put on a table as a problem, and the word becomes the title of that problem.","whyCN":"事物一旦有了名字，就能被摆上台面当作问题，这个词于是成为那个问题的标题。"},{"no":"08","title":"Whether it is there at all","titleCN":"意识的存续与否","definition":"the presence or absence of awareness, as in losing it or coming round","definitionCN":"觉察的存在与否，如昏过去或醒转","example":"He lost consciousness before the paramedics reached him.","exampleCN":"急救人员赶到之前他就失去了意识。","why":"the noun is treated as a possession that can be dropped and picked up, which is why hospitals count it in minutes.","whyCN":"这个名词被当作可以丢掉又捡回的持有物，因此医院里按分钟来计算它。"}],"etymology":{"intro":{"en":"Consciousness is formed inside English from conscious plus the state suffix -ness. It was coined in the seventeenth century as a learned equivalent of Latin conscientia, the noun that also gave English conscience. Dates are approximate.","cn":"consciousness 是在英语内部由 conscious 加表状态的后缀构成的。17 世纪造出，用来对应拉丁 conscientia，而同一个拉丁名词也给了英语 conscience。年代均为约数。"},"items":[{"era":"LATIN CONSCIENTIA","en":"Conscientia meant 'knowledge held together with oneself'. Cicero used it for inner awareness, and Christian writers narrowed it to the moral judge.","cn":"conscientia 意为「与自己共持的知识」。西塞罗用它指内心觉察，基督教作家则把它收窄为道德裁判。"},{"era":"ENGLISH CONSCIENCE","en":"The older borrowing conscience took the moral sense into English, leaving the neutral sense of awareness without a noun.","cn":"较早借入的 conscience 把道德义带进英语，于是中性的「觉察」义反而缺一个名词。"},{"era":"SEVENTEENTH-CENTURY COINAGE","en":"Conscious plus -ness filled that gap, first in philosophical writing about the soul knowing its own states.","cn":"conscious 加表状态的后缀补上了这个空缺，最早见于讨论灵魂如何知道自身状态的哲学文字。"},{"era":"NINETEENTH-CENTURY SCIENCE","en":"Physiology and then psychology made it a measurable variable, so that it could be lost, regained, lowered and studied in animals.","cn":"生理学继而心理学把它变成可测量的变量，于是它可以被失去、恢复、降低，并在动物身上研究。"},{"era":"SOCIAL EXTENSION","en":"From the nineteenth century the noun was also applied to groups, giving phrases such as class consciousness and national consciousness.","cn":"从 19 世纪起，这个名词也被用于群体，产生阶级意识、民族意识一类说法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: no single first citation is agreed, and the pre-Latin origin of the root remains a reconstruction.","cn":"来源不确定：没有公认的最早书证，词根在拉丁语之前的来源仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin stock but given different jobs in English; group two holds near synonyms with a narrower reach.","cn":"第一组是同出拉丁词源、却在英语里分到不同职责的词；第二组是范围更窄的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conscience","ipa":"/ˈkɒnʃəns/","tag":"same source, moral duty","definition":"Both go back to the same Latin noun, but conscience names the inner judge of right and wrong, never the state of being awake.","definitionCN":"两者同出那个拉丁名词，但 conscience 指内心的是非裁判，从不指清醒状态。"},{"word":"conscientiousness","ipa":"/kənˈʃiːənʃəsnəs/","tag":"same source, a trait","definition":"The quality of being dutiful and exact; it looks like this word but describes character, not awareness.","definitionCN":"指尽责而严谨的品质；字形相近，描述的却是性格而非觉察。"},{"word":"conscious","ipa":"/ˈkɒnʃəs/","tag":"base adjective","definition":"The adjective behind the noun; it describes the person or state, while the noun names the state itself.","definitionCN":"这个名词背后的形容词；它描述人或状态，而名词命名状态本身。"},{"word":"unconsciousness","ipa":"/ʌnˈkɒnʃəsnəs/","tag":"negated form","definition":"Its plain negative, used in medicine for a coma-like state and in psychology for the whole hidden layer.","definitionCN":"它的直接否定形式，医学上指类昏迷状态，心理学上指整个隐藏层面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"awareness","ipa":"/əˈweənəs/","tag":"noticing only","definition":"The everyday synonym for the perceiving senses, but it does not cover being awake or the scientific sense of a whole field of experience.","definitionCN":"日常同义词，覆盖感知类义项，但不覆盖清醒状态，也不表示作为整体研究对象的那个科学义。"},{"word":"sentience","ipa":"/ˈsentɪəns/","tag":"feeling only","definition":"Strictly the capacity to feel, used in ethics and animal law; it says nothing about thinking or self-knowledge.","definitionCN":"严格指感受能力，多用于伦理学与动物法；不涉及思考或自知。"},{"word":"wakefulness","ipa":"/ˈweɪkfəlnəs/","tag":"sleep cycle","definition":"A sleep-medicine term for being awake, without the philosophical and social reach of this word.","definitionCN":"睡眠医学中表示醒着的术语，没有本词那种哲学与社会层面的延伸。"},{"word":"mind","ipa":"/maɪnd/","tag":"whole apparatus","definition":"Names the whole thinking apparatus, including what is not currently lighted; wider than consciousness, not a synonym.","definitionCN":"指整个思维装置，包括当下未被照亮的部分；比 consciousness 更宽，不是同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Conscious plus the state suffix gives the noun, exactly as dark plus the same suffix gives darkness.","cn":"conscious 加表状态的后缀构成这个名词，正如「暗」加同一后缀成为「黑暗」。"},{"en":"English keeps conscience for moral duty and consciousness for awareness, though both come from one Latin noun.","cn":"英语让 conscience 管道德、consciousness 管觉察，尽管两者同出一个拉丁名词。"},{"en":"Fixed phrases mark the medical sense: lose consciousness, regain consciousness.","cn":"固定搭配标出医学义：失去意识、恢复意识。"},{"en":"The social senses appear as class consciousness, national consciousness, environmental consciousness.","cn":"社会类义项出现在阶级意识、民族意识、环保意识这些说法里。"},{"en":"Stream-of-consciousness is the literary technique named after sense four.","cn":"「意识流」这一文学手法正是按第 4 个义项命名的。"}],"abstract":[{"en":"Picture a thin film of light lying on dark water, able to show the water to itself.","cn":"想象一层薄光铺在暗水上，能让水看见自己。"},{"en":"Picture a room whose switch can be flipped by someone outside the door.","cn":"想象一间屋子的开关能被门外的人拨动。"},{"en":"Picture a crowd that suddenly recognizes itself in a single reflection.","cn":"想象一群人忽然在同一面倒影里认出自己。"}]},"examples":[{"en":"The drug lowers consciousness without stopping the heart.","cn":"这种药降低意识水平，却不使心脏停止。"},{"en":"Children develop self-consciousness earlier than most parents expect.","cn":"儿童形成自我意识的时间比多数家长预想的更早。"},{"en":"The report says public consciousness of air quality has risen sharply.","cn":"报告称公众对空气质量的意识已明显上升。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"conscious（有意识的）+ ness（状态）——有意识的那种状态 → 意识、知觉","word":"consciousness"},"root":"英语在 conscious 上加表状态的后缀构成，对应拉丁 conscientia「与自己共持的知识」；同一拉丁名词也给了英语 conscience「良心」。","sensesIntro":{"en":"Eight senses follow one movement: a light comes on, then it is measured, then it turns inward, then it becomes a stream, then it spreads to a group, narrows to an issue, and finally becomes an object of study.","cn":"八个义项沿一个动作展开：灯亮起，被测量，转向内部，变成一条流，扩散到群体，收窄到某个议题，最后成为一个被研究的对象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin film of light on dark water, able to show the water to itself.","cn":"核心意象：暗水上的一层薄光，能让水看见自己。"},"chain":["LIGHT ON","ABLE TO FEEL","TURNED INWARD","INNER STREAM","SHARED BY MANY","NAMED AS A PROBLEM"],"branches":[{"senses":"01 · 08","en":"PRESENCE OF THE LIGHT: the same state counted as on or off, which is why hospitals speak of losing and regaining it.","cn":"灯之有无：同一状态被算作亮或灭，所以医院说失去与恢复。"},{"senses":"02 · 04","en":"LIGHT AND ITS CONTENTS: first the bare capacity to be affected, then the whole moving stream of what fills it.","cn":"灯与其内容：先是能被影响这一能力，再是填满它的整条流动内容。"},{"senses":"03","en":"LIGHT TURNED ON ITSELF: self-awareness is the one sense in which the lamp and the lit object are the same thing.","cn":"灯照自身：自我觉察是唯一一个灯与被照物为同一物的义项。"},{"senses":"05 · 06","en":"LIGHT SHARED OR NARROWED: either a whole class knows itself, or a public keeps watch on one problem.","cn":"灯被共享或收窄：要么整个阶级认识自己，要么公众持续盯着某一个议题。"},{"senses":"07","en":"LIGHT AS A QUESTION: what was a state becomes a named puzzle that instruments are built to chase.","cn":"灯成为问题：原本的状态变成一个被命名的谜题，人们造仪器去追它。"}]},"affixes":{"intro":{"en":"The word is an English build: a Latin-derived adjective plus a native state suffix, so its family can be read from both ends.","cn":"这个词是在英语内部搭起来的：一个来自拉丁的形容词加一个本族语的状态后缀，因此可以从两头读它的词族。"},"latinIntro":{"en":"The Latin base is scire 'to know', with the prefix adding 'together'; the English suffix marks a state or quality.","cn":"拉丁词根意为「知道」，前缀增添「共同」的意思；英语后缀则标记状态或性质。"},"items":[{"word":"conscious","structure":"conscius (Latin adjective, borrowed)","meaning":"aware, awake, deliberate","meaningCN":"觉察的；清醒的；刻意的","example":"The base adjective supplies the whole meaning.","exampleCN":"词基形容词提供了全部词义。"},{"word":"-ness","structure":"native English suffix forming state nouns","meaning":"the state or quality of being X","meaningCN":"表示「处于某种状态或性质」","example":"It turns adjectives into abstract nouns.","exampleCN":"它把形容词变成抽象名词。"},{"word":"consciousness","structure":"conscious + -ness","meaning":"the state of being aware","meaningCN":"意识；知觉","example":"The drug lowers consciousness.","exampleCN":"这种药降低意识水平。"},{"word":"self-consciousness","structure":"self + consciousness","meaning":"awareness of oneself as seen","meaningCN":"自我意识；拘谨","example":"Self-consciousness made him stammer.","exampleCN":"自我意识让他结巴起来。"},{"word":"unconsciousness","structure":"un- 'not' + consciousness","meaning":"the state of not being aware","meaningCN":"无意识状态；昏迷","example":"Unconsciousness followed the blow.","exampleCN":"那一击之后便失去了意识。"},{"word":"class consciousness","structure":"class + consciousness","meaning":"a group's awareness of its own position","meaningCN":"阶级意识","example":"The strike sharpened class consciousness.","exampleCN":"罢工强化了阶级意识。"},{"word":"stream of consciousness","structure":"stream + of + consciousness","meaning":"the unbroken flow of inner experience","meaningCN":"意识流","example":"The novel uses stream of consciousness.","exampleCN":"这部小说采用意识流手法。"},{"word":"conscience","structure":"conscientia, separate borrowing","meaning":"the inner judge of right and wrong","meaningCN":"良心；是非心","example":"His conscience would not let him sign.","exampleCN":"他的良心不允许他签字。"}],"latinEntries":[{"word":"scire","structure":"scire, scio, scivi, scitum (verb, fourth conjugation)","meaning":"to know, understand","meaningCN":"知道；懂得"},{"word":"conscius","structure":"com- + scire, adjective of the first and second declension","meaning":"knowing with, privy to, conscious of","meaningCN":"共知的；知情的；自觉的"},{"word":"conscientia","structure":"conscius + -ia (first declension noun)","meaning":"shared knowledge, inner awareness, conscience","meaningCN":"共知；内心觉察；良心"}],"derivatives":[{"word":"conscious","pos":"adj.","zh":"清醒的；有意识的"},{"word":"consciously","pos":"adv.","zh":"有意识地"},{"word":"unconsciousness","pos":"n.","zh":"昏迷；无意识状态"},{"word":"consciousness-raising","pos":"n.","zh":"（社会运动中的）意识提升"}]}},{"word":"subconscious","ipa_uk":"/ˌsʌbˈkɒnʃəs/","ipa_us":"/ˌsʌbˈkɑːnʃəs/","definition_zh":"下意识的；潜意识的；半清醒的；隐约的；潜意识（名词）","definition_en":"below the level of ordinary awareness, or the part of the mind that works without being noticed","core_image":"海面上风平浪静，海面下却有一股看不见的洋流，一直在推着船走","scene":"他走进旧教室，没看座位表就径直坐到了自己当年的位置，坐下后才想起这件事。A subconscious pull toward the old seat made him sit down before he noticed.","sceneCN":"这里 subconscious 指「并未自觉、却仍在推动行为的心理力量」（第 1 个义项：未自觉而影响行为）；句意是一股下意识的牵引让他在察觉之前就坐下了。图中可辨识物件：旧课桌、偏移的路线、水面下的暗流。","pos":[{"tag":"adj.","zh":"下意识的；潜意识的；未自觉的；隐约的"},{"tag":"n.","zh":"潜意识；下意识的心理活动"}],"collocations":[{"phrase":"the subconscious mind","zh":"潜意识"},{"phrase":"subconscious desire","zh":"下意识的欲望"},{"phrase":"subconscious bias","zh":"不自觉的偏见"},{"phrase":"subconscious level","zh":"潜意识层面"},{"phrase":"at a subconscious level","zh":"在潜意识层面"},{"phrase":"subconscious fear","zh":"隐约的恐惧"}],"forms":[{"label":"比较级（多与 more 连用）","form":"more subconscious"},{"label":"最高级（多与 most 连用）","form":"most subconscious"},{"label":"副词","form":"subconsciously"},{"label":"名词（状态）","form":"subconsciousness"},{"label":"复数（名词，少用）","form":"subconsciouses"}],"derivatives":[{"word":"subconsciously","pos":"adv.","zh":"下意识地；不知不觉地"},{"word":"subconsciousness","pos":"n.","zh":"潜意识状态"},{"word":"conscious","pos":"adj.","zh":"有意识的；清醒的"},{"word":"unconscious","pos":"adj./n.","zh":"无意识的 / 潜意识（精神分析）"},{"word":"preconscious","pos":"adj.","zh":"前意识的（可被唤回但当下不在意识中）"}],"senses":[{"no":"01","title":"Working below awareness","titleCN":"在觉察之下起作用","definition":"guiding behaviour without the person noticing the guidance","definitionCN":"在当事人并未察觉这种引导的情况下左右其行为","example":"A subconscious pull toward the old seat made him sit down before he noticed.","exampleCN":"一股下意识的牵引让他在察觉之前就坐到了老位置上。","why":"the word simply places consciousness under something, so what happens there is real but unlighted.","whyCN":"这个词只是把意识放到某层之下，因此那一层发生的事真实存在，却没有被照亮。"},{"no":"02","title":"Stored but not recalled","titleCN":"存着却未被唤起的记忆","definition":"a memory or impression kept in the mind that shapes reactions without being brought to mind","definitionCN":"留在心里、能影响反应却不会被主动想起的记忆或印象","example":"A subconscious memory of the song kept him humming it.","exampleCN":"对那首歌的潜意识记忆让他一直哼着它。","why":"storage is the oldest idea attached to this word: the file is there, but nobody has opened it.","whyCN":"「储存」是这个词最古老的附着观念：档案在那里，只是没人打开。"},{"no":"03","title":"Only half awake","titleCN":"只醒着一半","definition":"in a drowsy or drugged state where some response is possible but full awareness is not","definitionCN":"在昏沉或药效之中，能作出部分反应，却没有完整觉察","example":"The patient was subconscious enough to mumble but not to answer.","exampleCN":"病人半醒半睡，能含糊出声，却不能作答。","why":"this sense stays close to the literal image of a level below the surface: partly above, partly below.","whyCN":"这个义项贴近字面意象：水面之下的那一层，一半在上，一半在下。"},{"no":"04","title":"The hidden part of the mind","titleCN":"心智中隐藏的那一部分","definition":"the region of mental life thought to operate outside ordinary attention","definitionCN":"被认为在日常注意之外运作的那块心理领域","example":"Early psychologists mapped a conscious, a subconscious and an unconscious layer.","exampleCN":"早期心理学家划分出意识、潜意识与无意识三层。","why":"as a noun the word turns the adjective into a place, which is how maps of the mind are drawn.","whyCN":"作名词时，这个词把形容词变成一个地点，心智地图正是这样画出来的。"},{"no":"05","title":"Its contents and workings","titleCN":"该层的内容与运作","definition":"the wishes, images and habits that live in that hidden region","definitionCN":"居住在那个隐藏区域里的愿望、意象与习惯","example":"Dreams were read as messages from the subconscious.","exampleCN":"梦被读作潜意识传来的讯息。","why":"a place needs furniture, so the same noun comes to mean everything stored in it as well.","whyCN":"地点需要家具，于是同一个名词也指储存在其中的全部东西。"},{"no":"06","title":"An unspoken resistance","titleCN":"说不出口的抗拒","definition":"a reluctance or aversion that shows in behaviour before it can be explained","definitionCN":"先表现在行为上、却还说不清理由的抗拒或反感","example":"He felt a subconscious resistance whenever the topic of money came up.","exampleCN":"一谈到钱，他心里就生出一股下意识的抗拒。","why":"when the hidden layer pushes against something, the push arrives as a feeling before it arrives as a reason.","whyCN":"当隐藏的那层对某物施力时，这股力先以感觉抵达，再以理由抵达。"},{"no":"07","title":"The undercurrent in art","titleCN":"作品底下的潜流","definition":"an emotional current beneath the surface of a text, performance or design","definitionCN":"文本、表演或设计表面之下的一股情绪暗流","example":"Critics heard a subconscious grief under the cheerful melody.","exampleCN":"评论家听出欢快旋律之下有一种潜意识的哀伤。","why":"the term is borrowed for works of art because a work also has a surface and something moving beneath it.","whyCN":"这个词被借去谈艺术作品，因为作品同样有表面，也有在表面之下流动的东西。"},{"no":"08","title":"A layer between two others","titleCN":"夹在另两层之间的那一层","definition":"in some psychological models, the tier that sits below the conscious and above the unconscious","definitionCN":"在某些心理学模型里，位于意识之下、无意识之上的那一层","example":"The model treats the subconscious as a corridor rather than a room.","exampleCN":"该模型把潜意识当作一条走廊，而不是一个房间。","why":"the prefix means under, not fully away, so the word fits a middle position whenever a three-part map is used.","whyCN":"前缀的意思是「在下」，而不是「完全离开」，因此在三分地图里它正好占中间位置。"}],"etymology":{"intro":{"en":"Subconscious is a modern learned compound of Latin origin: the prefix sub- 'under' placed before conscious. It was coined in the nineteenth century, when psychology needed a term for mental activity that is real but unlighted. Dates are approximate.","cn":"subconscious 是近代按拉丁语素造出的学术复合词：把表「在下」的前缀放在 conscious 之前。19 世纪造出，当时心理学需要一个名称，指真实存在却未被照亮的心理活动。年代均为约数。"},"items":[{"era":"LATIN SUB","en":"Sub meant 'under, below, beneath'. English freely attaches it to adjectives and nouns to place something at a lower level, as in submarine or subtitle.","cn":"sub 意为「在下、低于、底下」。英语自由地把它加在形容词与名词前，把某物放到较低层级，如潜水艇、副标题。"},{"era":"LATIN CONSCIOUS","en":"The second element is the Latin-derived adjective for being aware, itself built on a prefix meaning 'together' and a verb meaning 'to know'.","cn":"第二个成分是那个来自拉丁、表示「觉察」的形容词，它本身由表「共同」的前缀和表「知道」的动词构成。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"The compound appears in nineteenth-century psychological writing, alongside the older negative form, to name mental work that goes on under the threshold of attention.","cn":"这个词组出现在 19 世纪心理学著述中，与更早的否定形式并用，用来命名在注意阈限之下进行的心理活动。"},{"era":"POPULAR DIFFUSION","en":"Twentieth-century popular psychology and advertising carried the word out of the clinic, so that it now also describes ordinary unthinking habits.","cn":"20 世纪的通俗心理学与广告把它带出诊所，于是它如今也用来描述日常中不过脑的习惯。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact first use of the compound is not fixed, and whether it was modelled on a German term of the same shape is a hypothesis rather than a demonstrated fact.","cn":"来源不确定：这个词组最早的确切用例未定；它是否仿照同形的德语术语造出，属于假说而非已证实的事实。"}]},"similar":{"note":{"en":"Group one holds the prefixed neighbours that are constantly mixed up; group two holds words for what happens outside attention.","cn":"第一组是带前缀、极易混用的邻近词；第二组是表示「注意之外所发生之事」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"unconscious","ipa":"/ʌnˈkɒnʃəs/","tag":"not, rather than under","definition":"The negative prefix says 'not aware', so it covers fainting and complete unawareness; subconscious says 'under awareness', which still allows a faint rim of knowing.","definitionCN":"否定前缀表示「不觉察」，因此涵盖昏厥与完全不知；subconscious 表示「在觉察之下」，仍允许有一圈微弱的知。"},{"word":"preconscious","ipa":"/ˌpriːˈkɒnʃəs/","tag":"before awareness","definition":"A term for material that is not in mind at the moment but can be recalled at once, sitting just outside rather than underneath.","definitionCN":"指当下不在心中、却能立刻唤回的材料，位置是在外面而非下面。"},{"word":"unconsciousness","ipa":"/ʌnˈkɒnʃəsnəs/","tag":"medical state","definition":"The state of being unaware, often used for coma; it is a condition, not a layer of the mind.","definitionCN":"不觉察的状态，常用于昏迷；是一种状况，而非心智的一层。"},{"word":"subconsciousness","ipa":"/ˌsʌbˈkɒnʃəsnəs/","tag":"same word, noun form","definition":"The abstract noun of this adjective; it stresses the state, while subconscious usually stresses the place or the influence.","definitionCN":"本形容词的抽象名词形式；侧重状态，而 subconscious 通常侧重位置或影响。"}]},{"heading":"NEAR MEANING","entries":[{"word":"instinctive","ipa":"/ɪnˈstɪŋktɪv/","tag":"born, not learned","definition":"Built into the species rather than stored in one mind; an instinctive reaction needs no personal history behind it.","definitionCN":"是物种天生具备的，而非存在某一颗心里；本能反应不需要个人经历作背景。"},{"word":"involuntary","ipa":"/ɪnˈvɒləntri/","tag":"not willed","definition":"Describes acts outside conscious control, such as a blink; it names the lack of will rather than the hidden cause.","definitionCN":"描述不受意识控制的行为，如眨眼；它指出的是「无意志」，而非隐藏的起因。"},{"word":"implicit","ipa":"/ɪmˈplɪsɪt/","tag":"unstated","definition":"Said of knowledge or bias that is present but not spelled out; it can be fully conscious, so it is not a synonym.","definitionCN":"指存在却未被明说的知识或偏见；它可以是完全自觉的，因此不是同义词。"},{"word":"underlying","ipa":"/ˌʌndəˈlaɪɪŋ/","tag":"beneath as a cause","definition":"Names what lies beneath and explains what is seen, without implying anything about awareness at all.","definitionCN":"指位于其下、能解释可见现象的东西，完全不涉及觉察与否。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The prefix means 'under': the subconscious is literally the conscious layer placed lower.","cn":"前缀意为「在下」：潜意识字面上就是把意识那层放到下面。"},{"en":"The family runs subconscious, subconsciously, subconsciousness, conscious, unconscious, preconscious.","cn":"同族词包括 subconscious、subconsciously、subconsciousness、conscious、unconscious、preconscious。"},{"en":"Fixed phrases mark the uses: the subconscious mind, subconscious bias, at a subconscious level.","cn":"固定搭配标出用法：潜意识、不自觉的偏见、在潜意识层面。"},{"en":"The three-layer model conscious, subconscious, unconscious is the usual diagram this word sits in.","cn":"意识、潜意识、无意识这三层模型，正是这个词通常所在的那张图。"},{"en":"Advertising and popular psychology are the two places the word spread fastest.","cn":"广告与通俗心理学是这个词扩散最快的两个地方。"}],"abstract":[{"en":"Picture a current below a calm surface that moves the boat while the sailor sees only glass.","cn":"想象平静水面下的一股洋流，水手只看见镜面，船却被推着走。"},{"en":"Picture a file left in a drawer that still changes how the room is arranged.","cn":"想象一份留在抽屉里的档案，仍在改变房间的摆法。"},{"en":"Picture a whisper just below the range of hearing that still makes you turn your head.","cn":"想象一声刚好在听觉范围之下的低语，仍让你转过头。"}]},"examples":[{"en":"Subconscious habits often survive even when the reason behind them is gone.","cn":"下意识的习惯常常在背后的理由消失之后仍然保留。"},{"en":"She chose the same colour again, on a subconscious level.","cn":"她在潜意识层面又一次选了同一个颜色。"},{"en":"The advertisement works on the subconscious rather than on argument.","cn":"这则广告作用于潜意识，而非诉诸论证。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"sub（在下）+ conscious（有意识）——意识下面那一层 → 下意识的、潜意识","word":"subconscious"},"root":"拉丁语素复合：表「在下」的前缀 sub 加 conscious（源自拉丁 conscius「与……同知」）；19 世纪心理学造词，用来指注意阈限之下仍在运作的心理活动。","sensesIntro":{"en":"Eight senses follow one movement: a current runs under the surface, and that current is then named as a place, filled with contents, felt as resistance, borrowed for art and finally placed between two other layers.","cn":"八个义项沿一个动作展开：一股水流在表面之下运行，随后这股水流被命名成一个地方、被填进内容、被感觉为抗拒、被借去谈艺术，最后被放到另外两层之间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a current under a calm surface, moving the boat while the sailor sees only still water.","cn":"核心意象：平静表面下的一股水流，水手只看见静止的水，船却在移动。"},"chain":["UNDER THE SURFACE","STORED BUT UNOPENED","HALF ABOVE","NAMED AS A PLACE","ITS CONTENTS","PUSHING BACK"],"branches":[{"senses":"01 · 03","en":"THE CURRENT AND THE WATERLINE: one sense is the pull itself, the other is a person whose awareness sits exactly at the surface.","cn":"水流与水面线：一个义项是牵引本身，另一个是觉察恰好停在水面上的那种人。"},{"senses":"02","en":"THE UNOPENED FILE: what is kept below is not gone, only unread, and it still changes reactions.","cn":"未打开的档案：存在下面的东西并未消失，只是没被读，仍在改变反应。"},{"senses":"04 · 08","en":"A PLACE AND ITS ADDRESS: the noun turns the layer into a location, and the model gives that location a middle floor.","cn":"地点与它的门牌：名词把这一层变成一个位置，而模型又给这个位置安排了一个中间楼层。"},{"senses":"05","en":"THE FURNITURE OF THAT PLACE: wishes, images and dreams are what the hidden room is said to hold.","cn":"那个地点的家具：愿望、意象与梦，就是据说藏在暗室里的东西。"},{"senses":"06 · 07","en":"THE CURRENT FELT OUTSIDE: it reaches us as resistance in the body, or as an undercurrent in a work of art.","cn":"水流在外被感知：它抵达我们时，要么是身体里的抗拒，要么是艺术品底下的暗流。"}]},"affixes":{"intro":{"en":"The word is built from two Latin elements, one a prefix of position and one an adjective of awareness, so both halves are transparent.","cn":"这个词由两个拉丁成分搭成：一个是表位置的前缀，一个是表觉察的形容词，两半都很透明。"},"latinIntro":{"en":"Latin sub- 'under' is the same prefix seen in submarine and subordinate; the base adjective goes back to a verb meaning 'to know'.","cn":"拉丁前缀表示「在下」，与潜水艇、下属两词中的前缀相同；词基形容词则上溯到一个意为「知道」的动词。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under, below')","meaning":"under; below; secondary","meaningCN":"在下；低于；次要","example":"The prefix places the whole word at a lower level.","exampleCN":"这个前缀把整个词放到较低层级。"},{"word":"conscious","structure":"conscius (Latin adjective, borrowed)","meaning":"aware, awake","meaningCN":"觉察的；清醒的","example":"The base supplies the idea of awareness.","exampleCN":"词基提供「觉察」的意思。"},{"word":"subconscious","structure":"sub- + conscious","meaning":"below ordinary awareness","meaningCN":"在通常觉察之下的","example":"A subconscious pull made him sit down.","exampleCN":"一股下意识的牵引让他坐了下来。"},{"word":"subconsciously","structure":"subconscious + -ly (adverb)","meaning":"without noticing","meaningCN":"不知不觉地","example":"He subconsciously copied her gesture.","exampleCN":"他不自觉地模仿了她的动作。"},{"word":"subconsciousness","structure":"subconscious + -ness (state)","meaning":"the state of being below awareness","meaningCN":"潜意识状态","example":"The term names a state rather than a place.","exampleCN":"这个术语命名的是状态，而不是地点。"},{"word":"unconscious","structure":"un- 'not' + conscious","meaning":"not aware at all","meaningCN":"完全不觉察的","example":"She was unconscious for a minute.","exampleCN":"她有一分钟失去知觉。"},{"word":"preconscious","structure":"pre- 'before' + conscious","meaning":"just outside awareness but easily recalled","meaningCN":"在觉察之外却易被唤回的","example":"A preconscious memory surfaced at once.","exampleCN":"一段前意识的记忆立刻浮现。"},{"word":"submarine","structure":"sub- + marine ('of the sea')","meaning":"a vessel that travels under the sea","meaningCN":"潜艇","example":"The same prefix shows its positional force here.","exampleCN":"同一个前缀在这里显出它的位置义。"}],"latinEntries":[{"word":"sub","structure":"sub (Latin preposition and prefix, 'under, below')","meaning":"under, below, beneath","meaningCN":"在下；低于；底下"},{"word":"conscius","structure":"com- + scire (adjective)","meaning":"privy to, conscious of","meaningCN":"知情的；自觉的"},{"word":"conscientia","structure":"conscius + -ia (noun)","meaning":"inner awareness, conscience","meaningCN":"内心觉察；良心"}],"derivatives":[{"word":"subconsciously","pos":"adv.","zh":"下意识地；不知不觉地"},{"word":"subconsciousness","pos":"n.","zh":"潜意识状态"},{"word":"subconscious bias","pos":"n. phrase","zh":"不自觉的偏见"},{"word":"semisubconscious","pos":"adj.","zh":"半下意识的（少用）"}]}},{"word":"unconscious","ipa_uk":"/ʌnˈkɒnʃəs/","ipa_us":"/ʌnˈkɑːnʃəs/","definition_zh":"失去知觉的；昏迷的；无意识的；未察觉的；非故意的；潜意识（名词）","definition_en":"not awake and not able to respond, or happening without awareness or intention","core_image":"灯被关掉，房间里一切照旧，只是没有人再看见它们","scene":"球场上两个人争抢时头部相撞，其中一人倒地不动，队医跑过去先看瞳孔再看呼吸。The referee stopped the match at once when one player lay unconscious on the grass.","sceneCN":"这里 unconscious 指「失去知觉、无法回应的状态」（第 1 个义项：昏迷、不能回应）；句意为一名球员倒在草地上失去知觉，裁判立刻中止了比赛。图中可辨识物件：草地、倒地的球员、队医的手电。","pos":[{"tag":"adj.","zh":"失去知觉的；昏迷的；无意识的；未察觉的；非故意的"},{"tag":"n.","zh":"无意识（精神分析用语，指心智中不被觉察的部分）"}],"collocations":[{"phrase":"unconscious of","zh":"未察觉到的"},{"phrase":"knock somebody unconscious","zh":"把某人打昏"},{"phrase":"the unconscious mind","zh":"无意识"},{"phrase":"unconscious bias","zh":"无意识的偏见"},{"phrase":"unconscious habit","zh":"不自觉的习惯"},{"phrase":"unconscious process","zh":"不受意识控制的生理过程"}],"forms":[{"label":"比较级（多与 more 连用）","form":"more unconscious"},{"label":"最高级（多与 most 连用）","form":"most unconscious"},{"label":"副词","form":"unconsciously"},{"label":"名词（状态）","form":"unconsciousness"},{"label":"复数（名词，少见）","form":"unconsciouses"}],"derivatives":[{"word":"unconsciously","pos":"adv.","zh":"无意识地；不知不觉地"},{"word":"unconsciousness","pos":"n.","zh":"昏迷；无意识状态"},{"word":"conscious","pos":"adj.","zh":"有意识的；清醒的"},{"word":"subconscious","pos":"adj./n.","zh":"下意识的 / 潜意识"},{"word":"unconscious bias","pos":"n. phrase","zh":"无意识偏见"}],"senses":[{"no":"01","title":"Not awake and not responding","titleCN":"失去知觉、不能回应","definition":"in a state like deep sleep or coma, unable to see, hear or react","definitionCN":"处于类似深睡或昏迷的状态，看不见、听不见也无法反应","example":"The referee stopped the match when one player lay unconscious.","exampleCN":"一名球员倒地失去知觉，裁判中止了比赛。","why":"the plain negative prefix switches the light off entirely, which is why this sense is the one used in emergency reports.","whyCN":"单纯的否定前缀把灯完全关掉，因此急诊报告用的正是这个义项。"},{"no":"02","title":"Acting without noticing","titleCN":"做而不自知","definition":"doing something without paying attention to it at the moment of doing","definitionCN":"在做的时候并未注意自己正在做","example":"She unconsciously straightened the papers on his desk.","exampleCN":"她无意识地把他的桌上的纸张摆正。","why":"the body can carry out a familiar act while the mind is elsewhere, so the act is done yet not witnessed.","whyCN":"身体可以在心思他顾时完成熟悉动作，于是动作发生了，却没有被目击。"},{"no":"03","title":"The hidden layer of the mind","titleCN":"心智中不被照亮的那一层","definition":"the part of mental life that is said to work outside awareness and yet to shape it","definitionCN":"据称在觉察之外运作、却又塑造觉察的那部分心理生活","example":"The theory holds that the unconscious speaks through slips of the tongue.","exampleCN":"该理论认为无意识借口误发声。","why":"psychology needed a noun for what the light never reaches, and the negative adjective supplied it.","whyCN":"心理学需要一个名词来指灯光永远照不到的地方，这个否定形容词正好提供了它。"},{"no":"04","title":"Not intended","titleCN":"并非有意","definition":"done by accident, with no intention behind it","definitionCN":"出于偶然，背后没有意图","example":"He offered an unconscious slight by mispronouncing her name.","exampleCN":"他把她的名字念错，无意中冒犯了她。","why":"if the doer never saw the act coming, there was no intention, so the word slides from awareness to intent.","whyCN":"既然做事的人从未预见这个动作，就没有意图，于是词义从「觉察」滑向「意图」。"},{"no":"05","title":"The unconscious as a system","titleCN":"作为一套系统的无意识","definition":"in psychoanalysis, the whole structure of drives and memories kept out of awareness","definitionCN":"在精神分析中，被挡在觉察之外的驱力与记忆所构成的整体结构","example":"Freud gave the unconscious a grammar of its own.","exampleCN":"弗洛伊德给无意识配了一套自己的语法。","why":"a negative adjective becomes a proper noun when a whole theory is built around it.","whyCN":"当整套理论围着它建立起来时，一个否定形容词就变成了专有名词。"},{"no":"06","title":"Revealing what was not meant to show","titleCN":"流露了本不打算显露的东西","definition":"showing a feeling or attitude that the person would not choose to display","definitionCN":"显露出本人不会主动展示的情绪或态度","example":"An unconscious flicker of annoyance crossed his face.","exampleCN":"一丝不自觉的烦躁掠过他的脸。","why":"the hidden layer leaks, and the leak is visible precisely because nobody was managing the face.","whyCN":"隐藏的那层会渗漏，而渗漏之所以看得见，正因为没人当时在管理表情。"},{"no":"07","title":"Unaware of a fact","titleCN":"对某事实并不知情","definition":"not knowing that something is the case, often something important happening nearby","definitionCN":"不知道某事确实如此，通常是身边正在发生的重要事情","example":"He walked on, unconscious of the crowd gathering behind him.","exampleCN":"他继续往前走，并未察觉身后聚起的人群。","why":"this sense keeps the old construction with 'of', where the negative simply cancels awareness of an object.","whyCN":"这个义项保留了后接介词的老结构，否定只是取消了针对某个对象的觉察。"},{"no":"08","title":"Outside conscious control","titleCN":"不受意识控制","definition":"describing body processes such as breathing in sleep, which run without direction","definitionCN":"描述睡眠中的呼吸一类身体过程，无需指挥便自行运行","example":"Digestion is an unconscious process that continues all night.","exampleCN":"消化是不受意识控制的过程，整夜都在继续。","why":"physiology uses the word for what the will cannot reach, which is the cleanest case of 'not conscious'.","whyCN":"生理学用它指意志够不到的地方，这是「非意识」最干净的用例。"}],"etymology":{"intro":{"en":"Unconscious is conscious with the native negative prefix un-. The adjective is recorded from the eighteenth century; the noun, as a name for a hidden region of the mind, belongs to nineteenth-century psychology. Dates are approximate.","cn":"unconscious 是 conscious 加本族语的否定前缀构成的。形容词见于 18 世纪；作名词、用来指心智中隐藏区域的用法，则属于 19 世纪心理学。年代均为约数。"},"items":[{"era":"OLD ENGLISH NEGATIVE","en":"The prefix un- is native Germanic and freely cancels adjectives, as in unable and unfair; it is not a Latin borrowing.","cn":"这个否定前缀是日耳曼语本族成分，可以自由地否定形容词，如不能、不公；它并非拉丁借词。"},{"era":"LATIN BASE","en":"The adjective it negates goes back to a Latin adjective meaning 'knowing with', itself built on a verb meaning 'to know'.","cn":"被否定的那个形容词上溯到一个意为「与……同知」的拉丁形容词，它由意为「知道」的动词构成。"},{"era":"EIGHTEENTH-CENTURY USE","en":"Early records mean simply 'not aware of something', often in the phrase unconscious of, with no psychological theory behind it.","cn":"早期书证的意思只是「未察觉某事」，常出现在后接介词的说法里，背后并无心理学理论。"},{"era":"NINETEENTH-CENTURY NOUN","en":"Romantic writers and then psychologists turned the adjective into a noun, naming a region of the mind that works in the dark.","cn":"浪漫派作家继而心理学家把这个形容词变成名词，命名心智中在暗处运作的一块区域。"},{"era":"TWENTIETH-CENTURY SCIENCE","en":"The noun was extended to automatic body processes and, later, to social attitudes that people do not admit holding.","cn":"这个名词后来延伸到自动的身体过程，再延伸到人们不肯承认自己持有的社会态度。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: no single first citation for the noun is agreed, and the pre-Latin origin of the base root remains a reconstruction.","cn":"来源不确定：这个名词最早的确切书证没有公认结论，词根在拉丁语之前的来源仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds the prefixes that are constantly confused because they all sit near this word; group two holds words about acts done without a will behind them.","cn":"第一组是位置都贴着本词、因而常被混淆的前缀词；第二组是表示「背后没有意志」的行为的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"subconscious","ipa":"/ˌsʌbˈkɒnʃəs/","tag":"under, not absent","definition":"Places the layer under awareness, which still allows a faint knowing; this word cancels awareness, so the two are not interchangeable in medical talk.","definitionCN":"把那一层放到觉察之下，仍允许微弱的知；本词则取消觉察，因此在医学语境里两者不能互换。"},{"word":"preconscious","ipa":"/ˌpriːˈkɒnʃəs/","tag":"outside but reachable","definition":"Names material that is out of mind yet instantly recallable, so it is accessible rather than hidden.","definitionCN":"指不在心中却能立刻唤回的材料，因此是可取用的，而非隐藏的。"},{"word":"unconsciousness","ipa":"/ʌnˈkɒnʃəsnəs/","tag":"the state, as a noun","definition":"The abstract noun for the medical condition; it cannot refer to a theory or a layer of the mind.","definitionCN":"指那种医学状况的抽象名词；不能指一套理论或心智的一层。"},{"word":"conscientious","ipa":"/kənˈʃiːənʃəs/","tag":"looks alike, feels opposite","definition":"Same Latin stock but a completely different word: it praises careful dutifulness, while this word says awareness is missing.","definitionCN":"同出拉丁词源却是完全不同的词：它称赞认真尽责，而本词说的是觉察缺席。"}]},{"heading":"NEAR MEANING","entries":[{"word":"comatose","ipa":"/ˈkəʊmətəʊs/","tag":"medical depth","definition":"A clinical term for a prolonged state of deep unresponsiveness, narrower and graver than simply being unconscious.","definitionCN":"指长时间深度无反应的临床术语，比一般的失去知觉更窄也更严重。"},{"word":"involuntary","ipa":"/ɪnˈvɒləntri/","tag":"no will","definition":"Says an act happens without the will, but says nothing about whether the person knew; a cough can be involuntary yet fully felt.","definitionCN":"说行为不经意志，却不涉及当事人是否知道；咳嗽可以不由自主却完全被感觉到。"},{"word":"automatic","ipa":"/ɔːˈtɒmətɪk/","tag":"by mechanism","definition":"Stresses a mechanism running by itself, as with a door or a reflex, not the absence of a mind.","definitionCN":"强调机制自行运转，如门或反射，而不是心智的缺席。"},{"word":"unaware","ipa":"/ˌʌnəˈweə/","tag":"not knowing only","definition":"Covers only the sense of not knowing a fact; it never means fainting and never names a layer of the mind.","definitionCN":"只覆盖「不知道某事实」这一义，从不表示昏厥，也不指心智的一层。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The negative prefix is native English and simply cancels the awareness in the base word.","cn":"这个否定前缀是英语本族成分，只是取消了词基里的觉察。"},{"en":"The family runs unconscious, unconsciously, unconsciousness, conscious, subconscious, preconscious.","cn":"同族词包括 unconscious、unconsciously、unconsciousness、conscious、subconscious、preconscious。"},{"en":"Fixed phrases mark the uses: unconscious of, the unconscious mind, unconscious bias.","cn":"固定搭配标出用法：未察觉到、无意识、无意识的偏见。"},{"en":"Medicine uses it for fainting; psychology uses it for a layer; everyday speech uses it for acts done without noticing.","cn":"医学用它说昏厥，心理学用它说一个层面，日常口语用它说没注意就做了的事。"},{"en":"The opposite pair conscious and unconscious is the backbone of every three-layer diagram.","cn":"意识与无意识这一对反义，是每张三层图的主干。"}],"abstract":[{"en":"Picture a room that keeps its furniture while the switch stays off.","cn":"想象一间家具照旧、开关却一直关着的房间。"},{"en":"Picture a hand writing a letter while the writer looks out of the window.","cn":"想象一只手在写信，写信的人却望着窗外。"},{"en":"Picture a basement where the lights never work but the machines still run.","cn":"想象一间灯永远不亮、机器却仍在转的地下室。"}]},"examples":[{"en":"He was unconscious for two minutes after the fall.","cn":"摔倒之后他失去知觉两分钟。"},{"en":"The bias is unconscious because nobody believes they hold it.","cn":"这种偏见是无意识的，因为没人相信自己持有它。"},{"en":"Breathing during sleep is an unconscious process.","cn":"睡眠中的呼吸是不受意识控制的过程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"un（不）+ conscious（有意识）——不再有意识 → 昏迷的、无意识的","word":"unconscious"},"root":"英语在 conscious 前加本族否定前缀 un 构成；conscious 源自拉丁 conscius「与……同知」，词根意为「知道」，更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: the light goes out, and then that going-out is read as an act done without watching, a layer of the mind, a lack of intent, a theory, a leak, a missed fact and finally a body process.","cn":"八个义项沿一个动作展开：灯熄灭了，随后这次熄灭依次被读作「没看就做」的动作、心智的一层、意图的缺席、一套理论、一次渗漏、一个被错过的事实，最后是不受控的身体过程。"},"semanticMap":{"core":{"en":"CORE IMAGE: a room whose switch is off, with the furniture still where it was and nobody there to see it.","cn":"核心意象：开关关着的房间，家具仍在原处，却没有人看见。"},"chain":["LIGHT OFF","ACT UNWITNESSED","A HIDDEN LAYER","NO INTENTION","LEAKAGE","BODY ON ITS OWN"],"branches":[{"senses":"01","en":"THE SWITCH ITSELF: the medical sense, where the person is present but no light is on.","cn":"开关本身：医学义，人在场，却没有灯亮着。"},{"senses":"02 · 04","en":"THE UNWITNESSED ACT AND ITS INTENT: first the deed happens unobserved, then the law reads that as no intention at all.","cn":"未被目击的动作与意图：先是行为在无人观看时发生，随后法律把它读成完全没有意图。"},{"senses":"03 · 05","en":"THE DARK REGION AND THE THEORY OF IT: psychology turns the off-switch into a place, then builds a whole grammar around that place.","cn":"暗区与其理论：心理学把这个关掉的开关变成一个地点，再围着这个地点造出整套语法。"},{"senses":"06 · 07","en":"TWO KINDS OF NOT KNOWING: one leaks out on the face, the other is a fact walking past unseen.","cn":"两种不知：一种从脸上渗出来，另一种是事实从身边走过而未被看见。"},{"senses":"08","en":"THE BODY WITHOUT A SWITCH: physiology's sense, where no light was ever needed in the first place.","cn":"没有开关的身体：生理学的义项，那里本来就不需要灯。"}]},"affixes":{"intro":{"en":"One native negative prefix sits on a Latin-derived adjective, which makes the word unusually easy to take apart.","cn":"一个本族否定前缀叠在一个来自拉丁的形容词上，因此这个词特别容易拆开看。"},"latinIntro":{"en":"The base adjective goes back to Latin scire 'to know' through a prefixed form meaning 'knowing with'; the negating prefix is Germanic.","cn":"词基形容词经一个意为「与……同知」的带前缀形式上溯到拉丁 scire「知道」；否定前缀则是日耳曼语成分。"},"items":[{"word":"un-","structure":"un- (native English negative prefix)","meaning":"not","meaningCN":"不；非","example":"The prefix simply cancels the adjective.","exampleCN":"这个前缀只是取消了那个形容词。"},{"word":"conscious","structure":"conscius (Latin adjective, borrowed)","meaning":"aware, awake","meaningCN":"觉察的；清醒的","example":"The base supplies awareness.","exampleCN":"词基提供「觉察」。"},{"word":"unconscious","structure":"un- + conscious","meaning":"not aware; not intended","meaningCN":"不觉察的；非故意的","example":"He lay unconscious on the grass.","exampleCN":"他躺在草地上失去知觉。"},{"word":"unconsciously","structure":"unconscious + -ly (adverb)","meaning":"without noticing","meaningCN":"无意识地；不知不觉地","example":"She unconsciously straightened the papers.","exampleCN":"她无意识地把纸张摆正。"},{"word":"unconsciousness","structure":"unconscious + -ness (state)","meaning":"a state of not being aware","meaningCN":"无意识状态；昏迷","example":"Unconsciousness lasted less than a minute.","exampleCN":"失去意识不到一分钟。"},{"word":"subconscious","structure":"sub- 'under' + conscious","meaning":"below awareness","meaningCN":"觉察之下的","example":"Subconscious habits are hard to name.","exampleCN":"下意识的习惯很难说清。"},{"word":"preconscious","structure":"pre- 'before' + conscious","meaning":"outside awareness but recallable","meaningCN":"觉察之外却可唤回的","example":"A preconscious image came back at once.","exampleCN":"一个前意识的意象立刻回来了。"},{"word":"unaware","structure":"un- + aware","meaning":"not knowing a fact","meaningCN":"不知道某事实的","example":"He was unaware of the crowd.","exampleCN":"他没察觉身后的人群。"}],"latinEntries":[{"word":"scire","structure":"scire, scio, scivi, scitum (verb, fourth conjugation)","meaning":"to know, understand","meaningCN":"知道；懂得"},{"word":"conscius","structure":"com- + scire (adjective)","meaning":"privy to, conscious of","meaningCN":"知情的；自觉的"}],"derivatives":[{"word":"unconsciously","pos":"adv.","zh":"无意识地；不知不觉地"},{"word":"unconsciousness","pos":"n.","zh":"昏迷；无意识状态"},{"word":"unconscious bias","pos":"n. phrase","zh":"无意识偏见"},{"word":"semiconscious","pos":"adj.","zh":"半清醒的"}]}},{"word":"subconsciousness","ipa_uk":"/ˌsʌbˈkɒnʃəsnəs/","ipa_us":"/ˌsʌbˈkɑːnʃəsnəs/","definition_zh":"潜意识状态；下意识的心理活动；半清醒状态；未进入注意的隐约感知","definition_en":"the condition of mental life going on below ordinary awareness","core_image":"一栋房子上层点着灯，地下的管道仍在输水，热气顺着墙往上爬，屋里的人只觉得墙是温的","scene":"深夜写字的人没听见窗外雨声，笔却越写越快，句子也越来越短，直到天亮才发现纸上有水汽。A slow subconsciousness shaped the rhythm of the page long before he noticed the rain.","sceneCN":"这里 subconsciousness 指「未进入注意、却持续影响产出的心理状态」（第 1 个义项：在觉察之下的心理状态）；句意是一种缓慢的潜意识状态，在他注意到雨之前就已决定了这一页的节奏。图中可辨识物件：台灯、稿纸、窗上的水汽。","pos":[{"tag":"n.","zh":"潜意识状态；下意识的心理活动；半清醒状态"}],"collocations":[{"phrase":"a state of subconsciousness","zh":"潜意识状态"},{"phrase":"sink into subconsciousness","zh":"沉入潜意识状态"},{"phrase":"the realm of subconsciousness","zh":"潜意识领域"},{"phrase":"collective subconsciousness","zh":"集体潜意识"},{"phrase":"surface from subconsciousness","zh":"从潜意识中浮现"}],"forms":[{"label":"复数（少见）","form":"subconsciousnesses"},{"label":"形容词形式","form":"subconscious"},{"label":"副词形式","form":"subconsciously"},{"label":"相近名词","form":"unconsciousness"},{"label":"反义名词","form":"consciousness"}],"derivatives":[{"word":"subconscious","pos":"adj./n.","zh":"下意识的 / 潜意识"},{"word":"subconsciously","pos":"adv.","zh":"下意识地"},{"word":"consciousness","pos":"n.","zh":"意识；知觉"},{"word":"unconsciousness","pos":"n.","zh":"无意识状态；昏迷"}],"senses":[{"no":"01","title":"Mental life below the surface","titleCN":"表面之下的心理生活","definition":"the condition in which thinking and feeling continue without being noticed","definitionCN":"思考与感受在未被注意的情况下继续进行的状况","example":"A slow subconsciousness shaped the rhythm of the page.","exampleCN":"一种缓慢的潜意识状态决定了这一页的节奏。","why":"the noun names a condition rather than a place, so it can be entered, left and measured in degrees.","whyCN":"这个名词命名的是状况而非地点，因此可以被进入、离开，也可以按程度衡量。"},{"no":"02","title":"Automatic inner work","titleCN":"自动进行的心理运作","definition":"the ordinary sorting, connecting and rehearsing that the mind does without being asked","definitionCN":"心智未经要求便自行进行的归类、联结与预演","example":"Repetition moved the sentence into subconsciousness, where it repeated itself.","exampleCN":"重复让那句话进入潜意识，在那里自己反复起来。","why":"once a task has been handed down to the lower level, it runs on its own and surfaces only as a result.","whyCN":"任务一旦被交给下层，便自行运转，只以结果的形式浮上来。"},{"no":"03","title":"Half waking","titleCN":"半睡半醒","definition":"a drowsy condition in which some impressions register but full awareness does not return","definitionCN":"昏沉之中，部分印象被接收，完整觉察却没有回来","example":"In the first minutes after waking he still moved in subconsciousness.","exampleCN":"刚醒的几分钟里，他仍处在半醒的潜意识状态。","why":"the word literally means the state of being under awareness, and the surface can be crossed by halves.","whyCN":"这个词字面就是「在觉察之下的状态」，而水面是可以只过一半的。"},{"no":"04","title":"Impressions below attention","titleCN":"未进入注意的印象","definition":"sights and sounds that are registered without being attended to at the time","definitionCN":"当时未被留意、却仍被记录下来的景象与声音","example":"The hum of the train stayed in subconsciousness and came back as a dream.","exampleCN":"火车的嗡鸣留在潜意识里，后来以梦的形式回来。","why":"registration and attention are two different doors, and this word names the state of the first door being open alone.","whyCN":"记录与注意是两扇不同的门，这个词命名的正是只开第一扇门的状态。"},{"no":"05","title":"The shared lower layer","titleCN":"共有的下层","definition":"a common reservoir of images and patterns said to be shared by a whole group or species","definitionCN":"据称由整个群体或物种共有的一处意象与模式储藏所","example":"He argued that myths rise out of a collective subconsciousness.","exampleCN":"他认为神话从集体潜意识中升起。","why":"the noun is lifted from one sleeper to a whole people, which is how the collective phrase came about.","whyCN":"这个名词从单个睡者抬到整个民族，集体这一说法正是这样来的。"},{"no":"06","title":"An unexamined preference","titleCN":"未经审视的偏好","definition":"a like or dislike that operates steadily without ever being put into words","definitionCN":"一种稳定起作用、却从未被说成话的好恶","example":"His subconsciousness favoured round numbers before any argument began.","exampleCN":"在争论开始之前，他的潜意识已经偏向整数。","why":"preferences can be formed below and then arrive in behaviour fully dressed, with no reasoning attached.","whyCN":"偏好可以在下层形成，然后整装出现在行为里，后面不带任何推理。"},{"no":"07","title":"The region as a research label","titleCN":"作为研究标签的那一区域","definition":"the name given in older psychology to the whole field between attention and the deepest layer","definitionCN":"旧日心理学给注意与最深那层之间整片区域所起的名字","example":"Textbooks of the period treat subconsciousness as a separate chapter.","exampleCN":"那个时期的教科书把潜意识单列一章。","why":"when a field is mapped, each band needs a noun, and this one was given the abstract form of the adjective.","whyCN":"一旦要给领域画图，每一带都需要一个名词，而这一带用的就是那个形容词的抽象形式。"},{"no":"08","title":"How it bends what we do","titleCN":"它如何改变我们的行为","definition":"the influence itself, understood as a pressure that alters choices before they are made","definitionCN":"指那股影响本身，被理解为在选择做出之前就改变选择的压力","example":"The subconsciousness of the crowd turned a quiet street into a route.","exampleCN":"人群的潜意识把一条安静的街变成了一条路线。","why":"the state is finally read as a force, which is what makes the word useful outside psychology.","whyCN":"这个状态最后被读成一股力，这正是这个词在心理学之外也有用的原因。"}],"etymology":{"intro":{"en":"Subconsciousness is built inside English from subconscious plus the state suffix -ness, and subconscious itself is a modern compound of a Latin prefix and a Latin-derived adjective. It belongs to nineteenth-century psychological vocabulary. Dates are approximate.","cn":"subconsciousness 是在英语内部由 subconscious 加表状态的后缀构成的，而 subconscious 本身是近代用拉丁前缀与拉丁来源形容词搭成的复合词。它属于 19 世纪心理学词汇。年代均为约数。"},"items":[{"era":"LATIN SUB","en":"Sub 'under, below' is the positional prefix seen in submarine and subordinate; here it puts a whole layer beneath another.","cn":"sub 意为「在下、低于」，是潜艇、下属等词里的位置前缀；在这里它把一整层放到另一层之下。"},{"era":"LATIN KNOWING","en":"The base adjective descends from a Latin verb meaning 'to know' through a prefixed form meaning 'knowing with oneself'.","cn":"词基形容词经一个意为「与己同知」的带前缀形式，上溯到意为「知道」的拉丁动词。"},{"era":"NINETEENTH-CENTURY COMPOUND","en":"Subconscious appears in nineteenth-century writing on the mind, and the abstract noun follows quickly, since a state needs a noun of its own.","cn":"subconscious 出现在 19 世纪论心智的著述中，抽象名词随即跟上，因为一种状态需要自己的名词。"},{"era":"ENGLISH SUFFIX","en":"The suffix -ness is native Germanic and turns adjectives into names for states, as in darkness and kindness.","cn":"后缀表示状态，是日耳曼语本族成分，把形容词变成状态的名称，如黑暗、善意。"},{"era":"LATER USE","en":"Twentieth-century popular writing extended the noun to groups and to ordinary preferences, which is where most non-technical uses now come from.","cn":"20 世纪通俗写作把这个名词延伸到群体与日常偏好，如今大多数非专业用法都出自这里。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first attested use of the abstract noun is not fixed, and the pre-Latin origin of the base root remains a reconstruction.","cn":"来源不确定：这个抽象名词最早的确切用例未定，词根在拉丁语之前的来源仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds the near-identical nouns that differ only by prefix; group two holds nouns for states of mind that sit close to this one.","cn":"第一组是只差前缀、字形极近的名词；第二组是表示相近心理状态的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"subconscious","ipa":"/ˌsʌbˈkɒnʃəs/","tag":"adjective and place","definition":"The adjective and the common noun for the layer; this word is the abstract name of the condition, so it fits after verbs like sink into.","definitionCN":"既是形容词，也是指那一层的常用名词；本词是那种状况的抽象名称，因此适合跟在「沉入」一类动词之后。"},{"word":"unconsciousness","ipa":"/ʌnˈkɒnʃəsnəs/","tag":"absence, not depth","definition":"Means awareness is gone, as in coma; this word means awareness is still present but working lower down.","definitionCN":"指觉察消失，如昏迷；本词指觉察仍在，只是在更下层运作。"},{"word":"consciousness","ipa":"/kənˈʃʌsnəs/","tag":"the upper floor","definition":"The direct opposite: the lighted state itself, without which the lower layer would have no name.","definitionCN":"直接的反义：那盏亮着的状态本身，没有它，下层也就无从命名。"},{"word":"preconsciousness","ipa":"/ˌpriːˈkɒnʃəsnəs/","tag":"rare, outside","definition":"A rare noun for material just outside awareness that can be recalled at will; the position is outside rather than underneath.","definitionCN":"罕见名词，指刚好在觉察之外、可随意唤回的材料；位置是在外面而非下面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"drowsiness","ipa":"/ˈdraʊzinəs/","tag":"body state","definition":"The physical heaviness before sleep; it explains half waking but says nothing about hidden mental work.","definitionCN":"入睡前身体的沉重感；能解释「半醒」，却不涉及隐藏的心理运作。"},{"word":"trance","ipa":"/trɑːns/","tag":"narrowed attention","definition":"A state of narrowed attention, often induced; it is a condition of the whole person, not a layer of the mind.","definitionCN":"注意收窄的状态，常由外界引发；是整个人的状况，而非心智的一层。"},{"word":"intuition","ipa":"/ɪnˈtjuːɪʃn/","tag":"the result","definition":"What arrives from below as a ready-made judgement; it is the product, while this word names the workshop.","definitionCN":"从下层送达的现成判断；它是产品，而本词命名的是那间作坊。"},{"word":"inner life","ipa":"/ˈɪnə laɪf/","tag":"plain phrase","definition":"An everyday phrase for private thoughts and feelings, including those one is fully aware of.","definitionCN":"指私人念头与感受的日常说法，包含本人完全清楚的那些。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Three pieces: a prefix meaning 'under', an adjective meaning 'aware', and a suffix meaning 'state'.","cn":"三块拼成：表「在下」的前缀、表「觉察」的形容词、表「状态」的后缀。"},{"en":"The family runs subconscious, subconsciously, subconsciousness, consciousness, unconsciousness.","cn":"同族词包括 subconscious、subconsciously、subconsciousness、consciousness、unconsciousness。"},{"en":"Fixed phrases mark the uses: a state of subconsciousness, sink into subconsciousness, surface from subconsciousness.","cn":"固定搭配标出用法：潜意识状态、沉入潜意识、从潜意识中浮现。"},{"en":"The collective phrase comes from the same pattern used by mythographers and early psychology.","cn":"「集体潜意识」这一说法，来自神话研究者与早期心理学使用的同一构词方式。"},{"en":"The abstract noun exists because a condition needs a name, while the adjective already named the place.","cn":"之所以有这个抽象名词，是因为状况需要名称，而形容词已经占用了地点。"}],"abstract":[{"en":"Picture a lit upper floor over a basement where pipes keep moving water all night.","cn":"想象亮着灯的上层，底下是整夜走水的管道。"},{"en":"Picture a hand that keeps writing after the ears have stopped listening.","cn":"想象耳朵早已不听，手却仍在写。"},{"en":"Picture warmth in a wall that nobody can trace back to a fire.","cn":"想象墙面发暖，却没人能把它追到一堆火。"}]},"examples":[{"en":"The phrase describes a subconsciousness that never announces itself.","cn":"这个说法描述的是一种从不自我宣告的潜意识状态。"},{"en":"He sank into a subconsciousness in which old songs kept playing.","cn":"他沉入一种潜意识状态，旧歌在其中反复播放。"},{"en":"Their collective subconsciousness turned the same legend into a shared dream.","cn":"他们的集体潜意识把同一个传说变成了共同的梦。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"sub（在下）+ conscious（有意识）+ ness（状态）——在意识之下的那种状态 → 潜意识状态","word":"subconsciousness"},"root":"英语在 subconscious 上加表状态的后缀构成；subconscious 由表「在下」的拉丁前缀加 conscious（源自拉丁 conscius「与……同知」）搭成，属 19 世纪心理学术语。","sensesIntro":{"en":"Eight senses follow one movement: a lower level keeps working, and that working is read as a condition, as automatic labour, as half waking, as unrecorded impressions, as a shared reservoir, as an unexamined preference, as a research label and finally as a force.","cn":"八个义项沿一个动作展开：下层持续运转，这次运转依次被读作一种状况、自动的劳动、半醒、未被留意的印象、共有的储藏所、未审视的偏好、研究标签，最后是一股力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lit upper floor over a basement where pipes keep moving water all night, warming the wall nobody questions.","cn":"核心意象：亮着灯的上层，底下是整夜走水的管道，把没人追问的墙面烘暖。"},"chain":["BELOW THE FLOOR","RUNNING ON ITS OWN","HALF AWAKE","IMPRESSIONS UNATTENDED","A SHARED RESERVOIR","THE PRESSURE IT PUTS"],"branches":[{"senses":"01 · 03","en":"THE CONDITION AND ITS HALFWAY POINT: the state itself, and the moment when a person crosses it only in part.","cn":"状况与它的一半：状态本身，以及人只过了一半的那个时刻。"},{"senses":"02 · 07","en":"WORK AND ITS CHAPTER TITLE: first the automatic labour, then the textbook habit of naming the whole band.","cn":"劳动与它的章节名：先是自动的劳动，再是教科书给整条带命名的习惯。"},{"senses":"04","en":"THE OPEN DOOR OF REGISTRATION: what enters without being attended stays and returns later.","cn":"记录之门开着：未被留意而进入的东西会留下，并在后来返回。"},{"senses":"05 · 06","en":"SHARED AND PRIVATE LOWER LAYERS: one is a reservoir held by a people, the other a preference held by one person.","cn":"共有与私有的下层：一个是整个民族持有的储藏所，一个是单个人持有的偏好。"},{"senses":"08","en":"THE STATE READ AS A FORCE: the noun finally names pressure rather than condition.","cn":"状态被读成力：这个名词最后命名的是压力，而不是状况。"}]},"affixes":{"intro":{"en":"The word stacks three elements, one positional, one about awareness, one about state, which makes the whole family readable from the outside in.","cn":"这个词叠了三块：一块说位置，一块说觉察，一块说状态，因此整个词族可以从外往内读。"},"latinIntro":{"en":"Latin sub- 'under' plus the Latin-derived adjective of awareness, then a native English state suffix.","cn":"拉丁前缀表「在下」，加上来自拉丁的觉察形容词，最后接一个英语本族的状态后缀。"},"items":[{"word":"sub-","structure":"sub- (Latin prefix, 'under')","meaning":"under; below","meaningCN":"在下；低于","example":"The prefix sets the whole word one level down.","exampleCN":"这个前缀把整个词放低一级。"},{"word":"conscious","structure":"conscius (Latin adjective, borrowed)","meaning":"aware","meaningCN":"觉察的","example":"The adjective supplies the lighted layer.","exampleCN":"这个形容词提供那层亮处。"},{"word":"-ness","structure":"native English state suffix","meaning":"the condition of being X","meaningCN":"处于某种状况","example":"It turns the adjective into a name for a condition.","exampleCN":"它把形容词变成状况的名称。"},{"word":"subconscious","structure":"sub- + conscious","meaning":"below awareness","meaningCN":"觉察之下的","example":"A subconscious wish shaped the choice.","exampleCN":"一个潜意识的愿望塑造了这个选择。"},{"word":"subconsciousness","structure":"subconscious + -ness","meaning":"the condition of working below awareness","meaningCN":"在觉察之下运作的状况","example":"He sank into subconsciousness before dawn.","exampleCN":"天亮前他沉入潜意识状态。"},{"word":"subconsciously","structure":"subconscious + -ly (adverb)","meaning":"without noticing","meaningCN":"不知不觉地","example":"She subconsciously matched his tone.","exampleCN":"她下意识地跟上了他的语气。"},{"word":"unconsciousness","structure":"un- 'not' + consciousness","meaning":"the absence of awareness","meaningCN":"觉察的缺席；昏迷","example":"Unconsciousness followed the collision.","exampleCN":"撞击之后便失去意识。"},{"word":"consciousness","structure":"conscious + -ness","meaning":"the lighted state","meaningCN":"意识；知觉","example":"Consciousness returned slowly.","exampleCN":"意识慢慢恢复。"}],"latinEntries":[{"word":"sub","structure":"sub (Latin preposition and prefix)","meaning":"under, below","meaningCN":"在下；低于"},{"word":"conscius","structure":"com- + scire (adjective)","meaning":"privy to, aware of","meaningCN":"知情的；觉察的"},{"word":"conscientia","structure":"conscius + -ia (noun)","meaning":"inner awareness","meaningCN":"内心觉察"}],"derivatives":[{"word":"subconscious","pos":"adj./n.","zh":"下意识的 / 潜意识"},{"word":"subconsciously","pos":"adv.","zh":"下意识地"},{"word":"collective subconsciousness","pos":"n. phrase","zh":"集体潜意识"},{"word":"subconsciousness","pos":"n.","zh":"潜意识状态"}]}},{"word":"emotion","ipa_uk":"/ɪˈməʊʃn/","ipa_us":"/ɪˈmoʊʃn/","definition_zh":"情绪；情感；激动；动情；情感的表达","definition_en":"a strong feeling such as anger, fear, joy or grief, or feeling regarded as a force in its own right","core_image":"一潭静水被一只手从内部推了一下，整片水面荡开，波纹一直传到岸边","scene":"剧院里，最后一幕的灯暗下去，前排有位观众一直坐着没动，直到同伴轻轻碰她才回过神。The final scene stirred a quiet emotion that kept her in her seat after the lights came up.","sceneCN":"这里 emotion 指「被触动而升起的一种较强烈的感受」（第 1 个义项：如悲伤、感动一类强烈感受）；句意为最后一幕激起一种安静的情绪，让她在灯亮之后仍坐着不动。图中可辨识物件：暗下的舞台、未起身的观众、搭在肩上的手。","pos":[{"tag":"n.","zh":"情绪；情感；激动；动情"},{"tag":"n. (countable)","zh":"一种具体的情绪（如愤怒、恐惧、喜悦）"}],"collocations":[{"phrase":"show emotion","zh":"流露情绪"},{"phrase":"control one's emotions","zh":"控制情绪"},{"phrase":"with emotion","zh":"动情地；带着感情"},{"phrase":"mixed emotions","zh":"复杂的情绪"},{"phrase":"basic emotions","zh":"基本情绪"},{"phrase":"emotion regulation","zh":"情绪调节"}],"forms":[{"label":"复数","form":"emotions"},{"label":"形容词形式","form":"emotional"},{"label":"副词形式","form":"emotionally"},{"label":"相关形容词","form":"emotive"},{"label":"无情绪形容词","form":"emotionless"}],"derivatives":[{"word":"emotional","pos":"adj.","zh":"情绪的；动感情的；动人的"},{"word":"emotionally","pos":"adv.","zh":"情感上；感情用事地"},{"word":"emotive","pos":"adj.","zh":"引起情绪的；易引发争议的"},{"word":"emotionless","pos":"adj.","zh":"无表情的；不带感情的"},{"word":"emotionalism","pos":"n.","zh":"情绪化倾向；重感情的做法"}],"senses":[{"no":"01","title":"A strong feeling","titleCN":"一种较强烈的感受","definition":"a powerful feeling such as fear, anger, joy or grief that rises in a person","definitionCN":"在人心里升起的强烈感受，如恐惧、愤怒、喜悦或悲伤","example":"The final scene stirred a quiet emotion that kept her in her seat.","exampleCN":"最后一幕激起一种安静的情绪，让她一直坐着。","why":"the word was made from a verb meaning 'to move out', so the core picture is something being stirred up and moving through a person.","whyCN":"这个词由意为「向外推动」的动词构成，因此核心画面是某物被搅起、在人身上流动。"},{"no":"02","title":"Feeling as a faculty","titleCN":"作为心智能力的情感","definition":"the whole side of human nature that feels, often set against reason","definitionCN":"人性中负责感受的那一整面，常被拿来与理智对照","example":"The essay asks whether law should answer to reason or to emotion.","exampleCN":"这篇文章追问法律应当服从理智还是情感。","why":"in this sense the word is uncountable and abstract, naming a capacity rather than any single episode of feeling.","whyCN":"这个义项不可数、是抽象的，命名的是能力，而不是某一次具体的感受。"},{"no":"03","title":"Visible agitation","titleCN":"外显的激动","definition":"a state of being moved that shows in voice, face or body","definitionCN":"被触动之后表现在声音、面部或身体上的状态","example":"His voice shook with emotion as he read the letter aloud.","exampleCN":"他朗读那封信时，声音因激动而发颤。","why":"the stirred water reaches the surface, which is why the word can name something listeners can see and hear.","whyCN":"被搅动的水抵达了表面，因此这个词可以命名旁人看得见、听得到的东西。"},{"no":"04","title":"One named kind of feeling","titleCN":"一种被命名的心情类别","definition":"a particular member of the class of feelings, as counted by psychologists","definitionCN":"感受这一类别中的某个具体成员，心理学家会逐个计数","example":"Researchers list fear, anger, joy and sadness as basic emotions.","exampleCN":"研究者把恐惧、愤怒、喜悦与悲伤列作基本情绪。","why":"once feelings are classified, each of them becomes a countable item, which is why the plural is so common in science.","whyCN":"感受一旦被分类，每一种都成了可计数的项，这就是科学文字里复数形式如此常见的原因。"},{"no":"05","title":"Warmth in expression","titleCN":"表达中的温度","definition":"the quality of warmth or force that a performance or speech carries","definitionCN":"一次表演或一段话语所带的温度与力度","example":"She thanked the committee with real emotion, not with a formula.","exampleCN":"她感谢委员会时带着真感情，而不是套话。","why":"the noun can measure how much feeling is packed into an act of expression, not just what the speaker feels.","whyCN":"这个名词衡量的是一次表达里装进了多少感情，而不只是说话人内心的感受。"},{"no":"06","title":"An object of scientific study","titleCN":"科学研究的对象","definition":"the general phenomenon that psychology and neuroscience set out to measure","definitionCN":"心理学与神经科学试图测量的那个总现象","example":"The lab studies how emotion alters memory for faces.","exampleCN":"该实验室研究情绪如何改变对面孔的记忆。","why":"a feeling that has a name can be put under instruments, so the word also serves as the title of a research field.","whyCN":"有了名字的感受就能被放到仪器下，因此这个词同时也充当一个研究领域的标题。"},{"no":"07","title":"Feeling stirred for another","titleCN":"为他人而起的感触","definition":"a sympathetic feeling raised by someone else's situation","definitionCN":"因他人的处境而被唤起的同情式感受","example":"The report describes the emotion of a crowd watching a rescue.","exampleCN":"报道描写了围观救援的人群那种情绪。","why":"the older sense of being moved by an event survives here, with the cause located outside the feeler.","whyCN":"「被事件推动」这一较早的义项在此保留，只是起因位于感受者之外。"},{"no":"08","title":"The body's share of feeling","titleCN":"感受中身体的那一份","definition":"the bodily stirring, such as a racing heart, that comes with a strong feeling","definitionCN":"伴随强烈感受而来的身体反应，如心跳加快","example":"Emotion begins in the body before it reaches words.","exampleCN":"情绪先起于身体，然后才抵达语言。","why":"the same outward-movement image applies inside the body, where blood and breath are what actually move.","whyCN":"同一个「向外推动」的意象也适用于身体内部，那里真正移动的是血与呼吸。"}],"etymology":{"intro":{"en":"Emotion comes through French from Latin emovere 'to move out, stir up', built on ex- 'out' and movere 'to move'. In seventeenth-century English it first named a stirring of the body or of public order, and only later settled on feeling. Dates are approximate.","cn":"emotion 经法语来自拉丁 emovere「推出、搅动」，由表「向外」的前缀与 movere「移动」构成。17 世纪英语中它最初指身体或公共秩序的骚动，后来才固定指感受。年代均为约数。"},"items":[{"era":"LATIN MOVERE","en":"Movere meant 'to move, set in motion'. It is the source of move, motion, motive and mobile, and its deeper origin is not established.","cn":"movere 意为「移动、使动」。它是 move、motion、motive、mobile 的来源，其更深来源未得到证明。"},{"era":"LATIN EMOVERE","en":"Ex- 'out' plus movere gave emovere 'to move out, remove, stir up'. The prefix turns a plain movement into a displacement.","cn":"表「向外」的前缀加 movere 构成 emovere「推出、移走、搅起」。前缀把单纯的移动变成了位移。"},{"era":"FRENCH EMOTION","en":"French émotion carried the word into English in the seventeenth century, where it first meant an agitation of the body or of a crowd.","cn":"法语 émotion 在 17 世纪把这个词带进英语，最初指身体或人群的骚动。"},{"era":"SHIFT TO FEELING","en":"By the eighteenth century the word had moved inward: the agitation was now mental, and emotion became the ordinary term for strong feeling.","cn":"到 18 世纪，这个词转向内部：骚动变成心理上的，emotion 遂成为强烈感受的常用词。"},{"era":"SCIENTIFIC USE","en":"Nineteenth- and twentieth-century psychology made emotions countable classes and measurable responses, which fixed the plural in technical writing.","cn":"19 与 20 世纪心理学把情绪变成可计数的类别与可测量的反应，复数形式因此在专业文字中固定下来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of movere remains a reconstruction, and the exact first English use for feeling is not pinned down.","cn":"来源不确定：movere 在拉丁语之前的来源仍属重构形式，英语中最先用于「感受」义的确切年代也未确定。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin verb of moving, which are easy to mix; group two holds the near synonyms that psychology keeps apart.","cn":"第一组是同出一个拉丁「移动」动词、极易混淆的词；第二组是心理学刻意区分的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"motion","ipa":"/ˈməʊʃn/","tag":"same root, physical","definition":"The plain noun of movement, from the same Latin verb without the outward prefix; it names change of place, not feeling.","definitionCN":"纯粹的「运动」名词，同出那个拉丁动词但不带向外前缀；指位置改变，而非感受。"},{"word":"motive","ipa":"/ˈməʊtɪv/","tag":"same root, reason to act","definition":"What moves a person to act; it is a cause of behaviour rather than a feeling, so the two are often confused in writing about crime.","definitionCN":"促使人行动的理由；是行为的原因而非感受，因此在罪案写作中常被混淆。"},{"word":"emotive","ipa":"/ɪˈməʊtɪv/","tag":"causing, not having","definition":"Describes words or images that raise feeling in others; emotion is the feeling itself, emotive is its power to spread.","definitionCN":"形容词句或画面能引起他人情绪；emotion 是感受本身，emotive 是它扩散的力量。"},{"word":"motivation","ipa":"/ˌməʊtɪˈveɪʃn/","tag":"same root, drive","definition":"The force that keeps behaviour going; it shares the Latin verb but belongs to the vocabulary of purpose, not of affect.","definitionCN":"维持行为的力量；与情绪共享那个拉丁动词，却属于「目的」而非「情感」的词汇。"}]},{"heading":"NEAR MEANING","entries":[{"word":"feeling","ipa":"/ˈfiːlɪŋ/","tag":"wider and plainer","definition":"The everyday word for any felt state, including mild ones and bodily sensations; emotion usually implies something stronger.","definitionCN":"指任何被感觉到的状态，包括轻微感受与身体感觉；emotion 通常暗示更强一些。"},{"word":"affect","ipa":"/əˈfekt/","tag":"technical umbrella","definition":"The research term for feeling as a measurable dimension, positive or negative; it covers moods too, so it is broader.","definitionCN":"研究中把感受当作可测量维度的术语，分正负；它连心境也一并涵盖，因此更宽。"},{"word":"sentiment","ipa":"/ˈsentɪmənt/","tag":"judgement mixed in","definition":"A feeling that already carries an opinion, such as public sentiment about a policy; it is cooler and more social than emotion.","definitionCN":"已带有看法的感受，如公众对某项政策的情绪；比 emotion 更冷静，也更社会性。"},{"word":"passion","ipa":"/ˈpæʃn/","tag":"extreme, long-lasting","definition":"Feeling at a high temperature, often lasting and attached to an object; emotion can be brief, passion rarely is.","definitionCN":"高温状态的感受，往往持久并附着于某个对象；情绪可以短暂，激情很少短暂。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin movere 'to move' is the root; the outward prefix makes the feeling something pushed up and out.","cn":"词根意为「移动」；向外的前缀让感受成为被推上来、推出去的东西。"},{"en":"The family runs emotion, emotional, emotionally, emotive, emotionless, emotionalism.","cn":"同族词包括 emotion、emotional、emotionally、emotive、emotionless、emotionalism。"},{"en":"Fixed phrases mark the uses: show emotion, control one's emotions, mixed emotions, with emotion.","cn":"固定搭配标出用法：流露情绪、控制情绪、复杂情绪、动情地。"},{"en":"Psychology counts basic emotions and speaks of emotion regulation, which pins down the countable sense.","cn":"心理学数出基本情绪并谈情绪调节，这锁定了可数义。"},{"en":"The word shares its root with move, motion, motive and motivation, all built on the same Latin verb.","cn":"这个词与 move、motion、motive、motivation 共享词根，都建在同一个拉丁动词上。"}],"abstract":[{"en":"Picture a hand pressing the water from underneath, so the surface moves without being struck.","cn":"想象一只手从水底推水，水面动了，却没有被击打。"},{"en":"Picture a room whose temperature rises without anyone touching the thermostat.","cn":"想象一间屋子的温度升高，却没人碰过恒温器。"},{"en":"Picture a letter that shakes in the hand holding it.","cn":"想象一封信在拿着它的那只手里发抖。"}]},"examples":[{"en":"He spoke about his brother without any visible emotion.","cn":"他谈起弟弟时看不出任何情绪。"},{"en":"The film plays on emotion rather than on argument.","cn":"这部片子靠情绪打动人，而不是靠论证。"},{"en":"Fear and anger are often listed among the basic emotions.","cn":"恐惧与愤怒常被列入基本情绪。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"e（向外）+ motion（动）——心里被推得动了起来 → 情绪、情感","word":"emotion"},"root":"拉丁 emovere「推出、搅动」= 表「向外」的前缀 + movere「移动」；经法语进入英语。movere 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: water is stirred, and the stirring is then read as a capacity, as a visible sign, as a countable class, as warmth in expression, as a research object, as sympathy and finally as a bodily event.","cn":"八个义项沿一个动作展开：水被搅动，这次搅动依次被读作一种能力、一个可见迹象、一个可计数的类别、表达里的温度、一个研究对象、对他人的同情，最后是一件身体事件。"},"semanticMap":{"core":{"en":"CORE IMAGE: still water stirred from beneath, so the whole surface moves and the ripples reach the shore.","cn":"核心意象：静水从底下被搅动，整片水面动起来，波纹一直传到岸边。"},"chain":["STIRRED INSIDE","A WHOLE SIDE OF US","SHOWING ON THE SURFACE","COUNTED KINDS","WARMTH IN DELIVERY","NAMED FOR STUDY"],"branches":[{"senses":"01 · 08","en":"THE STIRRING AND ITS BODY: one sense is the feeling as experienced, the other the racing heart that comes with it.","cn":"搅动与它的身体：一个义项是被体验到的感受，另一个是随之而来的心跳加速。"},{"senses":"02","en":"THE WHOLE CAPACITY: feeling treated as one half of human nature rather than a single episode.","cn":"整体能力：把感受当作人性的一半，而不是某一次发作。"},{"senses":"03 · 05","en":"WHAT OTHERS CAN SEE AND HEAR: the shaking voice and the warmth of a speech are the same stirring reaching the surface.","cn":"旁人看得见听得见的部分：发颤的声音与话语里的温度，是同一次搅动抵达表面。"},{"senses":"04 · 06","en":"FROM COUNTING TO MEASURING: first feelings are sorted into kinds, then those kinds become instruments and data.","cn":"从计数到测量：先把感受分成种类，再把这些种类变成仪器与数据。"},{"senses":"07","en":"STIRRED BY ANOTHER: the movement starts outside the feeler and arrives as sympathy.","cn":"被他人搅动：运动起于感受者之外，以同情的形式抵达。"}]},"affixes":{"intro":{"en":"The word is a Latin verb with a prefix of direction, carried through French, so its family can be read from the Latin pieces outward.","cn":"这个词是一个带方向前缀的拉丁动词，经法语传来，因此其词族可以从拉丁成分往外读。"},"latinIntro":{"en":"Latin movere 'to move' gives motion, motive, move and mobile; the outward prefix gives emotion, emigrate and eject their shared sense of leaving.","cn":"拉丁 movere「移动」衍生 motion、motive、move、mobile；向外的前缀则给 emotion、emigrate、eject 共同的「离开」义。"},"items":[{"word":"movere","structure":"movere (Latin verb, second conjugation)","meaning":"to move, set in motion","meaningCN":"移动；使动","example":"The root supplies motion to a whole family of words.","exampleCN":"这个词根为一整族词提供「动」。"},{"word":"emovere","structure":"ex- 'out' + movere","meaning":"to move out, stir up, dislodge","meaningCN":"推出；搅起；挪走","example":"The prefix turns movement into displacement.","exampleCN":"前缀把「移动」变成「位移」。"},{"word":"emotion","structure":"emovere, through French émotion","meaning":"a stirred feeling","meaningCN":"被搅起的感受；情绪","example":"The scene stirred a quiet emotion.","exampleCN":"这一幕激起一种安静的情绪。"},{"word":"emotional","structure":"emotion + -al (relating to)","meaning":"of or filled with feeling","meaningCN":"与情绪有关的；易动感情的","example":"It was an emotional farewell.","exampleCN":"那是一场动情的告别。"},{"word":"emotionally","structure":"emotional + -ly (adverb)","meaning":"in feeling terms","meaningCN":"在情感方面","example":"She was exhausted emotionally.","exampleCN":"她在情感上筋疲力尽。"},{"word":"emotive","structure":"emotion + -ive (tending to cause)","meaning":"likely to raise feeling","meaningCN":"易引发情绪的","example":"It is an emotive word in the debate.","exampleCN":"在这场争论里，这是个容易挑动情绪的词。"},{"word":"emotionless","structure":"emotion + -less (without)","meaning":"showing no feeling","meaningCN":"不带感情的；无表情的","example":"He gave an emotionless reply.","exampleCN":"他给了一个不带感情的回答。"},{"word":"motion","structure":"movere + -tion (action noun)","meaning":"movement, change of place","meaningCN":"运动；移动","example":"The same root without the prefix gives motion.","exampleCN":"同一个词根去掉前缀就是「运动」。"},{"word":"motive","structure":"movere + -ive (that which moves)","meaning":"a reason for acting","meaningCN":"动机；行动的理由","example":"Money was not his motive.","exampleCN":"钱并不是他的动机。"}],"latinEntries":[{"word":"movere","structure":"movere, moveo, movi, motum (verb, second conjugation)","meaning":"to move, stir, set going","meaningCN":"移动；搅动；使运转"},{"word":"emovere","structure":"ex- + movere (verb, second conjugation)","meaning":"to move out, stir up","meaningCN":"推出；搅起"},{"word":"emotio","structure":"emovere + -tio (action noun)","meaning":"a stirring, an agitation","meaningCN":"搅动；骚动"},{"word":"motus","structure":"movere, past participle used as a noun","meaning":"movement","meaningCN":"运动"}],"derivatives":[{"word":"emotional","pos":"adj.","zh":"情绪的；易动感情的；动人的"},{"word":"emotionally","pos":"adv.","zh":"情感上；感情用事地"},{"word":"emotive","pos":"adj.","zh":"引起情绪的"},{"word":"emotionless","pos":"adj.","zh":"不带感情的"},{"word":"emotionality","pos":"n.","zh":"情绪性；易动感情的程度"}]}},{"word":"emotional","ipa_uk":"/ɪˈməʊʃənl/","ipa_us":"/ɪˈmoʊʃənl/","definition_zh":"情绪的；情感的；易动感情的；情绪化的；动人的；感情上的","definition_en":"relating to feelings, or showing strong feelings, or likely to make people feel strongly","core_image":"一根裸露的导线没有包皮，电流稍一经过就整条发亮，也容易被碰痛","scene":"散场后，母女在剧场门口站了很久，谁也没有先说话，最后只是抱了一下。It was an emotional reunion that neither of them tried to put into words.","sceneCN":"这里 emotional 指「充满情绪、难以用言语处理的」（第 1 个义项：与情绪相关且情绪浓烈）；句意为那是一次动情的重逢，两人都没打算把它说成话。图中可辨识物件：剧场门口的灯、相互抱住的两人。","pos":[{"tag":"adj.","zh":"情绪的；情感的；易动感情的；动人的；感情用事的；受情绪影响的"}],"collocations":[{"phrase":"emotional support","zh":"情感支持"},{"phrase":"emotional response","zh":"情绪反应"},{"phrase":"emotional intelligence","zh":"情商；情绪智力"},{"phrase":"emotional attachment","zh":"情感依恋"},{"phrase":"get emotional","zh":"动感情；情绪激动起来"},{"phrase":"emotional well-being","zh":"情绪健康"}],"forms":[{"label":"比较级（多与 more 连用）","form":"more emotional"},{"label":"最高级（多与 most 连用）","form":"most emotional"},{"label":"副词","form":"emotionally"},{"label":"名词（情绪）","form":"emotion"},{"label":"名词（情绪性）","form":"emotionality"}],"derivatives":[{"word":"emotionally","pos":"adv.","zh":"情感上；感情用事地"},{"word":"emotion","pos":"n.","zh":"情绪；情感"},{"word":"emotionality","pos":"n.","zh":"情绪性；易动感情"},{"word":"emotionless","pos":"adj.","zh":"不带感情的"},{"word":"overemotional","pos":"adj.","zh":"过度情绪化的"}],"senses":[{"no":"01","title":"Full of feeling","titleCN":"充满情绪的","definition":"carrying strong feeling that is hard to set aside","definitionCN":"带着强烈、难以搁置的感受","example":"It was an emotional reunion that neither of them put into words.","exampleCN":"那是一次动情的重逢，两人都没把它说成话。","why":"the suffix simply turns the noun of feeling into an adjective, so whatever it describes is loaded with emotion.","whyCN":"后缀只是把表示感受的名词变成形容词，因此它修饰的东西都装满了情绪。"},{"no":"02","title":"Belonging to feeling, not reason","titleCN":"属于情感而非理智","definition":"relating to the feeling side of life as opposed to the calculating side","definitionCN":"涉及生活中感受的那一面，与算计的那一面相对","example":"He needed emotional support more than technical advice.","exampleCN":"他更需要情感上的支持，而不是技术建议。","why":"this sense draws a line: the help given is not practical but affects how a person feels.","whyCN":"这个义项划出一条界线：所给的帮助不是实务性的，而是作用于人的感受。"},{"no":"03","title":"Quick to feel and show it","titleCN":"容易动感情、也容易表现出来","definition":"having feelings close to the surface, so that they appear easily","definitionCN":"感受贴近表面，因此很容易显露出来","example":"She gets emotional at every farewell party.","exampleCN":"每次告别会她都容易动情。","why":"the adjective can describe a person's temperament, not just a moment, which is why it appears with get.","whyCN":"这个形容词可以描述一个人的性情，而不只是一个时刻，所以常与「变得」连用。"},{"no":"04","title":"Acting from feeling","titleCN":"凭感受行事","definition":"making decisions under the pull of feeling rather than by weighing evidence","definitionCN":"在感受的牵引下作决定，而不是权衡证据","example":"The decision was emotional rather than financial.","exampleCN":"这个决定出于感情，而非财务考虑。","why":"here the word works as a mild criticism: feeling has taken over the chair where judgement should sit.","whyCN":"这里这个词带轻微批评：感受坐上了本该由判断坐的那把椅子。"},{"no":"05","title":"Likely to move an audience","titleCN":"容易打动观众的","definition":"built to raise feeling in others, as a scene, speech or ceremony","definitionCN":"为在他人心里激起感受而设计，如场景、演说或仪式","example":"The final speech was the most emotional part of the evening.","exampleCN":"最后那段讲话是整晚最动人的部分。","why":"the direction flips: the object is not feeling but causing feeling, and English lets the same adjective do both jobs.","whyCN":"方向反过来了：对象不是有感受，而是引发感受，英语让同一个形容词兼任两职。"},{"no":"06","title":"Personal and easily hurtful","titleCN":"涉及个人感受、容易伤人","definition":"touching private feelings, so that disagreement becomes personal","definitionCN":"触及私人感受，因此分歧容易变成人身攻击","example":"Religion remains an emotional subject in the region.","exampleCN":"在这个地区，宗教仍是容易牵动感情的话题。","why":"some topics sit on nerves rather than on facts, and the adjective marks that exposure.","whyCN":"有些话题压在神经上而不是压在事实上，这个形容词标记的正是这种暴露。"},{"no":"07","title":"Health of the feeling life","titleCN":"感受生活的健康状况","definition":"describing the condition of a person's feeling life, as in wellbeing or development","definitionCN":"描述一个人感受生活的状况，如健康或发展","example":"Schools now track emotional development alongside grades.","exampleCN":"学校如今把情绪发展同成绩一起追踪。","why":"psychology gave the word a neutral, clinical sense, where it names a dimension to be supported rather than a weakness.","whyCN":"心理学给了它中性、临床的义项，那里它指一个需要被支持的维度，而不是弱点。"},{"no":"08","title":"Charged with sentiment","titleCN":"带着浓重情感的","definition":"said of objects, places or memories that carry personal feeling","definitionCN":"用于承载私人感情的东西、地点或记忆","example":"The old house has emotional value far beyond its price.","exampleCN":"那栋老房子的情感价值远超它的价格。","why":"feelings can attach to things, and the adjective records that attachment as a property of the thing.","whyCN":"感情会附着在物件上，这个形容词便把这种附着记成物件的一种属性。"}],"etymology":{"intro":{"en":"Emotional is formed inside English from emotion plus the adjective suffix -al, which goes back to Latin -alis. The noun itself came through French from a Latin verb meaning 'to move out, stir up'. Dates are approximate.","cn":"emotional 是在英语内部由 emotion 加形容词后缀构成的，那个后缀上溯拉丁 -alis。名词本身则经法语来自一个意为「推出、搅动」的拉丁动词。年代均为约数。"},"items":[{"era":"LATIN MOVERE","en":"Movere 'to move' supplies the root; its outward-prefixed form emovere means 'to stir up'. The deeper origin of movere is not established.","cn":"movere「移动」提供词根；加上向外前缀的形式意为「搅起」。movere 的更深来源未得到证明。"},{"era":"FRENCH EMOTION","en":"The noun entered English in the seventeenth century as a word for agitation, then shifted to strong feeling by the eighteenth.","cn":"这个名词在 17 世纪进入英语，指骚动，到 18 世纪转为指强烈感受。"},{"era":"LATIN ADJECTIVE SUFFIX","en":"The suffix -alis formed adjectives of belonging in Latin and survives in English as -al, as in national and personal.","cn":"这个拉丁后缀构成表归属的形容词，在英语中留存为 -al，如国家的、个人的。"},{"era":"NINETEENTH-CENTURY WORD","en":"Emotional is recorded from the nineteenth century, when writers needed an adjective for feeling as a domain rather than for a single episode.","cn":"emotional 见于 19 世纪，当时写作者需要一个形容词，指作为一整个领域的感受，而非某一次发作。"},{"era":"PSYCHOLOGY","en":"Twentieth-century psychology and education made it a neutral technical word, so that emotional development and emotional health became ordinary phrases.","cn":"20 世纪心理学与教育学把它变成中性的专业词，于是「情绪发展」「情绪健康」成为常见说法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the precise first date of the adjective is not fixed, and the pre-Latin history of the root remains a reconstruction.","cn":"来源不确定：这个形容词的确切首见年代未定，词根在拉丁语之前的历史仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds adjectives that look or sound close and are often swapped by mistake; group two holds near synonyms with a narrower focus.","cn":"第一组是字形或读音接近、常被误换的形容词；第二组是范围更窄的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"emotive","ipa":"/ɪˈməʊtɪv/","tag":"causes feeling","definition":"Said of words or images that stir people up; it points outward at the effect, while emotional often points at the state.","definitionCN":"形容词句或画面能激起情绪；它指向对外的效果，而 emotional 常指向状态本身。"},{"word":"emotionless","ipa":"/ɪˈməʊʃənləs/","tag":"shows nothing","definition":"Its plain negative: a face or voice that reveals no feeling at all.","definitionCN":"它的直接否定：脸上或声音里看不出任何感情。"},{"word":"emotionalism","ipa":"/ɪˈməʊʃənəlɪzəm/","tag":"the habit, named","definition":"The noun for a style or habit of relying on feeling; it criticises the practice, not a single moment.","definitionCN":"指依赖感受的风格或习惯的名词；批评的是做法，不是某一个时刻。"},{"word":"emoticon","ipa":"/ɪˈməʊtɪkɒn/","tag":"looks alike, unrelated build","definition":"A blend of emotion and icon, coined for typed faces; it shares the first element but nothing else.","definitionCN":"由 emotion 与 icon 缩合而成，指打字用的表情符号；只共享前一个成分，别无关联。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sentimental","ipa":"/ˌsentɪˈmentl/","tag":"sweetened feeling","definition":"Feeling that is softer and often excessive, attached to keepsakes and old songs; emotional can be raw rather than sweet.","definitionCN":"较柔、常显过度的感情，多附着于纪念物与老歌；emotional 可以是生涩的，而不一定甜。"},{"word":"passionate","ipa":"/ˈpæʃənət/","tag":"hot and committed","definition":"Intense feeling joined to commitment or desire; it usually implies energy directed at something.","definitionCN":"强烈感受加上投入或欲望；通常暗示有方向地使力。"},{"word":"touchy-feely","ipa":"/ˌtʌtʃi ˈfiːli/","tag":"informal, dismissive","definition":"A mocking label for open expression of feeling; it is a judgement, not a description.","definitionCN":"对公开表达感情的嘲讽说法；是评判，而非描述。"},{"word":"affective","ipa":"/əˈfektɪv/","tag":"technical","definition":"The research adjective for feeling as a measurable dimension; it never means 'easily upset'.","definitionCN":"研究中把感受当作可测量维度的形容词；从不表示「容易难过」。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"It is simply the noun of feeling with the ordinary adjective suffix attached.","cn":"它就是「情绪」这个名词加上普通的形容词后缀。"},{"en":"The family runs emotion, emotional, emotionally, emotionality, emotionless, overemotional.","cn":"同族词包括 emotion、emotional、emotionally、emotionality、emotionless、overemotional。"},{"en":"Fixed phrases mark the uses: emotional support, emotional response, emotional intelligence.","cn":"固定搭配标出用法：情感支持、情绪反应、情商。"},{"en":"The phrase get emotional marks the temperament sense, where the feeling rises fast.","cn":"「变得动情」这一说法标记的是性情义，感受升得快。"},{"en":"Psychologists pair it with development and wellbeing, which shows the neutral technical side.","cn":"心理学家把它与「发展」「健康」搭配，显出中性的专业一面。"}],"abstract":[{"en":"Picture a bare wire that lights up along its whole length at the smallest touch.","cn":"想象一根裸露的导线，轻轻一碰就整条亮起来。"},{"en":"Picture a room where the thermostat is set by mood rather than by weather.","cn":"想象一间屋子的恒温器由心情而不是由天气设定。"},{"en":"Picture a door that opens at a knock but also at a gust of wind.","cn":"想象一扇门，敲门会开，来一阵风也会开。"}]},"examples":[{"en":"The team offered practical help and emotional support.","cn":"团队提供了实际帮助与情感支持。"},{"en":"He became emotional when he described the accident.","cn":"他描述那场事故时动情了。"},{"en":"The letter is an emotional appeal rather than a legal argument.","cn":"这封信是情感呼吁，而不是法律论证。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"emotion（情绪）+ al（……的）——与情绪有关的 → 情绪的、易动感情的","word":"emotional"},"root":"英语在 emotion 上加来自拉丁的表属性后缀 -alis 构成；emotion 出自拉丁 emovere「推出、搅动」，即表「向外」的前缀加 movere「移动」。","sensesIntro":{"en":"Eight senses follow one movement: feeling saturates something, and that saturation is then read as a domain, as a temperament, as a way of deciding, as a power to move others, as exposure, as health and finally as value stored in an object.","cn":"八个义项沿一个动作展开：感受浸透某物，这种浸透依次被读作一个领域、一种性情、一种决策方式、一种打动人心的力量、一种暴露、一种健康，最后是储存在物件里的价值。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bare wire that lights along its whole length at the smallest touch and is also easy to hurt.","cn":"核心意象：一根裸露的导线，轻轻一碰就整条发亮，也容易被碰痛。"},"chain":["LOADED WITH FEELING","THE FEELING SIDE","CLOSE TO THE SURFACE","FEELING DECIDES","MOVING OTHERS","FEELING LIFE"],"branches":[{"senses":"01 · 08","en":"SATURATION AND ITS STORAGE: one sense is the moment of being filled, the other is the value that stays in a house or a letter.","cn":"浸透与储存：一个义项是被充满的时刻，另一个是留在房子或信件里的价值。"},{"senses":"02 · 07","en":"THE DOMAIN AND ITS HEALTH: feeling treated as a whole province, then as something that can be looked after.","cn":"领域与其健康：把感受当成一整片地方，再当成可以被照料的东西。"},{"senses":"03","en":"THE SHORT FUSE: a temperament in which feeling reaches the surface almost at once.","cn":"短引线：一种感受几乎立刻抵达表面的性情。"},{"senses":"04 · 06","en":"FEELING IN THE CHAIR: it either makes the decision or makes a topic too sore to decide calmly.","cn":"感受坐上主位：它要么替人作决定，要么让某个话题痛到无法冷静决定。"},{"senses":"05","en":"FEELING AS AN EFFECT: the same adjective turns outward and describes what moves an audience.","cn":"感受作为效果：同一个形容词转向外，描述能打动观众的东西。"}]},"affixes":{"intro":{"en":"A Latin-derived noun of feeling plus a Latin adjective suffix; the pieces are so regular that the whole family reads at sight.","cn":"一个来自拉丁的「感受」名词加一个拉丁形容词后缀；成分很规则，整个词族一眼就能读。"},"latinIntro":{"en":"The noun goes back to a Latin verb of moving with an outward prefix; the suffix -alis marks belonging and survives as -al in English.","cn":"名词上溯到一个带向外前缀的拉丁「移动」动词；后缀 -alis 标记归属，在英语中留存为 -al。"},"items":[{"word":"emotion","structure":"emovere, through French émotion","meaning":"stirred feeling","meaningCN":"被搅起的感受","example":"The scene stirred a quiet emotion.","exampleCN":"这一幕激起一种安静的情绪。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to; of the nature of","meaningCN":"与……有关的；具有……性质的","example":"The suffix turns nouns into adjectives of belonging.","exampleCN":"这个后缀把名词变成表归属的形容词。"},{"word":"emotional","structure":"emotion + -al","meaning":"of feeling; showing feeling","meaningCN":"情绪的；流露感情的","example":"It was an emotional reunion.","exampleCN":"那是一次动情的重逢。"},{"word":"emotionally","structure":"emotional + -ly (adverb)","meaning":"in feeling terms","meaningCN":"在情感方面","example":"She was emotionally drained.","exampleCN":"她在情感上被掏空了。"},{"word":"emotionality","structure":"emotional + -ity (quality noun)","meaning":"the degree of being emotional","meaningCN":"情绪性；易动感情的程度","example":"The scale measures emotionality in children.","exampleCN":"这个量表测量儿童的情绪性。"},{"word":"emotionless","structure":"emotion + -less (without)","meaning":"showing no feeling","meaningCN":"不带感情的","example":"His face stayed emotionless.","exampleCN":"他的脸始终没有表情。"},{"word":"overemotional","structure":"over- 'too much' + emotional","meaning":"showing more feeling than a situation calls for","meaningCN":"过度情绪化的","example":"The reply was overemotional.","exampleCN":"那封回信过于情绪化。"},{"word":"emotive","structure":"emotion + -ive (tending to)","meaning":"likely to stir feeling","meaningCN":"容易引发情绪的","example":"It is an emotive term in the debate.","exampleCN":"在这场争论中它是个容易挑动情绪的词。"}],"latinEntries":[{"word":"movere","structure":"movere, moveo, movi, motum (verb)","meaning":"to move, stir","meaningCN":"移动；搅动"},{"word":"emotio","structure":"emovere + -tio (noun)","meaning":"a stirring, agitation","meaningCN":"搅动；骚动"}],"derivatives":[{"word":"emotionally","pos":"adv.","zh":"情感上；感情用事地"},{"word":"emotionality","pos":"n.","zh":"情绪性"},{"word":"emotionless","pos":"adj.","zh":"不带感情的"},{"word":"overemotional","pos":"adj.","zh":"过度情绪化的"}]}},{"word":"emotionally","ipa_uk":"/ɪˈməʊʃənəli/","ipa_us":"/ɪˈmoʊʃənəli/","definition_zh":"在情感方面；情绪上；感情用事地；在情绪健康方面；带着感情地","definition_en":"with respect to feelings, or in a way driven by feelings","core_image":"同一条路上有两条车道，一条写着「道理」，一条写着「感受」，方向盘总往第二条偏","scene":"两个人坐在桌前谈分家，账目摊开很久没人看，最后先开口的是那句「这些年我一直在忍」。The conversation turned emotionally long before anyone reached the numbers.","sceneCN":"这里 emotionally 指「沿着感受这条线，而非沿着理智或数字」（第 1 个义项：在情感层面）；句意是这场谈话早在任何人碰到数字之前就转向了情感。图中可辨识物件：摊开的账本、无人动过的笔、两只抵住的杯子。","pos":[{"tag":"adv.","zh":"在情感方面；情绪上；感情用事地"}],"collocations":[{"phrase":"emotionally attached","zh":"在情感上依恋的"},{"phrase":"emotionally charged","zh":"情绪浓烈的"},{"phrase":"emotionally exhausted","zh":"情感上筋疲力尽的"},{"phrase":"emotionally unavailable","zh":"在情感上难以靠近的"},{"phrase":"react emotionally","zh":"情绪化地反应"},{"phrase":"emotionally intelligent","zh":"情绪智力高的"}],"forms":[{"label":"原级（副词）","form":"emotionally"},{"label":"比较级（多与 more 连用）","form":"more emotionally"},{"label":"最高级（多与 most 连用）","form":"most emotionally"},{"label":"形容词形式","form":"emotional"},{"label":"名词形式","form":"emotion"}],"derivatives":[{"word":"emotional","pos":"adj.","zh":"情绪的；易动感情的"},{"word":"emotion","pos":"n.","zh":"情绪；情感"},{"word":"unemotionally","pos":"adv.","zh":"不带感情地；冷静地"},{"word":"overemotionally","pos":"adv.","zh":"过度情绪化地"}],"senses":[{"no":"01","title":"On the feeling side","titleCN":"在情感这一面","definition":"in the part of life that concerns feelings rather than practical matters","definitionCN":"在生活里涉及感受、而非实务的那一面","example":"The conversation turned emotionally long before anyone reached the numbers.","exampleCN":"这场谈话早在任何人碰到数字之前就转向了情感。","why":"the adverb simply marks the dimension in which something happens, so it can be added to almost any verb of caring or costing.","whyCN":"这个副词只标出事情发生在哪个维度，因此几乎可以加在任何表示「在意」或「付出」的动词上。"},{"no":"02","title":"By way of feeling","titleCN":"经由感受这一途径","definition":"through an experience that is felt rather than reasoned","definitionCN":"通过被感受到而非被推理的经验","example":"Children learn the story emotionally before they learn its dates.","exampleCN":"孩子们先在情感上理解这个故事，之后才知道它的年代。","why":"the route matters: what arrives through feeling is remembered differently from what arrives as information.","whyCN":"途径很重要：经由感受抵达的东西，与作为信息抵达的东西，记忆方式不同。"},{"no":"03","title":"Driven by feeling","titleCN":"被感受推着走","definition":"acting under the pressure of feeling instead of weighing things","definitionCN":"在感受的压力下行动，而不是权衡轻重","example":"He reacted emotionally and regretted it by morning.","exampleCN":"他情绪化地反应，到早上就后悔了。","why":"here the adverb criticises the manner of acting, implying that judgement was bypassed.","whyCN":"这里这个副词批评的是行事方式，暗示判断被绕过了。"},{"no":"04","title":"In terms of feeling health","titleCN":"在情绪健康方面","definition":"with regard to the condition of a person's feeling life","definitionCN":"就一个人感受生活的状况而言","example":"The job left her emotionally exhausted but financially secure.","exampleCN":"这份工作让她情感上筋疲力尽，经济上却安稳。","why":"psychology turned the adverb into a neutral measure, so it can sit beside exhausted, healthy or neglected.","whyCN":"心理学把这个副词变成中性的度量，因此它可以与「疲惫」「健康」「被忽视」并列。"},{"no":"05","title":"With feeling in the voice","titleCN":"带着感情地","definition":"delivering something with audible or visible feeling","definitionCN":"带着听得见、看得见的感情去表达","example":"She sang the last line emotionally, almost in a whisper.","exampleCN":"她把最后一句唱得很有感情，几乎像在低语。","why":"the manner of delivery is what is being judged here, not the inner state.","whyCN":"这里被评判的是表达方式，而不是内心状态。"},{"no":"06","title":"In an exposed, vulnerable way","titleCN":"以脆弱、易受伤的方式","definition":"in a state where private feeling is visible and easily hurt","definitionCN":"处于私人感受暴露、容易被伤到的状态","example":"They were both emotionally naked in that room.","exampleCN":"在那间屋子里，两人都情感上毫无遮拦。","why":"the wire is bare: exposure is the point, and the adverb marks how unprotected the moment is.","whyCN":"导线是裸的：暴露就是重点，这个副词标记这一刻有多无遮拦。"},{"no":"07","title":"In a way that moves others","titleCN":"以打动别人的方式","definition":"so as to raise feeling in those who watch or listen","definitionCN":"以致让观看或聆听的人产生感受","example":"The documentary ends emotionally, on a child's unanswered question.","exampleCN":"这部纪录片以情绪收尾，停在一个孩子没有得到回答的问题上。","why":"the adverb can point at the effect on an audience, the same flip seen in the adjective.","whyCN":"这个副词可以指向对观众的效果，正是形容词里出现的那种方向反转。"},{"no":"08","title":"Attached rather than neutral","titleCN":"带着依恋而非中立","definition":"in a relation where personal attachment has formed","definitionCN":"在已经形成私人依恋的关系里","example":"He is emotionally attached to a town he left twenty years ago.","exampleCN":"他在情感上依恋着一座二十年前离开的小镇。","why":"attachment is feeling that has settled onto an object, and the adverb names the tie rather than the object.","whyCN":"依恋是沉淀到某个对象上的感受，副词命名的是那条绳，而不是那个对象。"}],"etymology":{"intro":{"en":"Emotionally is emotional plus the adverb suffix -ly. The whole chain runs back through French to a Latin verb meaning 'to move out, stir up'. Dates are approximate.","cn":"emotionally 是 emotional 加副词后缀构成的。整条链经法语上溯到一个意为「推出、搅动」的拉丁动词。年代均为约数。"},"items":[{"era":"LATIN MOVERE","en":"The root verb means 'to move'; with an outward prefix it means 'to stir up'. Its deeper origin is not established.","cn":"词根动词意为「移动」；加上向外前缀即「搅起」。其更深来源未得到证明。"},{"era":"FRENCH AND ENGLISH NOUN","en":"The noun reached English through French in the seventeenth century and settled on strong feeling during the eighteenth.","cn":"名词在 17 世纪经法语进入英语，到 18 世纪固定指强烈感受。"},{"era":"ADJECTIVE SUFFIX","en":"A Latin suffix of belonging produced the adjective in the nineteenth century, when feeling became a named domain.","cn":"一个表归属的拉丁后缀在 19 世纪造出形容词，那时感受开始成为一个被命名的领域。"},{"era":"ADVERB SUFFIX","en":"The native adverb suffix -ly marks manner or respect, so the adverb can mean either 'in what way' or 'in what respect'.","cn":"本族副词后缀标记方式或方面，因此这个副词既可表示「以何种方式」，也可表示「在哪一方面」。"},{"era":"CLINICAL USE","en":"Twentieth-century psychology fixed phrases such as emotionally unavailable and emotionally exhausted, where the adverb marks a dimension of health.","cn":"20 世纪心理学固定了「情感上难以靠近」「情感上筋疲力尽」一类说法，那里的副词标记健康的维度。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: no exact first citation for the adverb is agreed, and the pre-Latin history of the root remains a reconstruction.","cn":"来源不确定：这个副词最早的确切书证没有公认结论，词根在拉丁语之前的历史仍属重构形式。"}]},"similar":{"note":{"en":"Group one holds adverbs that look close and are frequently swapped; group two holds near equivalents with a different angle.","cn":"第一组是字形接近、常被互换的副词；第二组是角度不同的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"emotional","ipa":"/ɪˈməʊʃənl/","tag":"adjective, not adverb","definition":"The adjective describes the person, thing or state; the adverb describes how or in what respect something is done.","definitionCN":"形容词描述人或事物或状态；副词描述事情以何种方式、在哪个方面发生。"},{"word":"emotively","ipa":"/ɪˈməʊtɪvli/","tag":"in a stirring way","definition":"Built on the adjective for 'causing feeling', so it describes language that is loaded to provoke rather than a person who feels.","definitionCN":"由「引发情绪」那个形容词构成，因此描述的是被装填用来挑动的语言，而不是有感受的人。"},{"word":"unemotionally","ipa":"/ʌnɪˈməʊʃənəli/","tag":"plain negative","definition":"The direct opposite: done without feeling showing, often read as cold or professional.","definitionCN":"直接的反义：做时不露感情，常被读作冷淡或专业。"},{"word":"emotionlessly","ipa":"/ɪˈməʊʃənləsli/","tag":"absence, stronger","definition":"Stronger than the plain negative because it stresses the total absence of feeling, as in a flat recorded voice.","definitionCN":"比单纯否定更强，因为它强调感受完全缺席，如毫无起伏的录音嗓音。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sentimentally","ipa":"/ˌsentɪˈmentəli/","tag":"softer feeling","definition":"In a tender, often nostalgic way; the feeling is sweetened, whereas this word can be raw.","definitionCN":"以温柔、常带怀旧的方式；感受是加过糖的，而本词可以是生的。"},{"word":"passionately","ipa":"/ˈpæʃənətli/","tag":"with heat and commitment","definition":"With intense, directed feeling; it implies energy aimed at something, not merely being moved.","definitionCN":"带着强烈而有方向的感情；暗示朝某物使力，而不只是被触动。"},{"word":"personally","ipa":"/pəˈsəʊnəli/","tag":"about the self","definition":"Marks that something touches the self or is done by the self, which overlaps with this word only when feelings are involved.","definitionCN":"标记某事触及本人或由本人来做，只有涉及感受时才与本词重叠。"},{"word":"intuitively","ipa":"/ɪnˈtjuːɪtɪvli/","tag":"without reasoning","definition":"By direct apprehension rather than analysis; it explains the route but says nothing about feeling.","definitionCN":"凭直接领会而非分析；它解释途径，却不涉及感受。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Adjective plus the ordinary adverb suffix: feeling turned into a manner or a dimension.","cn":"形容词加普通副词后缀：把感受变成一种方式或一个维度。"},{"en":"The family runs emotion, emotional, emotionally, unemotionally, emotively.","cn":"同族词包括 emotion、emotional、emotionally、unemotionally、emotively。"},{"en":"Fixed phrases mark the uses: emotionally attached, emotionally exhausted, emotionally unavailable.","cn":"固定搭配标出用法：情感上依恋、情感上筋疲力尽、情感上难以靠近。"},{"en":"The word often answers the question 'in what respect', not 'in what manner', which is why it pairs with adjectives.","cn":"这个词常回答「在哪方面」，而不是「以何方式」，因此常与形容词搭配。"},{"en":"Psychology made it a neutral measure beside healthy, exhausted and neglected.","cn":"心理学把它变成中性的度量，与「健康」「疲惫」「被忽视」并列。"}],"abstract":[{"en":"Picture two lanes on one road, and the wheel keeps drifting to the one marked feeling.","cn":"想象同一条路上的两条车道，方向盘总往标着「感受」的那条偏。"},{"en":"Picture a wire with no insulation, glowing wherever it is touched.","cn":"想象一根没有包皮的导线，碰到哪里哪里就亮。"},{"en":"Picture a scale that weighs a house by the memories inside it.","cn":"想象一台秤，用屋里的记忆来称这栋房子。"}]},"examples":[{"en":"He is still emotionally tied to his first school.","cn":"他在情感上仍与第一所学校相连。"},{"en":"The debate became emotionally charged within minutes.","cn":"辩论在几分钟内就变得情绪浓烈。"},{"en":"She answered the question emotionally, without checking the figures.","cn":"她情绪化地回答了这个问题，没有核对数字。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"emotional（情绪的）+ ly（地）——以情绪的方式 → 在情感上、感情用事地","word":"emotionally"},"root":"英语在 emotional 上加副词后缀构成；emotional 又由 emotion 加表属性的后缀构成，emotion 出自拉丁 emovere「推出、搅动」。","sensesIntro":{"en":"Eight senses follow one movement: feeling becomes the lane a thing travels in, and that lane is then read as a route, as a driver, as a measure of health, as a manner of delivery, as exposure, as an effect on others and finally as a tie.","cn":"八个义项沿一个动作展开：感受变成事情行驶的那条车道，这条车道依次被读作途径、驾驶者、健康度量、表达方式、暴露、对他人的效果，最后是一条绳。"},"semanticMap":{"core":{"en":"CORE IMAGE: two lanes on one road, and the wheel keeps drifting toward the one marked feeling.","cn":"核心意象：同一条路上的两条车道，方向盘总往标着「感受」的那条偏。"},"chain":["THE FEELING LANE","THE FEELING ROUTE","THE FEELING DRIVER","FEELING HEALTH","FEELING IN DELIVERY","BARE AND TIED"],"branches":[{"senses":"01 · 02","en":"THE LANE AND THE ROUTE: first the dimension in which something happens, then the path by which it is learned.","cn":"车道与路线：先是事情发生的维度，再是它被学会的路径。"},{"senses":"03","en":"WHO HOLDS THE WHEEL: feeling takes over the driving, and judgement is said to have been bypassed.","cn":"谁握着方向盘：感受接管驾驶，判断被说成绕过了。"},{"senses":"04","en":"THE MEASURE OF THE LANE: health language turns the adverb into a gauge, as in exhausted or neglected.","cn":"车道的度量：健康类说法把这个副词变成量表，如疲惫或被忽视。"},{"senses":"05 · 07","en":"DELIVERY AND ITS EFFECT: how a line is sung, and how that singing lands on listeners.","cn":"表达与其效果：一句怎么被唱出来，以及这种唱法如何落在听众身上。"},{"senses":"06 · 08","en":"BARE WIRE AND LASTING TIE: either feeling is unprotected in the moment, or it has hardened into attachment.","cn":"裸线与此后的绳：要么感受在此刻毫无遮拦，要么它已经凝成依恋。"}]},"affixes":{"intro":{"en":"Three layers stack here: a Latin verb of moving, a Latin adjective suffix, and a native adverb suffix.","cn":"这里叠了三层：一个拉丁「移动」动词、一个拉丁形容词后缀、一个本族副词后缀。"},"latinIntro":{"en":"The base verb is the same one behind motion and motive; the adjective suffix marks belonging; the adverb suffix marks manner or respect.","cn":"词基动词也是 motion 与 motive 背后的那个；形容词后缀标记归属；副词后缀标记方式或方面。"},"items":[{"word":"emotion","structure":"emovere, through French","meaning":"stirred feeling","meaningCN":"被搅起的感受","example":"The scene stirred a quiet emotion.","exampleCN":"这一幕激起一种安静的情绪。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"It made the noun into an adjective.","exampleCN":"它把名词变成形容词。"},{"word":"emotional","structure":"emotion + -al","meaning":"of or showing feeling","meaningCN":"情绪的；流露感情的","example":"It was an emotional farewell.","exampleCN":"那是一场动情的告别。"},{"word":"-ly","structure":"-ly (native adverb suffix)","meaning":"in a certain manner or respect","meaningCN":"以某种方式；在某方面","example":"The suffix let the adjective describe how something is done.","exampleCN":"这个后缀让形容词去描述事情如何被做。"},{"word":"emotionally","structure":"emotional + -ly","meaning":"in feeling terms","meaningCN":"在情感方面；感情用事地","example":"He reacted emotionally.","exampleCN":"他情绪化地反应。"},{"word":"unemotionally","structure":"un- 'not' + emotionally","meaning":"without feeling showing","meaningCN":"不带感情地","example":"She answered unemotionally.","exampleCN":"她不带感情地回答。"},{"word":"emotionlessly","structure":"emotionless + -ly","meaning":"with no feeling at all","meaningCN":"毫无感情地","example":"The announcement was read emotionlessly.","exampleCN":"公告被毫无感情地念出。"},{"word":"emotively","structure":"emotive + -ly","meaning":"in a way that stirs feeling","meaningCN":"以挑动情绪的方式","example":"The issue was emotively framed.","exampleCN":"这个议题被用挑动情绪的方式框定。"}],"latinEntries":[{"word":"movere","structure":"movere, moveo, movi, motum (verb)","meaning":"to move, stir","meaningCN":"移动；搅动"},{"word":"emotio","structure":"emovere + -tio (noun)","meaning":"a stirring","meaningCN":"搅动；骚动"}],"derivatives":[{"word":"emotional","pos":"adj.","zh":"情绪的；易动感情的"},{"word":"unemotionally","pos":"adv.","zh":"不带感情地"},{"word":"emotionlessly","pos":"adv.","zh":"毫无感情地"},{"word":"emotively","pos":"adv.","zh":"以挑动情绪的方式"}]}},{"word":"mood","ipa_uk":"/muːd/","ipa_us":"/muːd/","definition_zh":"心情；情绪；气氛；语气（语法）；一时的兴致","definition_en":"a temporary state of feeling, or the atmosphere of a place or group, or a grammatical category of the verb","core_image":"天气没有变，屋里的人却觉得整间房子忽明忽暗，像云在屋顶上走","scene":"排练到一半，指挥忽然放下手，说今天先到这里，因为整个乐队已经提不起劲。The conductor stopped the rehearsal because the mood in the hall had gone flat.","sceneCN":"这里 mood 指「一群人当下共同的情绪基调」（第 1 个义项：一时的情绪状态）；句意为指挥中止排练，因为大厅里的情绪已经没了劲。图中可辨识物件：放下的指挥棒、松开的谱架、空着的上半场座位。","pos":[{"tag":"n.","zh":"心情；情绪；气氛；语气（语法）"},{"tag":"n. (plural)","zh":"情绪波动；一时的心情变化"}],"collocations":[{"phrase":"in a good mood","zh":"心情好"},{"phrase":"in the mood for","zh":"有兴致做……"},{"phrase":"mood swings","zh":"情绪波动"},{"phrase":"set the mood","zh":"定下气氛"},{"phrase":"public mood","zh":"公众情绪"},{"phrase":"the mood of the times","zh":"时代氛围"}],"forms":[{"label":"复数","form":"moods"},{"label":"形容词形式","form":"moody"},{"label":"副词形式","form":"moodily"},{"label":"名词（情绪性）","form":"moodiness"},{"label":"复合形式","form":"mood music"}],"derivatives":[{"word":"moody","pos":"adj.","zh":"情绪化的；闷闷不乐的"},{"word":"moodily","pos":"adv.","zh":"闷闷不乐地"},{"word":"moodiness","pos":"n.","zh":"喜怒无常"},{"word":"mood-altering","pos":"adj.","zh":"影响情绪的"},{"word":"mood board","pos":"n.","zh":"（设计用的）情绪板"}],"senses":[{"no":"01","title":"A temporary state of feeling","titleCN":"一时的情绪状态","definition":"the way a person feels at a particular time, seen as passing rather than fixed","definitionCN":"一个人在某段时间里的感受状态，被视为会过去而非固定","example":"The conductor stopped the rehearsal because the mood in the hall had gone flat.","exampleCN":"指挥中止排练，因为大厅里的情绪已经没了劲。","why":"the oldest English sense is simply 'mind, disposition', so the word names the weather inside a person rather than their climate.","whyCN":"最早的英语义就是「心境、性情」，因此这个词命名的是人内部的天气，而不是气候。"},{"no":"02","title":"The atmosphere of a place","titleCN":"一个地方的气氛","definition":"the feeling that a room, a street or a gathering gives off","definitionCN":"一间屋子、一条街或一场聚会所散发出的感受","example":"Candles on the tables changed the mood of the whole restaurant.","exampleCN":"桌上的蜡烛改变了整间餐馆的气氛。","why":"the same word moves from one head to a space, because a space is read as having a temper of its own.","whyCN":"同一个词从一颗脑袋移到一个空间，因为空间被读作有自己的脾气。"},{"no":"03","title":"A spell of bad temper","titleCN":"一阵坏脾气","definition":"a period of sulking or irritability, often named in the plural and with a possessive","definitionCN":"一段闷气或易怒的时期，常以复数并带物主词出现","example":"He has been in one of his moods since the meeting.","exampleCN":"开会之后他一直闹着脾气。","why":"when the passing state is unpleasant, the plural turns it into a recurring event that others learn to expect.","whyCN":"当这种会过去的状态并不愉快时，复数把它变成别人学会预期、一再发生的事。"},{"no":"04","title":"A grammatical category","titleCN":"语法上的语气","definition":"the form of a verb that shows whether it states, commands or supposes","definitionCN":"动词的形式，表明它是在陈述、命令还是假设","example":"English marks the imperative mood by leaving the subject out.","exampleCN":"英语通过省去主语来标记祈使语气。","why":"this sense is a different word altogether, borrowed from Latin modus 'measure, manner', and it means a manner of speaking.","whyCN":"这个义项其实是另一个词，借自拉丁 modus「尺度、方式」，意思是说话的方式。"},{"no":"05","title":"The public's temper","titleCN":"公众的总体情绪","definition":"the general temper of a group, market or electorate at a given time","definitionCN":"某一时刻一个群体、市场或选民的总体情绪","example":"The public mood turned against the plan within a week.","exampleCN":"一周之内公众情绪就转向反对这个方案。","why":"one person's weather scaled up becomes a collective climate that politicians claim to read.","whyCN":"一个人的天气放大之后成为集体的气候，政治家声称自己能读出它。"},{"no":"06","title":"Feeling like doing something","titleCN":"有兴致做某事","definition":"the inclination to do a particular thing at a particular moment","definitionCN":"在某个时刻做某件具体事情的倾向","example":"She was not in the mood for another long explanation.","exampleCN":"她没有兴致再听一段冗长的解释。","why":"the state is now aimed at an object, and 'in the mood for' turns a climate into a door that is either open or shut.","whyCN":"这个状态现在有了对象，「有兴致」把气候变成一扇要么开、要么关的门。"},{"no":"07","title":"Rapid shifts of feeling","titleCN":"情绪的快速起落","definition":"quick changes between emotional states, often treated as a symptom or a trait","definitionCN":"情绪状态之间的快速变化，常被当作症状或特质","example":"Her mood swings made the household walk on glass.","exampleCN":"她的情绪起落让全家人如履薄冰。","why":"the plural measures frequency, turning a state into a pattern that others can chart.","whyCN":"复数衡量的是频率，把一个状态变成旁人能画出来的模式。"},{"no":"08","title":"The key of a work","titleCN":"作品的基调","definition":"the prevailing feeling that a painting, film or piece of music is built to produce","definitionCN":"一幅画、一部电影或一段音乐被设计来产生的总体感受","example":"The grey palette gives the film a mood of waiting.","exampleCN":"灰调子给这部片子一种等待的基调。","why":"artists speak of mood because a work also has weather, and the term lets them tune it deliberately.","whyCN":"艺术家谈基调，是因为作品也有天气，而这个说法让他们能刻意调它。"}],"etymology":{"intro":{"en":"English has two different words written mood. The feeling word is native Old English mod 'mind, courage, temper'. The grammar word was borrowed later from Latin modus 'measure, manner', the same source as mode and model. Dates are approximate.","cn":"英语里有两个写法相同的 mood。表感受的那个是本族古英语 mod「心、勇气、性情」；语法义的那个则是后来从拉丁 modus「尺度、方式」借入的，与 mode、model 同源。年代均为约数。"},"items":[{"era":"OLD ENGLISH MOD","en":"Mod meant 'mind, inner self, courage, anger'. It is Germanic in origin and had no connection with Latin at all.","cn":"mod 意为「心、内在自我、勇气、愤怒」。它源出日耳曼语，与拉丁语毫无关联。"},{"era":"MIDDLE ENGLISH NARROWING","en":"As the older senses faded, the word narrowed to a passing state of feeling, the sense it carries today.","cn":"随着较早的义项淡出，这个词收窄为一种会过去的感受状态，也就是今天的义项。"},{"era":"LATIN MODUS","en":"Modus meant 'measure, standard, manner'. Grammarians used it for the manner in which a verb states or commands, and that use entered English.","cn":"modus 意为「尺度、标准、方式」。语法学家用它指动词陈述或命令的方式，这一用法进入了英语。"},{"era":"TWO WORDS MEET","en":"The spelling fell together in Middle English, so that one shape now carries two unrelated histories, one Germanic and one Latin.","cn":"两个词在中古英语里拼写合流，于是一个字形现在背着两段互不相关的历史，一段日耳曼，一段拉丁。"},{"era":"MODERN EXTENSIONS","en":"From the eighteenth century the feeling word was extended to rooms, crowds, markets and works of art, and mood music followed in the twentieth.","cn":"从 18 世纪起，表感受的那个词被延伸到屋子、人群、市场与艺术品，20 世纪又有了「氛围音乐」。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the earliest written forms of the Germanic word are attested but its deeper pre-Germanic origin is a reconstruction, and no first date is agreed for the grammar borrowing.","cn":"来源不确定：那个日耳曼词的最早书写形式有书证，但它在日耳曼语之前的更深来源属重构形式；语法义借入的确切年代也没有公认结论。"}]},"similar":{"note":{"en":"Group one holds the word that looks the same but has another history; group two holds feeling words that differ in duration and cause.","cn":"第一组是字形相同而历史不同的词；第二组是持续时间与起因不同的感受词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mode","ipa":"/məʊd/","tag":"same Latin source as the grammar sense","definition":"From Latin modus 'measure, manner': a way of doing something. It looks close to mood but shares history only with the grammar sense.","definitionCN":"来自拉丁 modus「尺度、方式」：做事的方式。字形近 mood，但只与语法义共享历史。"},{"word":"moody","ipa":"/ˈmuːdi/","tag":"adjective from the feeling word","definition":"Built on the feeling sense: given to sudden low or irritable states.","definitionCN":"由表感受的义项构成：容易陷入突然的低落或烦躁。"},{"word":"model","ipa":"/ˈmɒdl/","tag":"same Latin source, different road","definition":"Also from modus through a small form meaning 'little measure'; it belongs to design, not to feeling.","definitionCN":"同样出自 modus，经由一个意为「小尺度」的形式；属设计领域，与感受无关。"},{"word":"moderate","ipa":"/ˈmɒdərət/","tag":"same Latin source, restraint","definition":"From the same idea of measure: kept within limits. Nothing of it survives in the feeling word.","definitionCN":"同出「尺度」这一观念：保持在限度之内。表感受的那个词里没有留下它的痕迹。"}]},{"heading":"NEAR MEANING","entries":[{"word":"emotion","ipa":"/ɪˈməʊʃn/","tag":"shorter and stronger","definition":"A distinct surge such as fear or joy; a mood is the longer weather that such surges happen inside.","definitionCN":"如恐惧或喜悦那样一次明确的涌动；mood 是这些涌动所发生的更长的天气。"},{"word":"temper","ipa":"/ˈtempə/","tag":"the tendency behind it","definition":"A settled tendency to become angry, closer to temperament than to a passing state.","definitionCN":"易怒的固定倾向，更接近气质而非一时的状态。"},{"word":"atmosphere","ipa":"/ˈætməsfɪə/","tag":"place only","definition":"The feel of a space or occasion; it covers the place sense but never the inner state of one person.","definitionCN":"指空间或场合的感受；覆盖「地点」义，却从不指单个人的内在状态。"},{"word":"spirits","ipa":"/ˈspɪrɪts/","tag":"level of cheer","definition":"A plural word for how high or low someone's cheer is, as in high spirits; it measures level, not colour.","definitionCN":"指一个人兴致高低的复数说法，如兴致高；衡量的是水位，而不是颜色。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The feeling sense is native Old English, while the grammar sense came from Latin modus, so one spelling hides two families.","cn":"感受义是本族古英语，语法义则来自拉丁 modus，因此一个拼写藏着两个词族。"},{"en":"The family runs mood, moody, moodily, moodiness, mood-altering, mood board.","cn":"同族词包括 mood、moody、moodily、moodiness、mood-altering、mood board。"},{"en":"Fixed phrases mark the uses: in a good mood, in the mood for, mood swings, set the mood.","cn":"固定搭配标出用法：心情好、有兴致、情绪波动、定下气氛。"},{"en":"Grammar keeps the Latin side alive in phrases like the imperative mood.","cn":"语法在「祈使语气」一类说法里让拉丁那一面活着。"},{"en":"Markets and newspapers speak of the public mood, extending one person's weather to a whole country.","cn":"市场与报纸谈「公众情绪」，把一个人的天气扩到整个国家。"}],"abstract":[{"en":"Picture a room where the lamp does not change but the walls seem to brighten and dim.","cn":"想象灯没有变，墙面却似乎忽明忽暗的屋子。"},{"en":"Picture a thermostat that responds to conversation rather than to air.","cn":"想象一个对谈话而不是对空气作出反应的恒温器。"},{"en":"Picture a door that opens only when the person inside feels like it.","cn":"想象一扇只有在里面的人有兴致时才开的门。"}]},"examples":[{"en":"The mood in the office lifted as soon as the results arrived.","cn":"结果一到，办公室里的气氛就轻松起来。"},{"en":"I am not in the mood for a debate tonight.","cn":"我今晚没兴致辩论。"},{"en":"The subjunctive mood is rare in modern spoken English.","cn":"虚拟语气在现代英语口语中很少见。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"mood 读如「木的」——人一时像木头一样闷着 → 心情、情绪、气氛","word":"mood"},"root":"两条独立来源：表感受的义项出自古英语 mod「心、勇气、性情」，属日耳曼语；表语气的语法义借自拉丁 modus「尺度、方式」，与 mode、model 同源。","sensesIntro":{"en":"Eight senses follow one movement: a person has weather, and that weather is then read as a room's temper, as a recurring bad spell, as a manner of speaking, as a public climate, as an open door, as a pattern of swings and finally as a key chosen by an artist.","cn":"八个义项沿一个动作展开：人有天气，这天气依次被读作一间屋子的脾气、一再出现的坏脾气、一种说话方式、公众气候、一扇开着的门、一串起落的模式，最后是艺术家选定的调子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a room whose lamp never changes, yet the walls seem to brighten and dim as clouds cross the roof.","cn":"核心意象：灯始终没变的屋子，云从屋顶走过时墙面却忽明忽暗。"},"chain":["INNER WEATHER","A ROOM'S TEMPER","RECURRING SPELLS","MANNER OF SPEAKING","PUBLIC CLIMATE","A DOOR OPEN OR SHUT"],"branches":[{"senses":"01 · 07","en":"WEATHER AND ITS RECORD: one sense is a single stretch of feeling, the other the chart of how often it turns.","cn":"天气与它的记录：一个是单段感受，另一个是它翻转频率的图表。"},{"senses":"02 · 08","en":"A SPACE WITH A TEMPER: the same weather either fills a room or is deliberately composed into a work.","cn":"有脾气的空间：同一种天气要么充满一间屋子，要么被刻意编进一件作品。"},{"senses":"03","en":"THE SPELL OTHERS LEARN: a bad mood made plural becomes a recurring event in a household.","cn":"旁人学会的那阵子：坏心情一旦用复数，就成了一户人家反复发生的事。"},{"senses":"04","en":"THE OTHER HISTORY: here the word does not mean feeling at all, but the manner in which a verb speaks.","cn":"另一段历史：这里这个词完全不指感受，而指动词说话的方式。"},{"senses":"05 · 06","en":"CLIMATE AND INCLINATION: one is a whole public's weather, the other a single door that is open or shut.","cn":"气候与意愿：一个是整个公众的天气，另一个是单扇开或关的门。"}]},"affixes":{"intro":{"en":"The word is short and native, so the interesting structure lies in its family and in the separate Latin homograph.","cn":"这个词又短又是本族语，因此有意思的结构在它的词族，以及那个同形异源的拉丁词上。"},"latinIntro":{"en":"Only the grammar sense has Latin behind it, from modus 'measure, manner'; the feeling word has no Latin ancestry at all.","cn":"只有语法义背后有拉丁语，出自 modus「尺度、方式」；表感受的那个词完全没有拉丁来历。"},"items":[{"word":"mood","structure":"Old English mod (native, 'mind, courage')","meaning":"a passing state of feeling","meaningCN":"一时的感受状态","example":"The mood in the hall went flat.","exampleCN":"大厅里的情绪没了劲。"},{"word":"-y","structure":"-y (native adjective suffix, 'having the quality of')","meaning":"given to a quality","meaningCN":"具有某种性质的","example":"It forms the adjective for someone given to moods.","exampleCN":"它构成形容某人容易闹情绪的形容词。"},{"word":"moody","structure":"mood + -y","meaning":"given to low or irritable states","meaningCN":"容易陷入低落或烦躁的","example":"He grew moody before exams.","exampleCN":"考试前他变得闷闷不乐。"},{"word":"-iness","structure":"-iness (state noun from an adjective in -y)","meaning":"the quality of being X","meaningCN":"具有某种性质的状态","example":"It turns the adjective into a name for the trait.","exampleCN":"它把形容词变成该特质的名称。"},{"word":"moodiness","structure":"moody + -ness, with a spelling change","meaning":"the trait of changing mood quickly","meaningCN":"情绪多变这一特质","example":"Moodiness is common in adolescence.","exampleCN":"情绪多变在青春期很常见。"},{"word":"mood music","structure":"mood + music","meaning":"music chosen to create an atmosphere","meaningCN":"为营造气氛而选的音乐","example":"The café plays mood music all afternoon.","exampleCN":"这家咖啡馆整个下午放着氛围音乐。"},{"word":"mood swing","structure":"mood + swing","meaning":"a rapid change of feeling","meaningCN":"情绪的快速转变","example":"The doctor asked about mood swings.","exampleCN":"医生询问了情绪波动的情况。"},{"word":"modus","structure":"Latin modus (source of the grammar sense)","meaning":"measure, manner, way","meaningCN":"尺度；方式；方法","example":"The grammar sense is a separate Latin borrowing.","exampleCN":"语法义是一次独立的拉丁借入。"}],"latinEntries":[{"word":"modus","structure":"modus, modi (second declension noun)","meaning":"measure, standard, manner","meaningCN":"尺度；标准；方式"}],"derivatives":[{"word":"moody","pos":"adj.","zh":"情绪化的；闷闷不乐的"},{"word":"moodily","pos":"adv.","zh":"闷闷不乐地"},{"word":"moodiness","pos":"n.","zh":"喜怒无常"},{"word":"mood-altering","pos":"adj.","zh":"影响情绪的"}]}},{"word":"temperament","ipa_uk":"/ˈtemprəmənt/","ipa_us":"/ˈtempərəmənt/","definition_zh":"气质；性情；易激动的脾性；气质类型说；平均律（音乐）","definition_en":"the usual temper of a person or animal, or the tuning of an instrument to a settled system","core_image":"四种不同温度的水倒进同一只杯子，杯子不变，杯里的冷热却决定了它适合装什么","scene":"同一个班里，一个孩子跌倒后自己爬起来继续跑，另一个要人抱很久才肯下地，老师记住了这两个名字。Thirty years later the teacher still described them by temperament rather than by grades.","sceneCN":"这里 temperament 指「一个人天生而稳定的性情倾向」（第 1 个义项：稳定的人格气质）；句意是三十年后老师仍按性情、而不是按成绩来描述这两个人。图中可辨识物件：操场、自己爬起的孩子、被抱着的孩子。","pos":[{"tag":"n.","zh":"气质；性情；脾性"},{"tag":"n. (music)","zh":"平均律；调音体系"}],"collocations":[{"phrase":"a calm temperament","zh":"沉静的气质"},{"phrase":"by temperament","zh":"就性情而言"},{"phrase":"an artistic temperament","zh":"艺术家的脾性"},{"phrase":"temperament and environment","zh":"天性与环境"},{"phrase":"equal temperament","zh":"十二平均律"},{"phrase":"a fiery temperament","zh":"火爆的脾气"}],"forms":[{"label":"复数","form":"temperaments"},{"label":"形容词形式","form":"temperamental"},{"label":"副词形式","form":"temperamentally"},{"label":"名词（性情程度，少见）","form":"temperamentalness"},{"label":"复合名词","form":"temperament type"}],"derivatives":[{"word":"temperamental","pos":"adj.","zh":"气质的；喜怒无常的；性能不稳定的"},{"word":"temperamentally","pos":"adv.","zh":"在性情上"},{"word":"temper","pos":"n./v.","zh":"脾气 / 缓和；使适应"},{"word":"temperate","pos":"adj.","zh":"温和的；有节制的"},{"word":"temperature","pos":"n.","zh":"温度"}],"senses":[{"no":"01","title":"A settled natural disposition","titleCN":"稳定而天生的性情","definition":"the usual balance of a person's nature, especially as it shows in how they react","definitionCN":"一个人天性的通常配比，尤其体现在反应方式上","example":"The teacher described them by temperament rather than by grades.","exampleCN":"老师按性情而不是按成绩来描述他们。","why":"the word began as a word for a due mixture, so it names a ratio inside a person that stays roughly the same across situations.","whyCN":"这个词最初指「恰当的混合」，因此命名的是人体内一个在各种情境下大致不变的配比。"},{"no":"02","title":"A tendency to flare up","titleCN":"容易上火的那股劲","definition":"the part of a disposition that decides how quickly anger or excitement rises","definitionCN":"决定愤怒或兴奋升起多快的那部分性情","example":"He has the temperament of a kettle that whistles early.","exampleCN":"他的脾性像一只早早叫起来的水壶。","why":"heat is one of the oldest images in this word, which is why it so often appears with fiery or calm.","whyCN":"「热」是这个词最古老的意象之一，因此它常与「火爆」或「沉静」连用。"},{"no":"03","title":"One of the four old types","titleCN":"旧说中的四种类型之一","definition":"a category in the ancient theory that divided people by the balance of bodily humours","definitionCN":"古代按体液配比给人分类的那套理论中的一个类别","example":"The four temperaments were once taught as medical fact.","exampleCN":"四种气质类型曾被当作医学事实讲授。","why":"classical medicine explained character by the mixture of fluids in the body, and the word still carries that taxonomy.","whyCN":"古典医学用体内液体的混合来解释性格，这个词至今带着那套分类。"},{"no":"04","title":"A system of tuning","titleCN":"一套调音体系","definition":"a way of tuning instruments so that the notes stay in usable relations across keys","definitionCN":"一种调音方式，使各音在各调之间保持可用的关系","example":"Equal temperament made the piano a flexible instrument.","exampleCN":"十二平均律让钢琴成为一件灵活的乐器。","why":"in music the word keeps its literal sense of adjusting a mixture until it balances, applied here to intervals.","whyCN":"在音乐里，这个词保留了「把混合调到平衡」的字面义，只是把对象换成了音程。"},{"no":"05","title":"An animal's handling","titleCN":"动物的性子与好不好带","definition":"the disposition of an animal, especially as it affects how easily it can be worked with","definitionCN":"动物的性情，尤其影响它好不好驾驭","example":"The breed is chosen for a steady temperament around children.","exampleCN":"选这个品种，是因为它在孩子身边性子稳。","why":"the word applies wherever a creature has a fixed setting, which is why breeders use it like a specification.","whyCN":"凡是有固定「设定」的生物都适用这个词，因此育种者拿它当规格来用。"},{"no":"06","title":"The temper of an age","titleCN":"一个时代的脾气","definition":"the prevailing character of a period or a group, spoken of as if it were a person","definitionCN":"某个时期或群体的主导性格，被当作一个人来说","example":"Historians speak of the temperament of the decade.","exampleCN":"史学家会谈那十年的时代脾气。","why":"the metaphor of a body with balanced fluids transfers easily to a collective, which is how whole eras get a temper.","whyCN":"「体内液体平衡」这一比喻很容易搬到集体上，整个时代于是有了脾气。"},{"no":"07","title":"The fit between parts","titleCN":"各部分之间的配比","definition":"the working balance among mixed elements, as in a blend or an arrangement","definitionCN":"混合成分之间起作用的配比，如调配或布局","example":"The garden's temperament comes from the ratio of stone to green.","exampleCN":"这座园子的脾性来自石头与绿意的配比。","why":"this sense reaches back to the original meaning of a measured mixture and keeps the word's earliest image alive.","whyCN":"这个义项回到「按量混合」的本义，让这个词最早的意象继续活着。"},{"no":"08","title":"A temperamental machine","titleCN":"忽好忽坏的机器","definition":"the use of the derived adjective for equipment that works only when it feels like it","definitionCN":"用其派生形容词指只在它高兴时才肯工作的设备","example":"The old press is temperamental in cold weather.","exampleCN":"那台老印刷机天冷时脾气很坏。","why":"machines are described with this family because they are treated as having a disposition, which is the joke the usage rests on.","whyCN":"机器被用这一词族来描述，是因为它们被当作有性情，这个用法正建立在这个玩笑上。"}],"etymology":{"intro":{"en":"Temperament comes from Latin temperamentum 'a due mixture', from temperare 'to mix in proportion, to moderate'. Classical medicine used it for the balance of bodily humours, and music borrowed it for the tuning of intervals. Dates are approximate.","cn":"temperament 来自拉丁 temperamentum「恰当的混合」，出自 temperare「按比例调配、节制」。古典医学用它指体液配比，音乐则借它指音程的调校。年代均为约数。"},"items":[{"era":"LATIN TEMPERARE","en":"Temperare meant 'to divide or mix in due proportion, to moderate'. A suggested link to tempus 'time' is a hypothesis, not a demonstrated derivation.","cn":"temperare 意为「按适当比例调和、节制」。有人认为它与意为「时间」的词有关，那只是假说，并非已证实的派生。"},{"era":"LATIN TEMPERAMENTUM","en":"The noun named the resulting balance, first of climate and of bodily fluids, later of any mixture.","cn":"这个名词指混合后的平衡，先是气候与体液，后来是任何混合。"},{"era":"HUMOURAL MEDICINE","en":"Greek and then Latin medicine explained health and character by four fluids, so temperament became a medical word for a person's constitutional balance.","cn":"希腊继而拉丁医学用四种液体解释健康与性格，于是 temperament 成为指个人体质配比的医学词。"},{"era":"ENGLISH ADOPTION","en":"English took the word in the sixteenth century for a person's habitual disposition, and the older medical theory faded while the word stayed.","cn":"英语在 16 世纪借入这个词，指一个人惯常的性情；旧医学理论衰落，词却留了下来。"},{"era":"MUSICAL SENSE","en":"From the seventeenth century musicians used it for the tuning of intervals, where a tempered system is one deliberately adjusted to balance.","cn":"从 17 世纪起，音乐家用它指音程的调校，所谓「调律体系」就是刻意调整以求平衡的系统。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of temperare is a reconstruction, and the exact date of the musical use is not fixed.","cn":"来源不确定：temperare 在拉丁语之前的来源属重构形式，音乐义的确切年代也未定。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin verb of mixing, which differ sharply in meaning; group two holds the words for character that psychologists keep apart.","cn":"第一组是同出拉丁「调配」动词、意义却相差很远的词；第二组是心理学家刻意区分的性格词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"temperature","ipa":"/ˈtempərətʃə/","tag":"same root, heat","definition":"From the same Latin verb through a noun for a tempered state: it measures heat, not character, and the resemblance is purely historical.","definitionCN":"同出那个拉丁动词，经一个表调匀状态的名词而来：它量的是热度，不是性格，相似纯属历史同源。"},{"word":"temper","ipa":"/ˈtempə/","tag":"the short form","definition":"The shorter relative: as a noun it means a tendency to anger, as a verb to soften or moderate something.","definitionCN":"较短的亲属词：作名词指易怒的倾向，作动词指使变软或使缓和。"},{"word":"temperate","ipa":"/ˈtempərət/","tag":"kept within limits","definition":"The adjective of restraint, used of climate, habits and speech; it describes moderation rather than an inborn balance.","definitionCN":"指有节制的形容词，用于气候、习惯与言谈；它描述的是节制，而不是天生的配比。"},{"word":"temperamental","ipa":"/ˌtempərəˈmentl/","tag":"derived adjective","definition":"Built on this noun: it can mean 'of temperament' but is used far more often for people or machines that change behaviour abruptly.","definitionCN":"由本名词构成：可指「性情的」，但更常用于形容人或机器行为突然多变。"}]},{"heading":"NEAR MEANING","entries":[{"word":"personality","ipa":"/ˌpɜːsəˈnæləti/","tag":"the whole pattern","definition":"The total pattern of traits and behaviour built over a life; temperament is the part thought to be inborn and stable.","definitionCN":"一生中形成的特质与行为的总格局；temperament 是其中被认为天生而稳定的那一部分。"},{"word":"disposition","ipa":"/dɪˈspəzɪʃn/","tag":"readiness to act","definition":"A settled readiness to behave in a certain way; it is less biological in tone than temperament.","definitionCN":"按某种方式行事的固定倾向；在语气上不如 temperament 那样带生理色彩。"},{"word":"character","ipa":"/ˈkærəktə/","tag":"moral shape","definition":"The moral shape of a person, judged as strong or weak; temperament says nothing about virtue.","definitionCN":"一个人的道德形状，可评为坚强或软弱；temperament 与德行无关。"},{"word":"nature","ipa":"/ˈneɪtʃə/","tag":"plain and broad","definition":"The everyday word for what someone is like by birth; it is broader and carries no theory of humours.","definitionCN":"指一个人天生怎样的日常词；更宽，也不带任何体液理论。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb behind it means 'to mix in due proportion', so a temperament is a recipe that came out balanced.","cn":"背后的拉丁动词意为「按比例调配」，因此气质就是一份调得刚好的配方。"},{"en":"The family runs temperament, temperamental, temperamentally, temper, temperate, temperature.","cn":"同族词包括 temperament、temperamental、temperamentally、temper、temperate、temperature。"},{"en":"Fixed phrases mark the uses: a calm temperament, by temperament, an artistic temperament.","cn":"固定搭配标出用法：沉静的气质、就性情而言、艺术家的脾性。"},{"en":"Equal temperament is the musical sense, where intervals are adjusted to balance.","cn":"十二平均律是音乐义，那里音程被调校以求平衡。"},{"en":"The four temperaments come from the old medicine of bodily humours.","cn":"四种气质类型来自旧的体液医学。"}],"abstract":[{"en":"Picture four cups of water at different temperatures poured into one glass.","cn":"想象四杯不同温度的水倒进同一只杯子。"},{"en":"Picture a kettle whose whistle comes at different moments for different owners.","cn":"想象一只水壶，对不同主人有不同的鸣叫时刻。"},{"en":"Picture a piano tuned so that every key agrees to compromise.","cn":"想象一架钢琴被调成每个键都同意让步。"}]},"examples":[{"en":"By temperament she is patient, though the work tests her daily.","cn":"就性情而言她很有耐心，尽管这份工作每天在考验她。"},{"en":"The two brothers share a temperament but not a vocabulary.","cn":"两兄弟性情相同，说话方式却完全不同。"},{"en":"Equal temperament allows a keyboard instrument to play in every key.","cn":"十二平均律让键盘乐器能在所有调上演奏。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"temper（调和）+ ament（东西）——把身体里的冷热调成一配方 → 气质、性情","word":"temperament"},"root":"拉丁 temperamentum「恰当的混合」，出自 temperare「按比例调配、节制」；古典医学用它指体液配比，音乐借它指调律。与表「时间」的词是否有联系仅为假说。","sensesIntro":{"en":"Eight senses follow one movement: a mixture is brought into balance, and that balance is then read as a person's settled nature, as heat, as one of four types, as a tuning system, as an animal's setting, as the temper of an age, as a ratio among parts and finally as a machine's whims.","cn":"八个义项沿一个动作展开：混合物被调到平衡，这个平衡依次被读作一个人稳定的天性、热度、四种类型之一、一套调律、动物的设定、一个时代的脾气、各部分之间的配比，最后是机器的任性。"},"semanticMap":{"core":{"en":"CORE IMAGE: four waters at different temperatures poured into one glass, so the glass decides what it can hold.","cn":"核心意象：四杯不同温度的水倒进同一只杯子，杯子于是决定了它能装什么。"},"chain":["A BALANCED MIX","THE PERSON'S SETTING","HOW FAST IT HEATS","FOUR OLD TYPES","A TUNED SYSTEM","THE TEMPER OF A TIME"],"branches":[{"senses":"01 · 02","en":"THE RATIO AND ITS HEAT: the settled mixture first, then the question of how quickly it boils.","cn":"配比与热度：先是定下来的混合，再是它多快沸腾。"},{"senses":"03","en":"THE OLD TAXONOMY: the mixture turned into named types by classical medicine.","cn":"旧的分类：古典医学把这种混合变成几个有名字的类型。"},{"senses":"04","en":"BALANCE APPLIED TO SOUND: music adjusts intervals by the same logic of compromise.","cn":"平衡用于声音：音乐用同一套让步的逻辑来调音程。"},{"senses":"05 · 07","en":"SETTINGS EVERYWHERE: an animal's handling and a garden's ratio are the same idea read on other objects.","cn":"各处的设定：动物的性子与园子的配比，是同一观念读在别的对象上。"},{"senses":"06 · 08","en":"FROM AN AGE TO A MACHINE: collectives and equipment get a temper, and the metaphor stretches until it becomes a joke.","cn":"从时代到机器：集体与设备都得到了脾气，比喻一路拉伸，直到成了玩笑。"}]},"affixes":{"intro":{"en":"The word is built from a Latin verb of mixing plus a Latin noun-forming element, and the same pieces recur across a large family.","cn":"这个词由一个拉丁「调配」动词加一个拉丁名词构词成分搭成，同样的成分反复出现在一大族词里。"},"latinIntro":{"en":"Latin temperare gives temper, temperament, temperate and temperature, all through the idea of bringing something to a due measure.","cn":"拉丁 temperare 衍生 temper、temperament、temperate、temperature，全部经由「把某物调到适当的度」这一观念。"},"items":[{"word":"temperare","structure":"temperare (Latin verb, first conjugation)","meaning":"to mix in proportion, moderate","meaningCN":"按比例调和；节制","example":"The verb supplies the idea of a measured mixture.","exampleCN":"这个动词提供「按量混合」的意思。"},{"word":"-mentum","structure":"-mentum (Latin noun-forming element)","meaning":"means or result of an action","meaningCN":"动作的手段或结果","example":"It turns the verb into the name of a resulting balance.","exampleCN":"它把这个动词变成调好之后的平衡的名称。"},{"word":"temperamentum","structure":"temperare + -mentum","meaning":"a due mixture, a balanced state","meaningCN":"恰当的混合；平衡状态","example":"The noun first described climate and body fluids.","exampleCN":"这个名词最初描述气候与体液。"},{"word":"temperament","structure":"temperamentum, through French","meaning":"a settled disposition","meaningCN":"稳定的性情","example":"He has a calm temperament.","exampleCN":"他性情沉静。"},{"word":"temperamental","structure":"temperament + -al (relating to)","meaning":"of disposition; changeable in behaviour","meaningCN":"性情的；行为多变的","example":"The press is temperamental in winter.","exampleCN":"那台印刷机天冷时脾气很坏。"},{"word":"temperamentally","structure":"temperamental + -ly (adverb)","meaning":"as far as disposition goes","meaningCN":"在性情上","example":"They are temperamentally unsuited.","exampleCN":"他们在性情上并不合适。"},{"word":"temper","structure":"temperare, shortened in English","meaning":"a tendency to anger; to moderate","meaningCN":"易怒的倾向；使缓和","example":"He lost his temper at the gate.","exampleCN":"他在门口发了脾气。"},{"word":"temperature","structure":"temperatura, from temperare","meaning":"the degree of heat","meaningCN":"热度；温度","example":"The same root measures heat elsewhere.","exampleCN":"同一个词根在别处用来量热度。"},{"word":"temperate","structure":"temperare + -atus (adjective)","meaning":"kept within limits","meaningCN":"有节制的；温和的","example":"A temperate climate suits the crop.","exampleCN":"温和的气候适合这种作物。"}],"latinEntries":[{"word":"temperare","structure":"temperare, tempero, temperavi, temperatum (verb)","meaning":"to mix in due proportion, moderate","meaningCN":"按比例调和；节制"},{"word":"temperamentum","structure":"temperare + -mentum (noun)","meaning":"a due mixture, balance","meaningCN":"恰当的混合；平衡"},{"word":"temperatura","structure":"temperare + -tura (noun)","meaning":"a tempering, due mixture; later, heat level","meaningCN":"调和；适当混合；后指热度"}],"derivatives":[{"word":"temperamental","pos":"adj.","zh":"性情的；喜怒无常的"},{"word":"temperamentally","pos":"adv.","zh":"在性情上"},{"word":"temper","pos":"n./v.","zh":"脾气 / 缓和"},{"word":"temperate","pos":"adj.","zh":"有节制的；温和的"},{"word":"temperature","pos":"n.","zh":"温度"}]}},{"word":"personality","ipa_uk":"/ˌpɜːsəˈnæləti/","ipa_us":"/ˌpɜːrsəˈnæləti/","definition_zh":"个性；性格；人格；名人；魅力；地方或事物的鲜明风格","definition_en":"the whole pattern of qualities that makes a person distinct, or a famous person, or the quality of being vividly oneself","core_image":"同一张素坯在窑里被反复上釉，最后开窑时只有它一只带着那种说不出名字的亮","scene":"面试官问了他三个问题，最后只记下一句：这个人说话时会停下来听别人说完。The interviewer noted a personality that made the room slow down.","sceneCN":"这里 personality 指「一个人整体上给人的性格印象」（第 1 个义项：整体的性格格局）；句意是面试官注意到一种让整个房间放慢下来的性格。图中可辨识物件：面试桌、停在半空的笔、两份摊开的简历。","pos":[{"tag":"n.","zh":"个性；性格；人格"},{"tag":"n. (a famous person)","zh":"名人（尤指娱乐界、媒体人物）"},{"tag":"n. (uncountable, personal charm)","zh":"魅力；鲜明的个人风格"}],"collocations":[{"phrase":"personality traits","zh":"人格特质"},{"phrase":"a strong personality","zh":"个性强的人；强势性格"},{"phrase":"personality disorder","zh":"人格障碍"},{"phrase":"personality test","zh":"人格测验"},{"phrase":"television personality","zh":"电视名人"},{"phrase":"personality clash","zh":"性格冲突"}],"forms":[{"label":"复数","form":"personalities"},{"label":"形容词形式","form":"personal"},{"label":"形容词形式","form":"personable"},{"label":"动词形式","form":"personalize"},{"label":"名词形式","form":"person"}],"derivatives":[{"word":"personal","pos":"adj.","zh":"个人的；私人的"},{"word":"personable","pos":"adj.","zh":"讨人喜欢的；易亲近的"},{"word":"personality trait","pos":"n. phrase","zh":"人格特质"},{"word":"depersonalize","pos":"v.","zh":"使失去个性；使非人格化"},{"word":"impersonate","pos":"v.","zh":"冒充；扮演"}],"senses":[{"no":"01","title":"The whole pattern of a person","titleCN":"一个人整体的性格格局","definition":"the total set of qualities that makes one person different from another","definitionCN":"使一个人区别于另一个人的全部品质所构成的整体","example":"The interviewer noted a personality that made the room slow down.","exampleCN":"面试官注意到一种让整个房间放慢下来的性格。","why":"the word was built from the name for a mask, so it names the face a person presents to the world in all its parts.","whyCN":"这个词由「面具」一词构成，因此命名的是一个人向世界呈现的整张脸，连同它的各个部分。"},{"no":"02","title":"An object of psychological study","titleCN":"心理学的研究对象","definition":"the measurable structure of traits that psychologists describe and classify","definitionCN":"心理学家加以描述与分类的那些可测量的特质结构","example":"The field treats personality as a set of dimensions rather than a single score.","exampleCN":"这个领域把人格当作一组维度，而不是一个单一分数。","why":"once qualities are counted and rated, the whole pattern becomes a research object with its own instruments.","whyCN":"品质一旦被计数与评级，整个格局就成了一个有自己仪器配套的研究对象。"},{"no":"03","title":"A famous face","titleCN":"出名的面孔","definition":"a well-known person, especially one who appears in media","definitionCN":"广为人知的人，尤指常在媒体露面者","example":"A television personality opened the charity event.","exampleCN":"一位电视名人主持了这场慈善活动。","why":"public life reduces a whole person to the face the public knows, so the word slides from the pattern to the person who carries it.","whyCN":"公众生活把整个人压缩成公众认得的那张脸，于是词义从格局滑向承载它的那个人。"},{"no":"04","title":"Charm that fills a room","titleCN":"能撑起一间屋子的魅力","definition":"a quality of presence that draws attention and holds it","definitionCN":"一种让人注意并被吸住的存在感","example":"The old hostess had more personality than the whole cast.","exampleCN":"那位老女主人比整台演员加起来更有魅力。","why":"when the pattern is vivid enough, it stops being a description and becomes an effect on others.","whyCN":"当这个格局鲜明到一定程度，它就不再是描述，而成了对他人产生的效果。"},{"no":"05","title":"A place with a face of its own","titleCN":"有自己的面孔的地方","definition":"the distinctive character of a building, street or brand","definitionCN":"建筑、街道或品牌所带的鲜明性格","example":"The market kept its personality even after the renovation.","exampleCN":"改造之后这个市场仍保有自己的性格。","why":"the metaphor is easy to move outward: whatever presents a consistent face to people can be said to have a personality.","whyCN":"这个比喻很容易向外搬：凡是向人呈现一致面孔的东西，都可以说有性格。"},{"no":"06","title":"A classified type","titleCN":"被归类的一种类型","definition":"one of the recognised kinds into which patterns of character are sorted","definitionCN":"把性格格局分门别类之后得到的某一类","example":"The test sorts people into four personality types.","exampleCN":"这个测验把人分成四种人格类型。","why":"classification is the next step after measurement, and the noun then serves as the label of a class.","whyCN":"测量之后的下一步是分类，这个名词于是充当某一类的标签。"},{"no":"07","title":"Friction between two patterns","titleCN":"两种性格之间的摩擦","definition":"the incompatibility that arises when two people's habits of behaviour do not fit","definitionCN":"两个人的行为习惯合不来时产生的不相容","example":"The project failed on a personality clash, not on the budget.","exampleCN":"项目败于性格冲突，而不是预算。","why":"the word can name a cause of trouble, which shows how much weight English gives to the pattern itself.","whyCN":"这个词可以命名麻烦的起因，可见英语把这个格局本身看得多重。"},{"no":"08","title":"Legal standing as a person","titleCN":"法律上的人格地位","definition":"the status of being recognised as a person before the law, as held by a company","definitionCN":"在法律上被认作人的地位，公司也可具有","example":"A company has legal personality separate from its owners.","exampleCN":"公司在法律上具有独立于其所有者的人格。","why":"the oldest layer of the word is the mask that a role makes one wear, and law still speaks of the mask a body wears.","whyCN":"这个词最古老的一层是角色所戴的面具，法律至今仍在说某个实体所戴的那张面具。"}],"etymology":{"intro":{"en":"Personality comes from Latin personalitas, built on persona 'a mask, a character in a play'. The origin of persona itself is not established; the old explanation that it meant 'something through which sound passes' is a hypothesis. Dates are approximate.","cn":"personality 来自拉丁 personalitas，由 persona「面具、剧中角色」构成。persona 本身的来源未得到证明；旧说认为它指「声音从中穿过之物」，那只是假说。年代均为约数。"},"items":[{"era":"LATIN PERSONA","en":"Persona named a mask worn by an actor and, by extension, the role played. Its deeper origin is uncertain; a link to a borrowed Etruscan word is one hypothesis among several.","cn":"persona 指演员戴的面具，引申为所演的角色。其更深来源不确定；认为它借自某种伊特鲁里亚词，只是若干假说之一。"},{"era":"LATIN PERSONALITAS","en":"The abstract noun named the quality of being a particular person, first in legal and theological writing about the status of an individual.","cn":"这个抽象名词指「作为某个特定个人的性质」，最早见于讨论个人地位的法律与神学文字。"},{"era":"ENGLISH ADOPTION","en":"English took the word in the eighteenth century for the sum of a person's qualities, at a time when portraits and novels were making individuality interesting.","cn":"英语在 18 世纪借入这个词，指一个人品质的总和，当时肖像画与小说正让「个体性」变得有趣。"},{"era":"PSYCHOLOGY","en":"Nineteenth- and twentieth-century psychology turned it into a measurable structure, giving rise to tests, types and disorders.","cn":"19 与 20 世纪心理学把它变成可测量的结构，于是有了测验、类型与障碍。"},{"era":"MEDIA SENSE","en":"Twentieth-century broadcasting made the word mean a famous face as well as an inner pattern, and the two senses now coexist.","cn":"20 世纪的广播电视让这个词既指有名的面孔，也指内在格局，两个义项如今并存。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of persona is a reconstruction, and the exact first English use of the abstract noun is not agreed.","cn":"来源不确定：persona 在拉丁语之前的来源属重构形式，这个抽象名词在英语中最早的确切用例也无公认结论。"}]},"similar":{"note":{"en":"Group one holds words built on the Latin word for a mask, whose meanings have drifted apart; group two holds the character words that overlap with this one.","cn":"第一组是同出拉丁「面具」一词、意义却已分流的词；第二组是与本词重叠的性格类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"person","ipa":"/ˈpɜːsn/","tag":"the bearer, not the pattern","definition":"The plain noun for an individual human being; this word names the pattern that individual carries.","definitionCN":"指单个的人的普通名词；本词命名的是那个人所带的格局。"},{"word":"personal","ipa":"/ˈpɜːsənl/","tag":"belonging to one person","definition":"Said of things that belong to or concern one individual, such as a personal letter; it never means 'full of character'.","definitionCN":"指属于或涉及某一个人的东西，如私人信件；从不表示「有性格」。"},{"word":"personable","ipa":"/ˈpɜːsənəbl/","tag":"pleasant to meet","definition":"Describes someone easy to like on first meeting, which is a social impression rather than a whole pattern.","definitionCN":"形容初次见面就容易让人喜欢，是社会印象，而非整体格局。"},{"word":"persona","ipa":"/pəˈsəʊnə/","tag":"the mask itself","definition":"The borrowed Latin word for the face one presents in public, often deliberately different from the private self.","definitionCN":"借来的拉丁词，指在公众面前呈现的那张脸，常刻意与私下自我不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"character","ipa":"/ˈkærəktə/","tag":"moral weight","definition":"Overlaps in the sense of make-up, but character also judges moral fibre, which personality does not.","definitionCN":"在「构成」这一义上重叠，但 character 还评判道德骨气，而 personality 不作此评判。"},{"word":"temperament","ipa":"/ˈtemprəmənt/","tag":"the inborn part","definition":"The part of the pattern thought to be native and steady; personality includes what experience adds.","definitionCN":"格局中被认为天生而稳定的那部分；personality 还包括经验添上的部分。"},{"word":"identity","ipa":"/aɪˈdentəti/","tag":"who one is","definition":"The sense of who one is, including group membership; it answers 'who', while this word answers 'what kind'.","definitionCN":"指「我是谁」的认知，包括群体归属；它回答「谁」，而本词回答「什么样」。"},{"word":"ego","ipa":"/ˈiːɡəʊ/","tag":"technical","definition":"A technical term for the self as it mediates; it belongs to theory rather than to everyday description.","definitionCN":"指起中介作用的自我，是理论术语，而非日常描述。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The base is Latin persona 'mask', so personality is the face a person wears in all its parts.","cn":"词基是拉丁 persona「面具」，因此 personality 就是一个人戴着的那张完整的脸。"},{"en":"The family runs person, personal, personality, personable, impersonate, depersonalize.","cn":"同族词包括 person、personal、personality、personable、impersonate、depersonalize。"},{"en":"Fixed phrases mark the uses: personality traits, personality test, personality clash, television personality.","cn":"固定搭配标出用法：人格特质、人格测验、性格冲突、电视名人。"},{"en":"Psychologists speak of personality disorders, which shows the technical sense is a whole structure.","cn":"心理学家谈人格障碍，可见专业义指的是整套结构。"},{"en":"Law speaks of legal personality, keeping the oldest mask metaphor alive.","cn":"法律说法律人格，让最古老的面具比喻继续活着。"}],"abstract":[{"en":"Picture one plain bowl that takes glaze after glaze until only it shines that way.","cn":"想象一只素坯一遍遍上釉，最后只有它那样发亮。"},{"en":"Picture a room whose furniture rearranges itself around one guest.","cn":"想象一间屋子的家具围着一位客人重新排列。"},{"en":"Picture a signature that can be read from across the street.","cn":"想象一个隔一条街都能认出的签名。"}]},"examples":[{"en":"The job needs a strong personality and a thick skin.","cn":"这份工作需要强势的性格和厚脸皮。"},{"en":"Their personalities never meshed, though their skills did.","cn":"他们的性格始终合不来，技能却互补。"},{"en":"The magazine turned a shy researcher into a media personality.","cn":"这家杂志把一位腼腆的研究者变成了媒体名人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"person（人）+ ality（性质）——一个人整体的那种性质 → 个性、人格","word":"personality"},"root":"拉丁 personalitas，由 persona「面具、剧中角色」构成；persona 的更深来源不确定，借自伊特鲁里亚语之说仅为假说之一。","sensesIntro":{"en":"Eight senses follow one movement: a mask is worn, and that mask is then read as a whole pattern, as something measured, as a famous face, as charm, as the face of a place, as a type, as a cause of friction and finally as legal standing.","cn":"八个义项沿一个动作展开：一张面具被戴上，这张面具依次被读作整体格局、被测量的对象、有名的面孔、魅力、一个地方的脸、一种类型、摩擦的起因，最后是法律地位。"},"semanticMap":{"core":{"en":"CORE IMAGE: one plain bowl that takes glaze after glaze until it alone shines in that particular way.","cn":"核心意象：一只素坯一遍遍上釉，最后只有它那样发亮。"},"chain":["A MASK WORN","THE WHOLE PATTERN","MEASURED AND CLASSIFIED","THE FACE THE PUBLIC KNOWS","CHARM THAT FILLS A ROOM","A FACE ON A PLACE"],"branches":[{"senses":"01 · 02","en":"THE PATTERN AND ITS INSTRUMENTS: first the whole make-up, then the same make-up turned into dimensions and scores.","cn":"格局与它的仪器：先是整体构成，再是同一构成被变成维度与分数。"},{"senses":"03 · 04","en":"THE FACE AND ITS FORCE: a famous face is the pattern reduced to what the public sees, and charm is that pattern acting on a room.","cn":"面孔与它的力：名人的脸是被压缩成公众所见之物的格局，魅力则是这格局在一间屋子里起作用。"},{"senses":"05","en":"THE SAME FACE ON THINGS: buildings, streets and brands are read as wearing a consistent face.","cn":"同样的脸长在物上：建筑、街道与品牌被读作戴着一张一致的脸。"},{"senses":"06 · 07","en":"FROM TYPE TO FRICTION: classification gives classes, and putting two classes in one room gives trouble.","cn":"从类型到摩擦：分类给出类别，把两个类别放进同一间屋子就生出麻烦。"},{"senses":"08","en":"THE MASK BEFORE THE LAW: legal standing keeps the oldest sense, where a mask makes a thing count as a person.","cn":"法律面前的面具：法律地位保留了最古老的义项，面具使某物被算作人。"}]},"affixes":{"intro":{"en":"The word is a Latin abstract noun built on the Latin word for a mask, so the whole family reads from that single image.","cn":"这个词是一个拉丁抽象名词，建在拉丁「面具」一词上，因此整个词族都从那张面具读起。"},"latinIntro":{"en":"Latin persona gives person, personal, personality, personable, persona and impersonate, all through the image of a mask and a role.","cn":"拉丁 persona 衍生 person、personal、personality、personable、persona、impersonate，全部经由面具与角色的意象。"},"items":[{"word":"persona","structure":"persona (Latin noun, first declension)","meaning":"mask; role; character","meaningCN":"面具；角色；人物","example":"The mask is the root of the whole family.","exampleCN":"那张面具是整个词族的根。"},{"word":"-alis","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"It produced the adjective of belonging.","exampleCN":"它造出表归属的形容词。"},{"word":"-itas","structure":"-itas (Latin abstract noun suffix)","meaning":"the quality of being X","meaningCN":"具有某种性质","example":"It turned the adjective into an abstract noun.","exampleCN":"它把形容词变成抽象名词。"},{"word":"personality","structure":"personalis + -itas","meaning":"the quality of being a particular person","meaningCN":"作为某个特定个人的性质","example":"The interviewer noted a personality.","exampleCN":"面试官注意到一种性格。"},{"word":"personal","structure":"persona + -alis","meaning":"belonging to one person","meaningCN":"属于个人的","example":"It was a personal letter.","exampleCN":"那是一封私人信件。"},{"word":"personable","structure":"person + -able (capable of being)","meaning":"easy to like on meeting","meaningCN":"见面容易让人喜欢的","example":"The candidate was personable.","exampleCN":"那位候选人很讨人喜欢。"},{"word":"impersonate","structure":"im- 'in' + persona + -ate","meaning":"to put on another's mask","meaningCN":"戴上别人的面具；冒充","example":"He impersonated an officer.","exampleCN":"他冒充了一名军官。"},{"word":"depersonalize","structure":"de- 'away' + personal + -ize","meaning":"to strip away personal character","meaningCN":"去掉个人特征","example":"The forms depersonalize the applicant.","exampleCN":"这些表格让申请人失去个人面目。"},{"word":"person","structure":"persona, shortened in English","meaning":"an individual human being","meaningCN":"人；个人","example":"Every person wears a mask somewhere.","exampleCN":"每个人都在某处戴着面具。"}],"latinEntries":[{"word":"persona","structure":"persona, personae (first declension noun)","meaning":"mask, role, character","meaningCN":"面具；角色；人物"},{"word":"personalis","structure":"persona + -alis (adjective)","meaning":"of a person, personal","meaningCN":"个人的；属于人的"},{"word":"personalitas","structure":"personalis + -itas (noun)","meaning":"the quality of being a person","meaningCN":"作为个人的性质；人格"}],"derivatives":[{"word":"personal","pos":"adj.","zh":"个人的；私人的"},{"word":"personable","pos":"adj.","zh":"讨人喜欢的"},{"word":"personally","pos":"adv.","zh":"亲自；就个人而言"},{"word":"impersonate","pos":"v.","zh":"冒充；扮演"},{"word":"depersonalization","pos":"n.","zh":"人格解体；去个人化"}]}},{"word":"personality trait","ipa_uk":"/ˌpɜːsəˈnæləti treɪt/","ipa_us":"/ˌpɜːrsəˈnæləti treɪt/","definition_zh":"人格特质；性格特征；可测量而相对稳定的行为倾向","definition_en":"a stable, measurable tendency in a person's behaviour that forms part of the wider pattern of character","core_image":"一张织物的放大图：整块布看不出花样，退后一步才看见经线与纬线交织成的那道纹","scene":"同一份问卷发给上千人，答案里反复出现的那几条，最后被研究者画成了一条曲线。One personality trait stood out across every age group in the survey.","sceneCN":"这里 personality trait 指「人格中一条可测量、相对稳定的倾向」（第 1 个义项：人格的可测倾向）；句意是有一项人格特质在所有年龄组里都很突出。图中可辨识物件：问卷、堆叠的答题纸、一条上升的曲线。","pos":[{"tag":"n. phrase","zh":"人格特质；性格特征"}],"collocations":[{"phrase":"a personality trait","zh":"一项人格特质"},{"phrase":"positive personality traits","zh":"积极的人格特质"},{"phrase":"inherited personality trait","zh":"遗传的人格特质"},{"phrase":"measure personality traits","zh":"测量人格特质"},{"phrase":"the Big Five personality traits","zh":"大五人格特质"}],"forms":[{"label":"复数","form":"personality traits"},{"label":"作定语形式","form":"personality-trait"},{"label":"相关单数名词","form":"trait"},{"label":"相关名词","form":"personality"},{"label":"近义说法","form":"character trait"}],"derivatives":[{"word":"trait","pos":"n.","zh":"特征；特质"},{"word":"personality","pos":"n.","zh":"人格；个性"},{"word":"character trait","pos":"n. phrase","zh":"性格特征"},{"word":"trait theory","pos":"n. phrase","zh":"特质理论"}],"senses":[{"no":"01","title":"One measurable tendency","titleCN":"一条可测量的倾向","definition":"a single stable tendency that can be rated and compared across people","definitionCN":"一条稳定倾向，可被评级并在人与人之间比较","example":"One personality trait stood out across every age group.","exampleCN":"有一项人格特质在所有年龄组里都很突出。","why":"the phrase narrows a whole pattern to one thread, which is what makes counting possible at all.","whyCN":"这个词组把整块格局收窄成一根线，正是这一点让计数成为可能。"},{"no":"02","title":"A building block of character","titleCN":"性格的组成单元","definition":"a component out of which the larger pattern of a person is assembled","definitionCN":"用来组装一个人更大格局的构件","example":"Patience is a personality trait that can be trained.","exampleCN":"耐心是一项可以训练的人格特质。","why":"a pattern needs parts, and this phrase names the parts rather than the whole.","whyCN":"格局需要零件，这个词组命名的正是零件，而不是整体。"},{"no":"03","title":"A tendency that runs in families","titleCN":"在家族中延续的倾向","definition":"a trait shown by studies to be partly inherited rather than wholly learned","definitionCN":"研究显示部分来自遗传、而非完全习得的特质","example":"Shyness is treated as an inherited personality trait in some studies.","exampleCN":"在一些研究里，害羞被当作一种可遗传的人格特质。","why":"once a trait is measured, the next question is where it comes from, and inheritance is one answer.","whyCN":"特质一旦能被测量，下一个问题就是它从哪里来，遗传承是其中一个答案。"},{"no":"04","title":"One of the five dimensions","titleCN":"五大维度中的一项","definition":"a member of the widely used five-factor classification of character","definitionCN":"广为使用的五因素人格分类中的某一项","example":"Conscientiousness is the personality trait most tied to school results.","exampleCN":"尽责性是五项人格特质中与学业成绩关系最紧的一项。","why":"classification reduces many traits to a few dims, and each of those dims is still called a trait.","whyCN":"分类把许多特质压缩成少数几个维度，而其中每个维度仍被称为一项特质。"},{"no":"05","title":"A reading of how someone acts","titleCN":"对某人行为方式的解读","definition":"the label an observer applies when the same behaviour keeps recurring","definitionCN":"观察者在同一行为反复出现时贴上的标签","example":"Neatness is a personality trait only if it shows up without being asked.","exampleCN":"只有当整洁无需要求便出现时，它才算一项人格特质。","why":"a trait is inferred from repetition, so it is a reading of behaviour rather than the behaviour itself.","whyCN":"特质是从重复中推断出来的，因此它是对行为的解读，而不是行为本身。"},{"no":"06","title":"An item on an assessment form","titleCN":"测评表上的一栏","definition":"a scored item in hiring, clinical or educational assessment","definitionCN":"招聘、临床或教育测评中被打分的一栏","example":"The form lists twelve personality traits and asks for evidence.","exampleCN":"表格列出十二项人格特质，并要求给出依据。","why":"institutions need comparable entries, so the phrase becomes a row on a form with a number beside it.","whyCN":"机构需要可比较的条目，于是这个词组变成表格上的一行，旁边配一个数字。"},{"no":"07","title":"A trait that can be praised or blamed","titleCN":"可褒可贬的特质","definition":"the same tendency seen as a virtue in one setting and a fault in another","definitionCN":"同一条倾向在一种场合被看作长处，在另一种场合被看作毛病","example":"Stubbornness is the same personality trait as persistence, seen from the other side.","exampleCN":"固执与坚持是同一项人格特质，只是从另一面看。","why":"value is added by the observer, not by the trait, which is why the same behaviour gets two names.","whyCN":"价值是观察者添上的，不是特质自带的，因此同一行为会有两个名字。"},{"no":"08","title":"A mark that identifies a character","titleCN":"用来辨认人物的标记","definition":"in fiction and drama, a repeated habit used to make a figure recognisable","definitionCN":"在小说与戏剧中，用来让人物可被辨认的重复习惯","example":"The writer gives each sister one personality trait and never adds a second.","exampleCN":"作者只给每位姐妹一项人格特质，从不加第二项。","why":"storytelling borrows the research unit because one clear trait is enough to make a figure stick.","whyCN":"叙事借用了研究的单位，因为一项清晰的特质就足以让人物留得住。"}],"etymology":{"intro":{"en":"The phrase joins personality, from Latin persona 'mask', with trait, from French and Latin tractus 'a drawing, a line'. It is a modern technical label of psychology and dates as a fixed phrase to the twentieth century. Dates are approximate.","cn":"这个词组把出自拉丁 persona「面具」的 personality，与出自法语及拉丁 tractus「划线、拉出」的 trait 接在一起。它是心理学的近代专业标签，作为固定说法大致定形于 20 世纪。年代均为约数。"},"items":[{"era":"LATIN PERSONA","en":"Persona meant a mask worn on stage and then the role itself; its deeper origin is uncertain, and one hypothesis links it to an Etruscan word.","cn":"persona 指舞台上戴的面具，后指角色本身；其更深来源不确定，有一种假说认为它来自某种伊特鲁里亚词。"},{"era":"LATIN TRACTUS","en":"Tractus meant 'a drawing, a line, a pull', from trahere 'to draw'. French turned it into a word for a line or feature of the face or character.","cn":"tractus 意为「划线、拉、牵引」，出自 trahere「拉」。法语把它变成指面部或性格的一条线、一个特征。"},{"era":"ENGLISH TRAIT","en":"English borrowed trait in the sixteenth century for a stroke of the pen and then for a feature of body or mind.","cn":"英语在 16 世纪借入 trait，先指一笔，后指身体或心智上的一个特征。"},{"era":"PSYCHOLOGY'S UNIT","en":"Nineteenth-century psychology needed countable units of character, and the phrase settled the noun trait into that role.","cn":"19 世纪心理学需要可计数的性格单位，这个词组把 trait 固定在这个角色上。"},{"era":"FIVE-FACTOR ERA","en":"Twentieth-century factor analysis reduced many traits to five broad dimensions, and the phrase became standard in reports and tests.","cn":"20 世纪的因素分析把许多特质压缩成五个宽维度，这个词组遂成为报告与测验里的标准说法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact date at which the two words began to be used as a fixed phrase is not recorded.","cn":"来源不确定：这两个词开始作为固定说法使用，确切年代没有记录。"}]},"similar":{"note":{"en":"Group one holds phrases that look similar and are often swapped; group two holds the neighbouring terms of trait research.","cn":"第一组是字形相近、常被互换的词组；第二组是特质研究里的邻近术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"character trait","ipa":"/ˈkærəktə treɪt/","tag":"moral flavour","definition":"Nearly the same unit, but it leans toward moral qualities such as honesty, while this phrase leans toward measurable tendencies.","definitionCN":"几乎同一个单位，但它偏向诚实一类道德品质，而本词组偏向可测量的倾向。"},{"word":"personality type","ipa":"/ˌpɜːsəˈnæləti taɪp/","tag":"a class, not a thread","definition":"Names a category a person belongs to, not a single tendency, so the two answer different questions.","definitionCN":"命名一个人所属的类别，而不是一条倾向，因此两者回答不同的问题。"},{"word":"personal trait","ipa":"/ˈpɜːsənl treɪt/","tag":"looser wording","definition":"A looser phrase that can cover habits and tastes; the technical form is this one.","definitionCN":"较松的说法，可涵盖习惯与口味；专业形式是本词组。"},{"word":"trait","ipa":"/treɪt/","tag":"the unit alone","definition":"The bare noun can belong to a species, a face or a character; adding personality restricts it to the human pattern.","definitionCN":"单用的名词可指物种、面容或人物的特征；加上 personality 就把范围限定为人的格局。"}]},{"heading":"NEAR MEANING","entries":[{"word":"temperament","ipa":"/ˈtemprəmənt/","tag":"the inborn setting","definition":"The native part of the pattern; traits may be inherited but are still measured one by one.","definitionCN":"格局中天生的那部分；特质可以遗传，但仍是一条条被测量。"},{"word":"habit","ipa":"/ˈhæbɪt/","tag":"learned and repeatable","definition":"A repeated behaviour that may be learned; a trait is the disposition said to lie behind such repetitions.","definitionCN":"可习得的重复行为；特质是被认为藏在这些重复背后的倾向。"},{"word":"quality","ipa":"/ˈkwɒləti/","tag":"plain and broad","definition":"The everyday word for a feature of a person or thing, with no claim about stability or measurement.","definitionCN":"指人或物某一特征的日常词，不主张稳定性或可测量性。"},{"word":"attribute","ipa":"/ˈætrɪbjuːt/","tag":"assigned from outside","definition":"A feature assigned to someone, often by an observer; it carries less weight than a trait.","definitionCN":"由他人赋予某人的特征，常出自观察者；分量不如 trait。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"First word from Latin for a mask, second word from Latin for a drawn line: a line on the mask.","cn":"第一个词出自拉丁的「面具」，第二个词出自拉丁的「划出的线」：面具上的一道线。"},{"en":"The family runs trait, personality, personality trait, character trait, trait theory.","cn":"同族说法包括 trait、personality、personality trait、character trait、trait theory。"},{"en":"Fixed phrases mark the uses: the Big Five personality traits, measure personality traits, inherited personality trait.","cn":"固定搭配标出用法：大五人格特质、测量人格特质、遗传的人格特质。"},{"en":"Research distinguishes a trait from a type: one is a thread, the other is a box.","cn":"研究区分「特质」与「类型」：一个是线，一个是盒子。"},{"en":"The phrase is countable, which is why reports speak of twelve traits rather than one character.","cn":"这个词组可数，因此报告会说十二项特质，而不是一个性格。"}],"abstract":[{"en":"Picture a magnified cloth where a single thread can be pulled out and named.","cn":"想象一块放大的织物，能抽出一根线并为它命名。"},{"en":"Picture a row of dots on a chart that only becomes a line when enough people answer.","cn":"想象图表上一排点，只有足够多人作答之后才连成一条线。"},{"en":"Picture the same key opening one door and jamming another.","cn":"想象同一把钥匙开了一扇门，却卡住了另一扇。"}]},"examples":[{"en":"Curiosity is the personality trait that predicts the widest range of outcomes.","cn":"好奇心是能预测最多种结果的一项人格特质。"},{"en":"The study compares personality traits across three generations.","cn":"这项研究比较了三代之间的人格特质。"},{"en":"Punctuality is less a personality trait than a local custom.","cn":"守时比起人格特质，更像是当地的风俗。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"personality（人格）+ trait（特征）——人格上的那一条特征 → 人格特质","word":"personality trait"},"root":"由 personality（拉丁 persona「面具」+ 抽象名词后缀）与 trait（拉丁 tractus「划线、拉出」）合成；作为固定说法属近代心理学专业标签。","sensesIntro":{"en":"Eight senses follow one movement: a single thread is pulled out of a whole pattern, and that thread is then read as a component, as an inheritance, as a dimension, as a label, as a form entry, as a value judgement and finally as a storytelling mark.","cn":"八个义项沿一个动作展开：从整块格局中抽出一根线，这根线依次被读作构件、遗传、维度、标签、表格栏目、价值判断，最后是叙事标记。"},"semanticMap":{"core":{"en":"CORE IMAGE: a magnified cloth where the whole weave is invisible until one thread is pulled out and named.","cn":"核心意象：一块放大的织物，整片织法看不见，直到抽出一根线并为它命名。"},"chain":["ONE THREAD PULLED","A COMPONENT","INHERITED","A DIMENSION","RECORDED AND JUDGED","A STORY MARK"],"branches":[{"senses":"01 · 02","en":"THE THREAD AND THE WEAVE: the measured tendency first, then its job as a part of the larger pattern.","cn":"线与织法：先是可测量的倾向，再是它作为更大格局之零件的作用。"},{"senses":"03","en":"WHERE THE THREAD COMES FROM: inheritance is the research answer to why the same line keeps appearing.","cn":"线从哪里来：遗传是研究给出的答案，解释了同一条线为何反复出现。"},{"senses":"04","en":"THE THREAD AS A DIMENSION: factor analysis folds many threads into five broad bands.","cn":"线作为维度：因素分析把许多线折成五条宽带。"},{"senses":"05 · 06","en":"THE THREAD READ AND RECORDED: an observer's label, then a scored row on an assessment form.","cn":"线被解读与被记录：先是观察者的标签，再是测评表上被打分的一行。"},{"senses":"07 · 08","en":"ONE THREAD, TWO JUDGEMENTS: praised as persistence or blamed as stubbornness, and used by writers to make a figure stick.","cn":"同一根线，两种判断：被赞为坚持或被责为固执，也被作家用来让人物留得住。"}]},"affixes":{"intro":{"en":"Two Latin-derived words joined into a technical phrase; each half still reads by its own pieces.","cn":"两个来自拉丁的词拼成一个专业词组，每一半仍可按自己的成分拆读。"},"latinIntro":{"en":"Latin persona 'mask' supplies the first half through its abstract noun; Latin tractus 'a drawing' supplies the second through French.","cn":"拉丁 persona「面具」经其抽象名词提供前半；拉丁 tractus「划线」经法语提供后半。"},"items":[{"word":"persona","structure":"persona (Latin noun, 'mask, role')","meaning":"mask; character","meaningCN":"面具；角色","example":"The first half goes back to the stage mask.","exampleCN":"前半上溯到舞台上的面具。"},{"word":"-ity","structure":"-itas (Latin abstract noun suffix)","meaning":"the quality of being X","meaningCN":"具有某种性质","example":"It makes the first half abstract.","exampleCN":"它让前半变成抽象名词。"},{"word":"personality","structure":"personalis + -itas","meaning":"the whole pattern of a person","meaningCN":"一个人整体的性格格局","example":"It supplies the larger frame.","exampleCN":"它提供较大的框架。"},{"word":"tractus","structure":"trahere + -tus (Latin noun of action)","meaning":"a drawing, a line, a pull","meaningCN":"划线；牵引","example":"The second half began as a stroke of the pen.","exampleCN":"后半最初指一笔。"},{"word":"trait","structure":"tractus, through French trait","meaning":"a line or feature","meaningCN":"一条线；一个特征","example":"Neatness is one trait among many.","exampleCN":"整洁是众多特征之一。"},{"word":"personality trait","structure":"personality + trait","meaning":"one stable measurable tendency","meaningCN":"一条稳定可测的倾向","example":"One personality trait stood out.","exampleCN":"有一项人格特质很突出。"},{"word":"character trait","structure":"character + trait","meaning":"a feature of moral make-up","meaningCN":"品性构成中的一项特征","example":"Honesty is a character trait.","exampleCN":"诚实是一项性格特征。"},{"word":"trait theory","structure":"trait + theory","meaning":"the approach that explains people by stable traits","meaningCN":"用稳定特质解释人的理论取向","example":"Trait theory underlies most questionnaires.","exampleCN":"特质理论是多数问卷的基础。"}],"latinEntries":[{"word":"persona","structure":"persona, personae (first declension noun)","meaning":"mask, role","meaningCN":"面具；角色"},{"word":"personalitas","structure":"personalis + -itas (noun)","meaning":"the quality of being a person","meaningCN":"作为个人的性质"},{"word":"tractus","structure":"trahere + -tus (fourth declension noun)","meaning":"a drawing, a line, a pull","meaningCN":"划线；牵引"}],"derivatives":[{"word":"trait","pos":"n.","zh":"特征；特质"},{"word":"personality","pos":"n.","zh":"人格；个性"},{"word":"character trait","pos":"n. phrase","zh":"性格特征"},{"word":"trait theory","pos":"n. phrase","zh":"特质理论"}]}},{"word":"trait","ipa_uk":"/treɪt/","ipa_us":"/treɪt/","definition_zh":"特征；特质；性状；一点、一丝（某性质）；一笔（旧义）","definition_en":"a distinguishing quality of a person, group or living thing, or a slight amount of something","core_image":"一张脸上只用一笔勾出的那道线，远看是轮廓，近看才知道是标记","scene":"同窝的幼犬里，只有一只从头到尾都不往人跟前凑，训导员在记录表上给它画了一道。That single trait decided which puppy went to the quiet household.","sceneCN":"这里 trait 指「一个可辨认、相对稳定的特征」（第 1 个义项：性格或性状上的特征）；句意是这一个特征决定了哪只幼犬被送去安静的人家。图中可辨识物件：记录表上的一道笔划、蜷在角落的幼犬、伸手的训导员。","pos":[{"tag":"n.","zh":"特征；特质；性状"},{"tag":"n. (archaic/literary)","zh":"一点；一丝；一笔"}],"collocations":[{"phrase":"a genetic trait","zh":"一种遗传性状"},{"phrase":"a personality trait","zh":"一项人格特质"},{"phrase":"a common trait","zh":"共同特征"},{"phrase":"a trait of","zh":"……的一点（一丝）"},{"phrase":"inherited trait","zh":"遗传特征"},{"phrase":"dominant trait","zh":"显性性状；主导特征"}],"forms":[{"label":"复数","form":"traits"},{"label":"形容词形式（少用）","form":"trait-like"},{"label":"复合名词","form":"trait theory"},{"label":"近义名词","form":"characteristic"},{"label":"近义名词","form":"attribute"}],"derivatives":[{"word":"traits","pos":"n.","zh":"特征（复数）"},{"word":"characteristic","pos":"n./adj.","zh":"特性 / 典型的"},{"word":"attribute","pos":"n./v.","zh":"属性 / 把……归于"},{"word":"trait theory","pos":"n. phrase","zh":"特质理论"}],"senses":[{"no":"01","title":"A distinguishing quality","titleCN":"一个可辨认的区别性品质","definition":"a stable quality that marks a person out from others","definitionCN":"使人区别于他人的一项稳定品质","example":"That single trait decided which puppy went to the quiet household.","exampleCN":"这一个特征决定了哪只幼犬被送去安静的人家。","why":"the word began as a drawn line, and a line is exactly what marks one thing off from another.","whyCN":"这个词最初指画出的一条线，而线正是把一物与另一物分开的标记。"},{"no":"02","title":"A feature of a thing","titleCN":"事物的一项显著属性","definition":"a noticeable property of an object, system or style","definitionCN":"物体、制度或风格上明显可见的一项属性","example":"The script's most useful trait is that it can be read upside down.","exampleCN":"这种文字最有用的一点是倒着也能读。","why":"the line can be drawn on anything, so the word easily leaves people and attaches to objects.","whyCN":"线可以画在任何东西上，因此这个词很容易离开人，附到物上。"},{"no":"03","title":"A slight amount","titleCN":"一点、一丝","definition":"a small trace of a quality, in older or literary usage","definitionCN":"某种性质的一点点痕迹，属较旧或文学化的用法","example":"There was a trait of irony in the old man's courtesy.","exampleCN":"老人的礼貌里带一丝讥讽。","why":"a single drawn stroke is also the smallest visible amount, which is how the word came to mean a trace.","whyCN":"单独画出的一笔也是最小的可见量，这个词由此有了「一丝」的意思。"},{"no":"04","title":"A biological character","titleCN":"生物学上的性状","definition":"an inherited characteristic of an organism, such as eye colour","definitionCN":"生物体遗传而来的特征，如眼睛颜色","example":"Sickle cell is a trait that protects against one kind of malaria.","exampleCN":"镰状细胞是一种能抵抗某类疟疾的性状。","why":"genetics needed a countable unit and borrowed the same word, keeping the idea of a marked feature.","whyCN":"遗传学需要一个可计数的单位，借用了同一个词，保留了「被标出的特征」这一观念。"},{"no":"05","title":"A recurring way of acting","titleCN":"反复出现的行为方式","definition":"a habit of behaviour treated as evidence of something deeper","definitionCN":"被当作更深层之证据的行为习惯","example":"Interrupting is a trait his colleagues have learned to expect.","exampleCN":"打断别人是他同事已学会预期的一个特点。","why":"one act is an event, but repetition turns it into a trait, which is why observers wait before naming one.","whyCN":"一次行为是一个事件，重复才把它变成特质，因此观察者会等一等再命名。"},{"no":"06","title":"Something a group shares","titleCN":"一个群体共有的东西","definition":"a feature common to a culture, generation or kind","definitionCN":"文化、世代或类别中共同具有的特征","example":"Suspicion of strangers is a trait of the region rather than of the family.","exampleCN":"对外人的戒心是这个地区的特征，而不是这一家的。","why":"the same mark can be drawn around many people at once, which lets the word describe a collective.","whyCN":"同一个标记可以一次画在一群人周围，这就让这个词能描述集体。"},{"no":"07","title":"A stroke of the pen","titleCN":"笔下的一笔","definition":"the original sense: a single line drawn by hand","definitionCN":"本义：手画出的一条线","example":"The mapmaker added one trait and the border changed.","exampleCN":"绘图者添了一笔，边界就变了。","why":"this is the literal sense from which all the others radiate, and it survives in careful historical writing.","whyCN":"这是所有其他义项由之辐射的字面义，在严谨的历史写作中仍然存留。"},{"no":"08","title":"A line of the face","titleCN":"脸上的一道线","definition":"in literary description, a feature of the face or outline","definitionCN":"在文学描写中指面部或轮廓上的一道线","example":"The portrait catches one trait of the mouth and nothing else.","exampleCN":"这幅肖像只抓住了嘴部的一道线，别的都没有。","why":"a face is read line by line, so the oldest drawing sense survives most naturally in portraits.","whyCN":"脸是一道道线读出来的，因此最古老的「划线」义在肖像描写里保存得最自然。"}],"etymology":{"intro":{"en":"Trait comes from French trait, from Latin tractus 'a drawing, a line, a pull', from trahere 'to draw, drag'. English borrowed it in the sixteenth century; the psychological sense is much later. Dates are approximate.","cn":"trait 来自法语 trait，上溯拉丁 tractus「划线、牵引」，出自 trahere「拉、拖」。英语在 16 世纪借入，心理学义则晚得多。年代均为约数。"},"items":[{"era":"LATIN TRAHERE","en":"Trahere meant 'to draw, drag, pull'. It is the source of tractor, traction, attract and contract, and its deeper origin is not established.","cn":"trahere 意为「拉、拖、牵引」。它是 tractor、traction、attract、contract 的来源，更深来源未得到证明。"},{"era":"LATIN TRACTUS","en":"The noun meant 'a drawing, a line, a course, a pull'. The sense of a line drawn by the hand is the seed of the later meanings.","cn":"这个名词意为「划线、路线、牵引」。手画出的一条线这一义，是后来各义的种子。"},{"era":"FRENCH TRAIT","en":"French trait kept the sense of a stroke or line and extended it to a feature of the face and then of character.","cn":"法语 trait 保留了「一笔、一线」的意思，并把它延伸到面部特征，再延伸到性格特征。"},{"era":"ENGLISH BORROWING","en":"English took the word in the sixteenth century, first for a stroke of the pen and soon for a feature of body or mind.","cn":"英语在 16 世纪借入这个词，先指一笔，很快指身体或心智上的一个特征。"},{"era":"PSYCHOLOGY AND GENETICS","en":"Nineteenth- and twentieth-century psychology and genetics made trait a countable unit, so that people and organisms could be described feature by feature.","cn":"19 与 20 世纪的心理学与遗传学把 trait 变成可计数的单位，人与生物于是可以一条条特征来描述。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of trahere remains a reconstruction, and the first English use for character is not precisely dated.","cn":"来源不确定：trahere 在拉丁语之前的来源属重构形式，英语中首次用于「性格特征」义的年代也未精确。"}]},"similar":{"note":{"en":"Group one holds look-alikes that belong to different histories; group two holds the near synonyms with different weight.","cn":"第一组是字形相近却来历不同的词；第二组是分量不同的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"traitor","ipa":"/ˈtreɪtə/","tag":"same opening, different root","definition":"From Latin tradere 'to hand over' through French: a person who hands others over. It shares no root with this word despite the spelling.","definitionCN":"经法语出自拉丁 tradere「交出」：指把别人交出去的人。尽管拼写相近，与本词不同源。"},{"word":"tract","ipa":"/trækt/","tag":"same root, a stretch","definition":"Same Latin noun, but English kept it for a stretch of land or a short pamphlet, a drawn-out area rather than a line.","definitionCN":"同一个拉丁名词，但英语把它留作一片土地或一本小册子，指拉展开的区域而非一条线。"},{"word":"trace","ipa":"/treɪs/","tag":"same root, a mark left","definition":"From the same verb of drawing: the mark left behind, which overlaps with the sense of a slight amount.","definitionCN":"同出那个「拉、画」的动词：留下的痕迹，与「一丝」义重叠。"},{"word":"train","ipa":"/treɪn/","tag":"same root, drawn along","definition":"From the same verb through French: something drawn along in a line, later a line of carriages.","definitionCN":"经法语同出那个动词：被拉成一列的东西，后指一列车厢。"}]},{"heading":"NEAR MEANING","entries":[{"word":"characteristic","ipa":"/ˌkærəktəˈrɪstɪk/","tag":"typical mark","definition":"A feature that typifies a group or thing; it is broader and less technical than trait.","definitionCN":"使一个群体或事物显出典型性的特征；比 trait 更宽、更少专业味。"},{"word":"attribute","ipa":"/ˈætrɪbjuːt/","tag":"ascribed quality","definition":"A quality ascribed to someone or something, often from outside; traits are meant to be internal and stable.","definitionCN":"被归到某人某物名下的品质，常由外界赋予；特质则被设定为内在而稳定。"},{"word":"quality","ipa":"/ˈkwɒləti/","tag":"plain word","definition":"The ordinary word for any feature, without the claim of stability that trait carries.","definitionCN":"指任何特征的普通词，不带 trait 那种稳定性的主张。"},{"word":"habit","ipa":"/ˈhæbɪt/","tag":"learned repetition","definition":"A behaviour repeated until it is automatic; it can be changed, while a trait is presented as part of the make-up.","definitionCN":"重复到自动化的行为；习惯可以改，而特质被呈现为构成的一部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The root verb means 'to draw', so a trait is literally a line drawn to mark something.","cn":"词根动词意为「拉、画」，因此 trait 字面上就是为标记某物而画的一条线。"},{"en":"The family runs trait, traits, trait theory, personality trait, character trait.","cn":"同族说法包括 trait、traits、trait theory、personality trait、character trait。"},{"en":"Fixed phrases mark the uses: a genetic trait, a personality trait, a common trait.","cn":"固定搭配标出用法：遗传性状、人格特质、共同特征。"},{"en":"The same Latin noun also gave tract, trace and train, each keeping a different part of the image.","cn":"同一个拉丁名词还给了 tract、trace、train，各保留了意象的不同部分。"},{"en":"Genetics says dominant and recessive traits, which shows the countable unit clearly.","cn":"遗传学说显性与隐性性状，这把可计数单位记得很清。"}],"abstract":[{"en":"Picture a single pencil line on a face, enough to make it recognisable.","cn":"想象脸上一道铅笔线，就足以让人认出。"},{"en":"Picture a map where one added stroke redraws a border.","cn":"想象地图上添的一笔改变了边界。"},{"en":"Picture a thread pulled out of cloth that still carries the shape of the weave.","cn":"想象从布里抽出的一根线，仍带着织法的形状。"}]},"examples":[{"en":"Patience is the one trait the job actually requires.","cn":"这份工作真正要求的唯一特质是耐心。"},{"en":"The species shares a trait that lets it survive dry seasons.","cn":"这个物种共有一种能让它熬过旱季的性状。"},{"en":"There was not a trait of irony in her reply.","cn":"她的回答里没有一丝讥讽。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"trait 读如「垂特」——特意垂下的一笔 → 特征、特质","word":"trait"},"root":"法语 trait，上溯拉丁 tractus「划线、牵引」，出自 trahere「拉、拖」；与表「背叛者」的词形近而不同源。","sensesIntro":{"en":"Eight senses follow one movement: a line is drawn by hand, and that line is then read as a distinguishing quality, as a property of things, as a slight trace, as a biological character, as repeated behaviour, as a group's mark and finally as a line of the face.","cn":"八个义项沿一个动作展开：手画出一条线，这条线依次被读作区别性品质、事物的属性、一丝痕迹、生物性状、重复行为、群体的标记，最后是脸上的一道线。"},"semanticMap":{"core":{"en":"CORE IMAGE: one pencil line drawn across a face, far off a mere outline, close up a deliberate mark.","cn":"核心意象：脸上画出的一道铅笔线，远看只是轮廓，近看才知道是刻意的标记。"},"chain":["A LINE DRAWN","WHAT THE LINE MARKS","THE SMALLEST TRACE","A BIOLOGICAL MARK","A REPEATED MARK","A LINE OF THE FACE"],"branches":[{"senses":"01 · 02","en":"THE MARK AND ITS CARRIER: first a quality that separates people, then the same mark drawn on an object.","cn":"标记与承载体：先是把人与人分开的品质，再是画在物件上的同一标记。"},{"senses":"03","en":"THE THINNEST LINE: one stroke is also the smallest visible amount, which is how the word came to mean a trace.","cn":"最细的一条线：一笔也是最小的可见量，这个词由此有了「一丝」。"},{"senses":"04","en":"THE MARK MADE INHERITABLE: genetics borrows the unit and ties the mark to a body.","cn":"标记变成可遗传之物：遗传学借走这个单位，把标记绑到身体上。"},{"senses":"05 · 06","en":"REPETITION AND SCALE: the same mark is inferred from repeated acts, or drawn around a whole group.","cn":"重复与尺度：同一标记或从重复行为推断，或被画在整个群体周围。"},{"senses":"07 · 08","en":"BACK TO THE HAND: the literal stroke survives in maps and portraits, where the drawn line is the thing itself.","cn":"回到那只手：字面的一笔活在地图与肖像里，那里画出的线就是事物本身。"}]},"affixes":{"intro":{"en":"A Latin participle used as a noun, carried through French, with one family of words keeping the drawing sense and another keeping the pulling sense.","cn":"一个拉丁分词被当作名词使用，经法语传来；词族里一部分保留「画线」义，另一部分保留「拉」义。"},"latinIntro":{"en":"Latin trahere 'to draw' gives tract, trace, train, traction and contract; the noun tractus gives the line sense that French turned into this word.","cn":"拉丁 trahere「拉」衍生 tract、trace、train、traction、contract；名词 tractus 则提供「线」义，法语由此造出本词。"},"items":[{"word":"trahere","structure":"trahere (Latin verb, third conjugation)","meaning":"to draw, drag, pull","meaningCN":"拉；拖；牵引","example":"The verb supplies the act of drawing a line.","exampleCN":"这个动词提供「画线」的动作。"},{"word":"tractus","structure":"trahere + -tus (fourth declension noun)","meaning":"a drawing, a line, a pull","meaningCN":"划线；一条线；牵引","example":"The noun supplies the visible result.","exampleCN":"这个名词提供可见的结果。"},{"word":"trait","structure":"tractus, through French trait","meaning":"a line; a feature","meaningCN":"一条线；一个特征","example":"Interrupting is a trait his colleagues expect.","exampleCN":"打断别人是他同事预期的特点。"},{"word":"traits","structure":"trait + plural -s","meaning":"features taken together","meaningCN":"多个特征合起来看","example":"The study rates twelve traits.","exampleCN":"这项研究评估十二项特征。"},{"word":"trait theory","structure":"trait + theory","meaning":"the approach that explains people by stable traits","meaningCN":"用稳定特质解释人的理论","example":"Trait theory underlies the questionnaire.","exampleCN":"特质理论是这份问卷的基础。"},{"word":"tract","structure":"tractus, kept for a stretch","meaning":"an area or a short essay","meaningCN":"一片区域；短论","example":"A tract of forest was set aside.","exampleCN":"一片林地被划了出来。"},{"word":"trace","structure":"tractus, through French trace","meaning":"a mark left behind","meaningCN":"留下的痕迹","example":"No trace of the letter remained.","exampleCN":"那封信没有留下任何痕迹。"},{"word":"train","structure":"trahere, through French trains","meaning":"that which is drawn along","meaningCN":"被拉成一列之物","example":"The idea is drawn out into a line.","exampleCN":"这个意象被拉成一条线。"}],"latinEntries":[{"word":"trahere","structure":"trahere, traho, traxi, tractum (verb)","meaning":"to draw, drag, pull","meaningCN":"拉；拖；牵引"},{"word":"tractus","structure":"trahere + -tus (fourth declension noun)","meaning":"a drawing, a line, a course","meaningCN":"划线；一条线；路线"}],"derivatives":[{"word":"characteristic","pos":"n./adj.","zh":"特性 / 典型的"},{"word":"attribute","pos":"n./v.","zh":"属性 / 归因于"},{"word":"trait theory","pos":"n. phrase","zh":"特质理论"},{"word":"traits","pos":"n.","zh":"特征（复数）"}]}},{"word":"character","ipa_uk":"/ˈkærəktə/","ipa_us":"/ˈkærəktər/","definition_zh":"性格；品格；骨气；角色；人物；字符；（地方或事物的）特色；名声","definition_en":"the moral and mental make-up of a person, or a person in a story, or a written symbol, or the distinctive quality of something","core_image":"一枚印章按进湿泥，泥上留下的深浅纹路，同时是记号，也是这枚章的脾气","scene":"老街上新开了连锁店，招牌很亮，可街坊都说这条街的味道变了，说不清变在哪里。The street lost its character long before the shop signs changed.","sceneCN":"这里 character 指「一个地方难以言说却可辨认的总体特色」（第 1 个义项：可辨认的特色与性格）；句意为这条街在招牌更换之前很久就已经失去了自己的味道。图中可辨识物件：旧砖墙、亮招牌、站在门口的街坊。","pos":[{"tag":"n. (moral nature)","zh":"性格；品格；骨气"},{"tag":"n. (role)","zh":"角色；人物（小说、戏剧、电影）"},{"tag":"n. (written symbol)","zh":"字符；文字符号"},{"tag":"n. (distinctive quality)","zh":"特色；性质；名声"}],"collocations":[{"phrase":"strength of character","zh":"骨气；品格的力量"},{"phrase":"in character","zh":"符合性格；合乎本性"},{"phrase":"out of character","zh":"不符合性格；反常"},{"phrase":"main character","zh":"主角"},{"phrase":"Chinese character","zh":"汉字"},{"phrase":"the character of a place","zh":"一个地方的特色"}],"forms":[{"label":"复数","form":"characters"},{"label":"形容词形式","form":"characteristic"},{"label":"动词形式","form":"characterize"},{"label":"名词形式","form":"characterization"},{"label":"否定形容词","form":"characterless"}],"derivatives":[{"word":"characteristic","pos":"adj./n.","zh":"典型的；特性"},{"word":"characterize","pos":"v.","zh":"刻画；以……为特征"},{"word":"characterization","pos":"n.","zh":"人物刻画；特征描述"},{"word":"characterless","pos":"adj.","zh":"无特色的"},{"word":"characteristically","pos":"adv.","zh":"典型地；一贯地"}],"senses":[{"no":"01","title":"The make-up of a person","titleCN":"一个人的性格构成","definition":"the settled combination of qualities that decides how a person acts","definitionCN":"决定一个人如何行事的稳定品质组合","example":"The street lost its character long before the shop signs changed.","exampleCN":"这条街在招牌更换之前很久就失去了自己的味道。","why":"the root means an engraved mark, so character is the stamp a person carries and leaves on everything.","whyCN":"词根意为刻下的印记，因此 character 是一个人随身带着、并留在一切事物上的那枚章。"},{"no":"02","title":"Moral fibre","titleCN":"道德上的骨气","definition":"the strength of a person's moral principles, especially under pressure","definitionCN":"一个人的道德原则在压力下的强度","example":"It took character to admit the mistake in front of the whole team.","exampleCN":"在全队面前承认错误需要骨气。","why":"an engraved mark is hard to erase, and the word came to mean what does not wear away under strain.","whyCN":"刻下的印记难以抹去，这个词于是指在压力之下不会磨掉的东西。"},{"no":"03","title":"A figure in a story","titleCN":"故事里的人物","definition":"a person represented in a novel, play or film","definitionCN":"小说、戏剧或电影中被表现的人物","example":"The main character never explains why she leaves.","exampleCN":"主角从未解释她为什么离开。","why":"a stage mask marked the role being played, and the word kept that sense for fictional persons.","whyCN":"舞台面具标记着所演的角色，这个词为虚构人物保留了那一义。"},{"no":"04","title":"A written symbol","titleCN":"书写的符号","definition":"a letter, sign or code unit used in writing or printing","definitionCN":"书写或印刷所用的字母、符号或编码单位","example":"The password needs at least one capital character.","exampleCN":"密码至少需要一个大小写字母字符。","why":"an engraved mark is literally a written sign, and computing merely made that sense countable.","whyCN":"刻下的印记本就是书写符号，计算机只是把这个义项变成可计数的。"},{"no":"05","title":"The distinctive quality of a thing","titleCN":"事物可辨认的独特性质","definition":"the quality that makes a place, period or object recognisably itself","definitionCN":"使一个地方、时期或物件能被认作它自身的那种性质","example":"The market keeps the character of a village fair.","exampleCN":"这个市场保留着乡村集市的味道。","why":"the stamp can be pressed into anything, so the word travels easily from people to places.","whyCN":"印章可以按在任何东西上，因此这个词很容易从人移到地方。"},{"no":"06","title":"Reputation and moral standing","titleCN":"名声与品行评价","definition":"the standing a person has in others' eyes, especially for honesty","definitionCN":"一个人在他人眼中的地位，尤指在诚实方面的评价","example":"The witness was of good character, the court was told.","exampleCN":"法庭被告知，这名证人品行良好。","why":"what is engraved on a person is also what is read off them by others, hence the public sense.","whyCN":"刻在一个人身上的东西，也是别人从他身上读出的东西，公共义由此而来。"},{"no":"07","title":"An odd, vivid person","titleCN":"古怪而有味道的人","definition":"a person whose habits are unusual enough to be memorable and entertaining","definitionCN":"习惯古怪到让人记得住、也觉得有趣的人","example":"The old boatman was a character and knew it.","exampleCN":"那位老船夫是个活宝，他自己也知道。","why":"the stamp is deep enough to be noticed, and English praises whatever is strongly marked as interesting.","whyCN":"印记深到能被注意到，而英语会把一切被强烈标记的东西当成有趣的。"},{"no":"08","title":"A feature of a kind","titleCN":"某一类事物的特性","definition":"a distinguishing property of a species, material or system","definitionCN":"物种、材料或系统身上可区分的性质","example":"Hardness is a character of the mineral, not of the soil.","exampleCN":"硬度是这种矿物的特性，而不是土壤的。","why":"the technical sense keeps the plain meaning of a mark by which a kind is known.","whyCN":"专业义保留了「凭以辨认某类的标记」这一朴素意思。"}],"etymology":{"intro":{"en":"Character comes from Greek kharakter 'an engraved mark, a stamp', from kharassein 'to engrave, scratch', through Latin and then French. English took it in the fourteenth century. Dates are approximate.","cn":"character 来自希腊 kharakter「刻下的印记、印章」，出自 kharassein「刻、划」，经拉丁与法语传入。英语在 14 世纪借入。年代均为约数。"},"items":[{"era":"GREEK KHARASSEIN","en":"Kharassein meant 'to engrave, scratch, cut into a surface'. Its deeper origin is not established; suggestions linking it to other roots are hypotheses, not demonstrated derivations.","cn":"kharassein 意为「刻、划、切进表面」。其更深来源未得到证明；把它与其他词根联系的种种说法只是假说，并非已证实的派生。"},{"era":"GREEK KHARAKTER","en":"The noun meant the mark cut into metal or stone, then any stamped sign, then the whole set of traits that a person or thing is stamped with.","cn":"这个名词指切进金属或石头的记号，后指任何压印的符号，再指一个人或事物被刻上的全部特征。"},{"era":"LATIN AND FRENCH","en":"Latin character kept both the written sign and the moral sense; French carried it into English in the fourteenth century.","cn":"拉丁 character 既保留书写符号义，也保留道德义；法语在 14 世纪把它带进英语。"},{"era":"PRINTING AND DRAMA","en":"Printing made the word mean a single letter or symbol, while the stage made it mean a role, so two very different senses grew from one image.","cn":"印刷让它指单个字母或符号，舞台让它指角色，于是同一个意象长出两个很不相同的义项。"},{"era":"MODERN USE","en":"Novels, psychology and computing each took a share: fictional persons, personality description and encoded symbols.","cn":"小说、心理学与计算机各取一份：虚构人物、性格描述与编码符号。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Greek origin of the root is a reconstruction, and no single date is agreed for the moral sense in English.","cn":"来源不确定：词根在希腊语之前的来源属重构形式，道德义在英语中出现的确切年代也没有公认结论。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close but come from other roots; group two holds the neighbouring words for personal make-up.","cn":"第一组是字形或读音接近、却出自别的词根的词；第二组是表示个人构成的邻近词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"caricature","ipa":"/ˈkærɪkətʃə/","tag":"different root","definition":"From Italian caricare 'to load, exaggerate', not from the Greek word for engraving: a drawing that exaggerates features.","definitionCN":"出自意大利语「装载、夸张」，而非那个希腊「刻」词：指夸张特征的画。"},{"word":"characteristic","ipa":"/ˌkærəktəˈrɪstɪk/","tag":"derived adjective","definition":"Built on this word: it names a feature that typifies something, and as an adjective means 'typical of'.","definitionCN":"由本词构成：作名词指使某物显出典型性的特征，作形容词指「为……所特有」。"},{"word":"characterize","ipa":"/ˈkærəktəraɪz/","tag":"the verb","definition":"To describe the distinguishing marks of something, or to be such a mark.","definitionCN":"描述某物的区别性标记，或本身成为这样的标记。"},{"word":"characterless","ipa":"/ˈkærəktələs/","tag":"without a stamp","definition":"Its negative: lacking any distinctive quality, said of places or prose that leave no impression.","definitionCN":"它的否定：缺少任何可辨性质，用于留不下印象的地方或文字。"}]},{"heading":"NEAR MEANING","entries":[{"word":"personality","ipa":"/ˌpɜːsəˈnæləti/","tag":"pattern, not judgement","definition":"The measurable pattern of qualities; it does not carry the moral judgement that character does.","definitionCN":"可测量的品质格局；不带 character 那种道德评判。"},{"word":"nature","ipa":"/ˈneɪtʃə/","tag":"what one is born like","definition":"The plain word for inborn disposition, without the sense of moral fibre or of a written sign.","definitionCN":"指天生性情的普通词，不含道德骨气或书写符号的意思。"},{"word":"role","ipa":"/rəʊl/","tag":"part only","definition":"The part played by an actor or held by a person; it covers the drama sense but none of the others.","definitionCN":"指演员扮演或某人承担的职务；只覆盖戏剧义，其余义一概没有。"},{"word":"symbol","ipa":"/ˈsɪmbl/","tag":"sign only","definition":"A sign that stands for something else; it covers the writing sense loosely but not the moral one.","definitionCN":"代表他物的符号；大致覆盖书写义，但不含道德义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Greek root means 'to engrave', so character is a mark cut in and hard to remove.","cn":"希腊词根意为「刻」，因此 character 是刻进去、难以抹掉的印记。"},{"en":"The family runs character, characteristic, characterize, characterization, characterless.","cn":"同族词包括 character、characteristic、characterize、characterization、characterless。"},{"en":"Fixed phrases mark the uses: strength of character, in character, out of character, main character.","cn":"固定搭配标出用法：骨气、符合本性、反常、主角。"},{"en":"Printing kept the symbol sense alive, which is why a password has characters.","cn":"印刷让符号义活了下来，因此密码里也有「字符」。"},{"en":"The stage kept the role sense alive, which is why a novel has characters.","cn":"舞台让角色义活了下来，因此小说里也有人物。"}],"abstract":[{"en":"Picture a seal pressed into wet clay, leaving both a sign and a temper.","cn":"想象一枚印章按进湿泥，既留下记号，也留下脾气。"},{"en":"Picture a house that keeps its smell even after every room is repainted.","cn":"想象一栋房子每个房间都重刷过，气味却还在。"},{"en":"Picture a letter that can be read as a word or as a person.","cn":"想象一个字母，既可以被读成词，也可以被读成人。"}]},"examples":[{"en":"The old quarter still has the character of a fishing village.","cn":"老城区仍带着渔村的味道。"},{"en":"She is a woman of strong character and few words.","cn":"她是个骨气很强、话很少的人。"},{"en":"The file name cannot contain a slash character.","cn":"文件名不能包含斜杠字符。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"char（刻）+ acter——刻在身上的记号 → 性格、品格、字符","word":"character"},"root":"希腊 kharakter「刻下的印记、印章」，出自 kharassein「刻、划」，经拉丁与法语传入英语；词根在希腊语之前的来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: a mark is cut into a surface, and that mark is then read as a person's make-up, as moral hardness, as a role, as a written sign, as the temper of a place, as public standing, as vivid oddity and finally as a feature of a kind.","cn":"八个义项沿一个动作展开：一道记号被刻进表面，这道记号依次被读作一个人的构成、道德的硬度、一个角色、一个书写符号、一个地方的脾气、公众评价、鲜明的古怪，最后是一类事物的特性。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seal pressed into wet clay, leaving at once a sign and a temper.","cn":"核心意象：一枚印章按进湿泥，同时留下记号与脾气。"},"chain":["A MARK CUT IN","THE PERSON'S STAMP","WHAT WILL NOT WEAR OFF","A ROLE ON STAGE","A SIGN ON PAPER","THE TEMPER OF A PLACE"],"branches":[{"senses":"01 · 05","en":"THE STAMP ON A PERSON AND ON A PLACE: the same mark read on a human being, then on a street or a market.","cn":"盖在人身上与盖在地方上的章：同一印记先读在人身上，再读在街市上。"},{"senses":"02 · 06","en":"HARDNESS AND REPUTATION: what cannot be erased is first called fibre, then read off by others as standing.","cn":"硬度与名声：抹不掉的东西先被称为骨气，再被别人读成品行评价。"},{"senses":"03","en":"THE MARK AS A MASK: the stage keeps the sense of a marked role rather than a person.","cn":"印记作为面具：舞台保留的是被标记的角色，而不是真人。"},{"senses":"04","en":"THE MARK AS A SIGN: printing and computing keep the literal written stroke.","cn":"印记作为符号：印刷与计算机保留了字面的一笔。"},{"senses":"07 · 08","en":"A DEEP MARK AND A CLASS MARK: the stamp either makes a person memorable or identifies a whole kind.","cn":"深印记与类印记：这枚章要么让人记得住，要么标出整个类别。"}]},"affixes":{"intro":{"en":"A Greek noun of engraving carried through Latin and French, with a large English family built on its adjective and verb forms.","cn":"一个希腊「刻」名词经拉丁与法语传来，英语在它的形容词与动词形式上长出一大族词。"},"latinIntro":{"en":"Greek kharakter reached Latin unchanged in meaning; Latin and French then supplied the adjective and verb shapes that English extended.","cn":"希腊 kharakter 以原义进入拉丁；拉丁与法语随后提供形容词与动词形态，英语再加以延伸。"},"items":[{"word":"kharassein","structure":"kharassein (Greek verb, 'to engrave')","meaning":"to cut into, scratch, stamp","meaningCN":"刻入；划；压印","example":"The verb supplies the act of cutting a mark.","exampleCN":"这个动词提供刻下记号的动作。"},{"word":"kharakter","structure":"kharassein + -ter (instrument noun)","meaning":"an engraved mark, a stamp","meaningCN":"刻下的印记；印章","example":"The noun is the direct source of the English word.","exampleCN":"这个名词是英语这个词的直接来源。"},{"word":"character","structure":"kharakter, through Latin and French","meaning":"make-up; role; sign","meaningCN":"性格构成；角色；符号","example":"The street lost its character.","exampleCN":"这条街失去了自己的味道。"},{"word":"characteristic","structure":"character + -istic (adjective and noun)","meaning":"typical; a typical feature","meaningCN":"典型的；典型特征","example":"It is characteristic of the style.","exampleCN":"这是该风格的典型特征。"},{"word":"characterize","structure":"character + -ize (verb)","meaning":"to describe or mark the nature of","meaningCN":"刻画；以……为特征","example":"Critics characterize the book as a diary.","exampleCN":"评论者把这本书定性为日记。"},{"word":"characterization","structure":"characterize + -ation (action noun)","meaning":"the act of portraying a figure or a nature","meaningCN":"人物刻画；特征描述","example":"The characterization of the aunt is the best part.","exampleCN":"对姑妈的刻画是全篇最好的部分。"},{"word":"characterless","structure":"character + -less (without)","meaning":"having no distinctive quality","meaningCN":"无特色的；平淡的","example":"The new square feels characterless.","exampleCN":"新广场显得毫无特色。"},{"word":"characteristically","structure":"characteristic + -ally (adverb)","meaning":"in the way typical of someone","meaningCN":"典型地；一贯地","example":"He was characteristically late.","exampleCN":"他一如既往地迟到了。"}],"latinEntries":[{"word":"kharakter","structure":"Greek kharakter, kharakteros (noun)","meaning":"engraved mark, stamp","meaningCN":"刻下的印记；印章"},{"word":"character","structure":"Latin character, characteris (noun)","meaning":"mark, sign, nature","meaningCN":"记号；符号；性质"}],"derivatives":[{"word":"characteristic","pos":"adj./n.","zh":"典型的；特性"},{"word":"characterize","pos":"v.","zh":"刻画；以……为特征"},{"word":"characterization","pos":"n.","zh":"人物刻画；特征描述"},{"word":"characterless","pos":"adj.","zh":"无特色的"},{"word":"characteristically","pos":"adv.","zh":"典型地"}]}},{"word":"anxiety","ipa_uk":"/æŋˈzaɪəti/","ipa_us":"/æŋˈzaɪəti/","definition_zh":"焦虑；担心；忧虑；焦虑症；渴望做某事","definition_en":"a troubled, uneasy feeling about something uncertain, or a strong wish to do something","core_image":"胸口被一条看不见的带子收紧，呼吸还在，空间却越来越小","scene":"通知说明天出结果，那一夜他在床上翻来覆去，把已经检查过的邮件又打开了三次。The anxiety did not lift until the message finally arrived at dawn.","sceneCN":"这里 anxiety 指「对尚未确定之事的持续不安」（第 1 个义项：持续的不安感）；句意是那份焦虑直到天亮消息终于抵达才松开。图中可辨识物件：亮着的屏幕、翻乱的被子、停在发件箱的草稿。","pos":[{"tag":"n.","zh":"焦虑；担心；忧虑"},{"tag":"n. (medical)","zh":"焦虑症"},{"tag":"n. (eager desire)","zh":"渴望；急切想做某事"}],"collocations":[{"phrase":"anxiety about","zh":"对……的焦虑"},{"phrase":"anxiety disorder","zh":"焦虑症"},{"phrase":"a source of anxiety","zh":"焦虑的来源"},{"phrase":"anxiety levels","zh":"焦虑水平"},{"phrase":"with anxiety","zh":"带着焦虑"},{"phrase":"anxiety to please","zh":"急于讨好"}],"forms":[{"label":"复数","form":"anxieties"},{"label":"形容词形式","form":"anxious"},{"label":"副词形式","form":"anxiously"},{"label":"复合形容词","form":"anxiety-ridden"},{"label":"名词形式","form":"anxiousness"}],"derivatives":[{"word":"anxious","pos":"adj.","zh":"焦虑的；担心的；渴望的"},{"word":"anxiously","pos":"adv.","zh":"焦虑地；急切地"},{"word":"anxiousness","pos":"n.","zh":"焦虑；急切"},{"word":"anxiolytic","pos":"adj./n.","zh":"抗焦虑的 / 抗焦虑药"},{"word":"overanxious","pos":"adj.","zh":"过度焦虑的"}],"senses":[{"no":"01","title":"Unease about what is uncertain","titleCN":"对不确定之事的持续不安","definition":"a lingering troubled feeling caused by something not yet settled","definitionCN":"由尚未落定之事引起的、持续不散的困扰感","example":"The anxiety did not lift until the message arrived at dawn.","exampleCN":"那份焦虑直到天亮消息抵达才松开。","why":"the root verb means 'to choke or squeeze', so the feeling is pictured as a tightening that has no object to fight.","whyCN":"词根动词意为「勒紧、扼住」，因此这种感受被画成一种收紧，却没有可对抗的对象。"},{"no":"02","title":"Worry about a specific thing","titleCN":"对某件具体事情的担心","definition":"a concern attached to a named problem, such as money, health or exams","definitionCN":"针对某一被点名的问题的挂虑，如金钱、健康或考试","example":"Most of their anxiety is about the rent, not the future.","exampleCN":"他们的担心大多关于房租，而不是将来。","why":"the vague tightening acquires an object, and the plural then lets people count their worries one by one.","whyCN":"模糊的收紧有了对象，复数于是让人们能把忧虑一桩桩数出来。"},{"no":"03","title":"A clinical condition","titleCN":"临床意义上的病症","definition":"a disorder in which unease becomes persistent enough to disturb daily life","definitionCN":"不安持续到足以扰乱日常生活的一种障碍","example":"She was diagnosed with anxiety rather than depression.","exampleCN":"她被诊断为焦虑症，而不是抑郁症。","why":"medicine took the ordinary feeling and made it a diagnosis, which is why the word now appears in clinic names.","whyCN":"医学把这种日常感受变成一种诊断，因此这个词如今出现在门诊名称里。"},{"no":"04","title":"A strong wish to do something","titleCN":"急切想做某事的愿望","definition":"an eager or restless desire to act, often to please someone","definitionCN":"急切而不安的做事愿望，常是为了讨好某人","example":"He answered with an anxiety to be useful.","exampleCN":"他回答时带着一种急于有用的心情。","why":"the same squeezing can come from wanting as from fearing, and older English used it freely for eager desire.","whyCN":"同一种收紧既可能来自想要，也可能来自害怕，早期英语就自由地用它表示急切愿望。"},{"no":"05","title":"The thing that causes it","titleCN":"引起焦虑的那件事","definition":"a burden or issue that keeps producing unease, often named in the plural","definitionCN":"持续制造不安的负担或问题，常以复数出现","example":"Debt was the family's chief anxiety for a decade.","exampleCN":"债务是这家人十年来最大的忧虑来源。","why":"English often lets the name of a feeling stand for its cause, which is why one can 'have anxieties'.","whyCN":"英语常让感受的名称代替它的起因，因此人们会说「有若干忧虑」。"},{"no":"06","title":"A measurable state in research","titleCN":"研究中可测量的状态","definition":"a variable that questionnaires rate as trait or state anxiety","definitionCN":"问卷以特质焦虑或状态焦虑来评定的变量","example":"The scale separates state anxiety from trait anxiety.","exampleCN":"这个量表把状态焦虑与特质焦虑分开。","why":"psychology splits a passing reaction from a standing tendency, and the noun serves both slots.","whyCN":"心理学把一时的反应与长期的倾向分开，这个名词同时供两个位置使用。"},{"no":"07","title":"The body's tightening","titleCN":"身体上的收紧","definition":"the physical side: fast heart, shallow breath, restless limbs","definitionCN":"身体那一面：心跳加快、呼吸变浅、四肢不安","example":"The anxiety showed first in his hands, not in his words.","exampleCN":"那份焦虑先出现在他手上，而不是话里。","why":"the original image is bodily, so the word can name an event in the chest rather than a thought.","whyCN":"原本的意象就是身体的，因此这个词能命名胸腔里的一件事，而不是一个念头。"},{"no":"08","title":"Stage fright before others","titleCN":"在他人面前的怯场","definition":"the specific unease felt before speaking, performing or being judged","definitionCN":"在发言、表演或被评判之前感到的那种特定不安","example":"The anxiety before the first sentence was worse than the talk.","exampleCN":"说第一句之前的焦虑比整场讲话更难熬。","why":"public exposure is the clearest case of being squeezed by other people's eyes, so the word settled there.","whyCN":"当众暴露是被他人的目光勒住的最清楚例子，因此这个词在那里安了家。"}],"etymology":{"intro":{"en":"Anxiety comes from Latin anxietas 'distress, uneasiness', from anxius 'troubled', from angere 'to choke, squeeze'. It entered English in the sixteenth century, first as a word for physical distress. Dates are approximate.","cn":"anxiety 来自拉丁 anxietas「痛苦、不安」，出自 anxius「受困扰的」，再上溯 angere「勒紧、扼住」。16 世纪进入英语，最初指身体上的痛苦。年代均为约数。"},"items":[{"era":"LATIN ANGERE","en":"Angere meant 'to choke, strangle, squeeze'. Its deeper origin is not established; a link with the root behind anger is a hypothesis about an ancient source, not a claim that the English words are close relatives.","cn":"angere 意为「勒紧、扼住、挤压」。其更深来源未得到证明；它与 anger 背后的词根有关联，那是对远古来源的假说，并不意味着这两个英语词是近亲。"},{"era":"LATIN ANXIUS","en":"Anxius described a person squeezed by trouble; the adjective also named narrow places, since the same root gave angustus 'narrow'.","cn":"anxius 形容被困扰勒住的人；这个形容词也用于狭窄之处，因为同一词根还给了 angustus「狭窄」。"},{"era":"LATIN ANXIETAS","en":"The noun named a state of distress or tightness, without any modern psychological meaning.","cn":"这个名词指痛苦或紧绷的状态，完全没有现代心理学含义。"},{"era":"ENGLISH BORROWING","en":"English took the word in the sixteenth century, first for physical tightness and trouble, then for mental unease.","cn":"英语在 16 世纪借入这个词，先指身体的紧绷与痛苦，后指心理上的不安。"},{"era":"CLINICAL SENSE","en":"Twentieth-century psychiatry made anxiety the name of a disorder, and questionnaires turned it into a ratable variable.","cn":"20 世纪精神病学把焦虑变成一种障碍的名称，问卷又把它变成可评分的变量。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin history of angere is a reconstruction, and no exact first date is agreed for the psychological sense.","cn":"来源不确定：angere 在拉丁语之前的历史属重构形式，心理义的确切首见年代也没有公认结论。"}]},"similar":{"note":{"en":"Group one holds words that look or sound close but come from another history; group two holds the fear family, where the differences are matters of object and timing.","cn":"第一组是字形或读音接近、却出自另一段历史的词；第二组是恐惧类词，差别在于对象与时间。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"angina","ipa":"/ænˈdʒaɪnə/","tag":"same root, the chest","definition":"From the same verb of choking: a medical term for chest pain, showing how literal the squeezing image once was.","definitionCN":"同出那个「勒紧」的动词：指胸痛的医学术语，可见这个收紧意象当年多字面。"},{"word":"anguish","ipa":"/ˈæŋɡwɪʃ/","tag":"same root, sharper pain","definition":"From the Latin noun for narrowness and distress: severe suffering, usually with a cause already known.","definitionCN":"出自拉丁表「狭窄与痛苦」的名词：剧烈的痛苦，通常起因已经明确。"},{"word":"anger","ipa":"/ˈæŋɡə/","tag":"different road, related far back","definition":"Entered English from Old Norse angr 'grief'. The two words may share a very old root, but they reached English by separate roads and are not synonyms.","definitionCN":"从古诺尔斯语 angr「悲痛」进入英语。两者也许共享一个很古老的词根，但分别经不同路径进入英语，并非同义词。"},{"word":"anxious","ipa":"/ˈæŋkʃəs/","tag":"the adjective","definition":"The adjective of this noun, which also carries the separate sense of eager to do something.","definitionCN":"本名词的形容词形式，同时也带「急于做某事」这一独立义项。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fear","ipa":"/fɪə/","tag":"object present","definition":"A response to a recognised danger; anxiety is the same system running without a clear target.","definitionCN":"对已被认出的危险作出的反应；焦虑则是同一套系统在没有明确目标时运转。"},{"word":"worry","ipa":"/ˈwʌri/","tag":"thinking it over","definition":"The everyday word for repeated mental chewing on a problem; it is the activity, anxiety is the state.","definitionCN":"反复在心里咀嚼某个问题的日常词；它是活动，而焦虑是状态。"},{"word":"stress","ipa":"/stres/","tag":"pressure from outside","definition":"The load placed on a person by demands; anxiety is one possible response to that load.","definitionCN":"外界要求压在一个人身上的负荷；焦虑是对这种负荷的一种可能反应。"},{"word":"dread","ipa":"/dred/","tag":"future and heavy","definition":"Anticipation of something bad that is fairly specific and often unavoidable; it is darker and more directed.","definitionCN":"对相当具体、常无法回避的坏事的预期；更阴暗，也更有指向。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin root means 'to choke or squeeze', so the feeling is a band around the chest.","cn":"拉丁词根意为「勒紧、扼住」，因此这种感受是绕在胸口的一条带子。"},{"en":"The family runs anxiety, anxious, anxiously, anxiousness, anxiolytic, overanxious.","cn":"同族词包括 anxiety、anxious、anxiously、anxiousness、anxiolytic、overanxious。"},{"en":"Fixed phrases mark the uses: anxiety about, anxiety disorder, anxiety levels, anxiety to please.","cn":"固定搭配标出用法：对……的焦虑、焦虑症、焦虑水平、急于讨好。"},{"en":"The same root gives angina and anguish, both about tightness and pain.","cn":"同一词根给了 angina 与 anguish，都与紧绷和疼痛有关。"},{"en":"Distinguish it from fear: fear has an object, anxiety often does not.","cn":"要与表示恐惧的近义词区分：恐惧有目标，焦虑常常没有。"}],"abstract":[{"en":"Picture a band around the chest that tightens as the news gets closer.","cn":"想象一条绕在胸口的带子，消息越近就勒得越紧。"},{"en":"Picture a room that shrinks each time you check the clock.","cn":"想象一间屋子，你每看一次钟它就小一点。"},{"en":"Picture a door you keep opening although you know the corridor is empty.","cn":"想象一扇你明知走廊空着却仍反复打开的门。"}]},"examples":[{"en":"The anxiety about the results kept him awake.","cn":"对结果的焦虑让他睡不着。"},{"en":"She felt a mild anxiety before every phone call home.","cn":"每次往家里打电话前，她都有一点淡淡的不安。"},{"en":"The clinic treats anxiety and sleep problems together.","cn":"这家诊所把焦虑与睡眠问题一起治疗。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"anx（紧）+ iety——胸口被紧紧勒住的感觉 → 焦虑、忧虑","word":"anxiety"},"root":"拉丁 anxietas「痛苦、不安」，出自 anxius「受困扰的」，再上溯 angere「勒紧、扼住」；同一词根还给了 angustus「狭窄」、angina 与 anguish。","sensesIntro":{"en":"Eight senses follow one movement: a band tightens around the chest, and that tightening is then read as vague unease, as a named worry, as a diagnosis, as eager desire, as its own cause, as a measured variable, as a bodily event and finally as stage fright.","cn":"八个义项沿一个动作展开：一条带子勒紧胸口，这次收紧依次被读作模糊的不安、被点名的忧虑、一个诊断、急切的愿望、它自己的起因、一个被测量的变量、一件身体事件，最后是怯场。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible band around the chest that tightens while the breath continues and the space shrinks.","cn":"核心意象：一条看不见的带子绕在胸口，呼吸仍在，空间却越来越小。"},"chain":["THE BAND TIGHTENS","WITHOUT A TARGET","A NAMED WORRY","A DIAGNOSIS","EAGER WANTING","THE BODY'S SIDE"],"branches":[{"senses":"01 · 02","en":"VAGUE AND NAMED: the same tightening first floats without an object, then attaches to rent, health or an exam.","cn":"模糊与被点名：同一次收紧先无对象地飘着，再附到房租、健康或考试上。"},{"senses":"03 · 06","en":"FROM FEELING TO MEASUREMENT: medicine names it a disorder, then questionnaires score it as a variable.","cn":"从感受到测量：医学把它命名为障碍，问卷再把它打成变量。"},{"senses":"04","en":"THE SAME BAND PULLING FORWARD: wanting can tighten the chest as surely as fearing.","cn":"同一条带子向前拉：想要和害怕一样能把胸口勒紧。"},{"senses":"05","en":"THE BAND'S OWN CAUSE: English lets the feeling stand for the debt or the deadline that produces it.","cn":"带子自己的起因：英语让这种感受代替产生它的债务或期限。"},{"senses":"07 · 08","en":"THE BODY AND THE AUDIENCE: the event in the chest, and the version that arrives when others are watching.","cn":"身体与观众：胸腔里的事件，以及有别人看着时出现的那一版。"}]},"affixes":{"intro":{"en":"A Latin noun of tightness with its own adjective and verb behind it; the family is small but very regular.","cn":"一个拉丁「紧绷」名词，背后有自己的形容词与动词；词族不大却非常规则。"},"latinIntro":{"en":"Latin angere 'to choke' gives anxius, anxietas, angustus and angina; the same ancient source may lie behind the Norse word that became anger, by another road.","cn":"拉丁 angere「勒紧」衍生 anxius、anxietas、angustus、angina；同一个远古来源也许经另一条路径藏在变成 anger 的那个诺尔斯词背后。"},"items":[{"word":"angere","structure":"angere (Latin verb, third conjugation)","meaning":"to choke, squeeze, distress","meaningCN":"勒紧；扼住；使痛苦","example":"The verb supplies the bodily image of tightening.","exampleCN":"这个动词提供「收紧」的身体意象。"},{"word":"anxius","structure":"angere + -ius (adjective)","meaning":"troubled, squeezed, uneasy","meaningCN":"受困扰的；被勒住的；不安的","example":"The adjective first described a body in distress.","exampleCN":"这个形容词最初形容处于痛苦中的身体。"},{"word":"anxietas","structure":"anxius + -tas (abstract noun)","meaning":"distress, tightness of mind","meaningCN":"痛苦；心头的紧绷","example":"The noun is the direct source of the English word.","exampleCN":"这个名词是英语这个词的直接来源。"},{"word":"anxiety","structure":"anxietas, through French or directly","meaning":"unease about what is uncertain","meaningCN":"对不确定之事的不安","example":"The anxiety did not lift until dawn.","exampleCN":"那份焦虑直到天亮才松开。"},{"word":"anxious","structure":"anxiety + -ous, or from Latin anxius","meaning":"uneasy; eager","meaningCN":"不安的；急切的","example":"She was anxious about the reply.","exampleCN":"她为回信而不安。"},{"word":"anxiously","structure":"anxious + -ly (adverb)","meaning":"in an uneasy way","meaningCN":"不安地；急切地","example":"He waited anxiously by the door.","exampleCN":"他在门边不安地等着。"},{"word":"anxiolytic","structure":"anxiety + Greek lysis 'loosening'","meaning":"a drug that loosens anxiety","meaningCN":"缓解焦虑的药物","example":"The doctor prescribed an anxiolytic.","exampleCN":"医生开了一种抗焦虑药。"},{"word":"angustus","structure":"angere + -tus (adjective)","meaning":"narrow, tight","meaningCN":"狭窄的；紧的","example":"The same root also named narrow places.","exampleCN":"同一词根也用来命名狭窄之处。"},{"word":"angina","structure":"angere + -ina (noun)","meaning":"a choking pain, especially in the chest","meaningCN":"扼紧般的疼痛；心绞痛","example":"The medical term keeps the literal squeezing.","exampleCN":"这个医学术语保留了字面的「勒紧」。"}],"latinEntries":[{"word":"angere","structure":"angere, ango, anxi, anctum (verb)","meaning":"to choke, squeeze, torment","meaningCN":"勒紧；扼住；折磨"},{"word":"anxius","structure":"angere + -ius (adjective)","meaning":"troubled, uneasy","meaningCN":"受困扰的；不安的"},{"word":"anxietas","structure":"anxius + -tas (noun)","meaning":"distress, uneasiness","meaningCN":"痛苦；不安"},{"word":"angustus","structure":"angere + -tus (adjective)","meaning":"narrow, tight","meaningCN":"狭窄的；紧的"}],"derivatives":[{"word":"anxious","pos":"adj.","zh":"焦虑的；渴望的"},{"word":"anxiously","pos":"adv.","zh":"焦虑地；急切地"},{"word":"anxiousness","pos":"n.","zh":"焦虑；急切"},{"word":"anxiolytic","pos":"adj./n.","zh":"抗焦虑的 / 抗焦虑药"},{"word":"overanxious","pos":"adj.","zh":"过度焦虑的"}]}}]);
